/**
 * Assert a node kind is one this planner has decided. Called on every
 * dispatch; the throw names the kind and the AST version so a language
 * change breaks the build instead of becoming an accidental residual.
 * Exported so the throw itself is pinned by a test.
 * @param {any} node
 */
export function assertDecidedKind(node) {
  const kind = node?.kind;
  if (!DECIDED_KINDS.has(kind)) {
    throw new Error(
      `pushdown planner: unrecognised AST node kind '${String(kind)}' `
      + `(AST_VERSION ${AST_VERSION}) — the planner must be taught this construct`);
  }
}

// the exhaustiveness pact: if the engine adds a kind, this module
// fails to load until the planner decides it
for (const kind of NODE_KINDS) {
  if (!DECIDED_KINDS.has(kind)) {
    throw new Error(
      `pushdown planner: NODE_KINDS declares '${kind}' (AST_VERSION ${AST_VERSION}) `
      + 'but the planner has not decided it');
  }
}

/** Whether a literal window bound is one SQL takes as written: a
 * non-negative safe integer. A negative, fractional or non-finite bound
 * is the ENGINE's to interpret (it answers `[]`, a truncation or a
 * refusal), and interpolated into `LIMIT`/`OFFSET` it answered other
 * rows or a raw database error. */
function isWindowBound(value) {
  return Number.isSafeInteger(value) && value >= 0;
}

/** Whether an aggregate accumulates floating values: a sum or an average
 * over a member the schema does not type `integer`, or over an adopted
 * column whose codec is not `integer` however the schema types it. The
 * engine adds left to right in doubles; SQLite's compensated sum and
 * PostgreSQL's exact numeric sum round differently, so such an aggregate
 * stays the engine's.
 * @param {{ fn: string, ref: any }} entry @returns {boolean} */
function floatingAccumulation(entry) {
  const ref = entry.ref;
  return (entry.fn === 'sum' || entry.fn === 'avg')
    && (ref?.type !== 'integer' || (ref.codec !== undefined && ref.codec !== 'integer'));
}

/** Whether a schema node admits `null` beside its scalar type. A present
 * null orders and aggregates in SQL (NULLS FIRST, skipped by SUM) where
 * the engine refuses it (`JQ2005`, `JQ2001`), so a promotion over such a
 * path answers where the reference semantics throw. */
function admitsNull(schema, segments) {
  const node = schemaNodeAt(schema, segments);
  return Array.isArray(node?.type) && node.type.includes('null');
}

/**
 * How a reference reads a null the database holds, the one question every
 * rule about nulls asks: `'present'` when it reads back as a `null` member
 * (a column whose policy says so, whatever its schema type; a document
 * member whose type admits one, an epoch member included, which keeps its
 * string in the document), `'absent'` when it reads back as no member at all
 * (a column of any other policy whose type admits `null`: the engine sees an
 * empty sequence, as SQL sees an unknown), `'none'` when it holds none.
 * @param {any} ref
 * @param {any} schema
 * @returns {'present' | 'absent' | 'none'}
 */
function nullReading(ref, schema) {
  if (ref.nullPolicy === 'null') return 'present';
  if (!admitsNull(schema, ref.segments)) return 'none';
  return ref.flavor === 'entity-column' ? 'absent' : 'present';
}

/** Whether a schema node admits values of more than one comparable kind
 * (`['integer', 'string']`; `integer` and `number` are one kind). The
 * planner types such a member by its first type, so SQL would order the
 * values of the other type as no value at all, where the engine refuses
 * to compare the two (`JQ2005`).
 * @param {any} schema @param {import('./dialect.js').JsonPathSegment[]} segments
 * @returns {boolean} */
export function admitsMixedTypes(schema, segments) {
  const node = schemaNodeAt(schema, segments);
  if (!Array.isArray(node?.type)) return false;
  return new Set(node.type.filter((type) => type !== 'null')
    .map((type) => columnKindFor(type) ?? type)).size > 1;
}

const FAMILY_ORDER = ['number', 'text', 'boolean', 'null'];

/**
 * The JSON families a member can hold when the schema types it as
 * scalars alone — `string`, `number`, `integer` and `boolean`, each
 * optionally with `null` — or `null` when it types it as anything else
 * (an object, an array, or no type at all). A schema-conforming document
 * never holds an object or an array there, so two such members compare
 * by the family of their values and never by structure.
 * @param {any} schema
 * @param {import('./dialect.js').JsonPathSegment[]} segments
 * @returns {('number' | 'text' | 'boolean' | 'null')[] | null}
 */
export function scalarFamilies(schema, segments) {
  const declared = schemaNodeAt(schema, segments)?.type;
  const names = typeof declared === 'string' ? [declared] : declared;
  if (!Array.isArray(names) || names.length === 0) return null;
  const found = new Set();
  for (const name of names) {
    const family = name === 'null' ? 'null' : columnKindFor(name);
    if (family === undefined) return null;
    found.add(family);
  }
  return /** @type {any} */ (FAMILY_ORDER.filter((family) => found.has(family)));
}

/**
 * Whether a reference holds a scalar or nothing, as every key of a grouping
 * and every leaf of a distinct must: a string, a number, a boolean or `null`,
 * in any mix the schema declares. The database groups such a value by what it
 * is and by its JSON type, as the engine's equality does; an object or an
 * array it groups by its text, which keeps the order of its members and the
 * spelling of its numbers where the engine compares deeply. So the schema must
 * declare the type on the node the path reaches ({@link scalarFamilies}: a
 * union with an object or an array, a type that is not declared and a path the
 * schema does not reach all fail), and a negative index fails because it counts
 * from the end of the array, which no schema places.
 * @param {{ segments: import('./dialect.js').JsonPathSegment[] }} ref
 * @param {any} schema - the schema that types the reference
 * @returns {boolean}
 */
function holdsOnlyScalars(ref, schema) {
  return ref.segments.length > 0 && !countsFromTheEnd(ref) && scalarFamilies(schema, ref.segments) !== null;
}

/**
 * Whether a reference has a negative index, which counts from the end of an
 * array: the last element of a short tuple is a prefix item, so the schema
 * places no negative index through a tuple ({@link schemaNodeAt}).
 * @param {{ segments: import('./dialect.js').JsonPathSegment[] }} ref
 * @returns {boolean}
 */
function countsFromTheEnd(ref) {
  return ref.segments.some((segment) => 'index' in segment && segment.index < 0);
}

/**
 * Whether a string operator over a reference is left to the engine because it
 * can meet a subject that is not a string: a member of several kinds besides
 * `null` (`['string', 'integer']`), or a column whose policy reads a NULL back
 * as a present `null` ({@link nullReading}). A member typed `string` and
 * `null` alone stays native: a stored `null` there answers false where the
 * engine raises `JQ2001` (a named deviation, so a prefix search over the most
 * common nullable text shape keeps its index seek and its bounded cost).
 * @param {any} ref
 * @param {any} shape
 * @returns {boolean}
 */
function stringSubjectRaises(ref, shape) {
  if (ref.mixed === true) return true;
  return shape.entityFlavors?.get(canonicalOf(ref.segments))?.nullPolicy === 'null';
}

/** Why a statement with no engine path — a graph load, a native mutation —
 * refuses a predicate comparing a string that holds a lone surrogate. */
export const LONE_SURROGATE_REFUSAL = 'a string literal holding a lone surrogate reaches the database as '
  + 'U+FFFD, so the predicate would match the rows holding U+FFFD in its place, and this statement has '
  + 'no engine path to compare it as written; compare a well-formed string, or select the rows through '
  + 'execute(), which answers it in the engine';

/**
 * Whether a planned predicate binds a string literal that holds a lone
 * surrogate as the operand of a comparison or a string operator. A driver
 * encodes such a string as UTF-8 with U+FFFD in the surrogate's place, so
 * the database compares another string than the document names. A
 * membership list is bound as JSON text, whose escape SQLite decodes as it
 * decoded the stored document; that it is no value PostgreSQL holds is the
 * emitter's to say.
 * @param {any} pred
 * @returns {boolean}
 */
export function bindsLoneSurrogate(pred) {
  return bindsText(pred, (text, listed) => !listed && !text.isWellFormed());
}

/** Whether a reference holds a boolean: by its schema type, or by what its
 * column stores, whatever the schema claims of it. A boolean orders as 0/1
 * and folds as a number in SQL, and is `JQ2005`/`JQ2001` in the engine. */
function holdsBoolean(ref) {
  return ref.type === 'boolean' || ref.storage === 'boolean';
}

/** Whether a typed reference orders and folds natively: numbers and strings
 * of one type that cannot hold a null — in its schema type, or by its column's
 * policy, which reads a NULL back as a present `null` — and no boolean. A
 * caller that counts the NULLs its statement skipped (`countsNulls`) and
 * refuses the answer when it meets one also takes a column whose policy reads
 * a NULL as a present `null`, which the engine refuses in a fold the same way.
 * @param {any} ref @param {any} schema @param {boolean} [countsNulls] */
function orderable(ref, schema, countsNulls = false) {
  return ref.type !== 'unknown' && !holdsBoolean(ref)
    && (nullReading(ref, schema) === 'none' || (countsNulls && ref.nullPolicy === 'null'))
    && !admitsMixedTypes(schema, ref.segments);
}

/**
 * One named refusal: the construct that stayed behind and the cause,
 * drawn from {@link PLANNER_REASONS} so an explanation's vocabulary is
 * one closed set rather than prose invented at each site.
 * @param {string} construct
 * @param {string} reason
 * @returns {{ construct: string, reason: string }}
 */
function refusal(construct, reason) {
  return { construct, reason };
}

/**
 * A translated predicate that DECIDES: no pre-filter, nothing left for
 * a residual to refine.
 * @param {import('./algebra.js').PlanPredicate} pred
 */
function exactly(pred) {
  return { pred, exact: true, prefilters: [], refinements: [] };
}

// ————— Registered operators (Ring 2) —————
//
// A store may open with a registry (createJsltRegistry()) whose
// operators become engine vocabulary. Ring 2 treats every registered
// operator as CORRECT but UN-pushable: the planner must KNOW its name
// (so the AST analysis does not fail `JQ0002`) yet still route it to the
// residual, where the compilation carries the same `{ functions,
// extensions }`. Ring 3 will promote the pushable subset to SQL; here
// everything registered runs in JavaScript over the fetched rows.

/**
 * The analyze options carrying the store's registered operators. A
 * registered operator is engine vocabulary, so the AST analysis must be
 * told its `{ functions, extensions }` or it rejects the document as an
 * unknown operator. `null`/absent operators → `undefined`, so a store
 * without a registry analyses byte-identically to before.
 * @param {{ functions?: any, extensions?: any } | null | undefined} operators
 * @returns {any}
 */
function analyzeOptionsFor(operators) {
  if (operators == null) return undefined;
  /** @type {any} */
  const options = {};
  if (operators.functions !== undefined) options.functions = operators.functions;
  if (operators.extensions !== undefined) options.extensions = operators.extensions;
  return options;
}

/**
 * The set of registered first-class operator names (the `op`/`agg`
 * entries that appear as document keys), or `null` when none.
 * @param {{ extensions?: any } | null | undefined} operators
 * @returns {Set<string> | null}
 */
function registeredNamesOf(operators) {
  if (operators == null) return null;
  const names = new Set(Object.keys(operators.extensions ?? {}));
  return names.size === 0 ? null : names;
}

/**
 * Which registered operator names a raw document mentions (a `$`-key is
 * an operator call). Robust across where/return/root placement, since it
 * walks the document rather than the AST.
 * @param {any} document
 * @param {Set<string>} registered
 * @returns {string[]}
 */
function registeredOpsUsed(document, registered) {
  const found = new Set();
  const walk = (node) => {
    if (Array.isArray(node)) { for (const item of node) walk(item); return; }
    if (node !== null && typeof node === 'object') {
      for (const key of Object.keys(node)) {
        if (registered.has(key)) found.add(key);
        walk(node[key]);
      }
    }
  };
  walk(document);
  return [...found];
}

/**
 * Prepend an honest, named residual reason when a non-native plan used a
 * registered operator: `explain()` then says plainly that the operator
 * forced the residual, never silently. Native plans and no-registry
 * stores pass through untouched.
 * @param {any} planned - a planner result carrying `mode` and `reasons`
 * @param {any} document
 * @param {{ extensions?: any } | null | undefined} operators
 * @returns {any}
 */
function prependRegisteredReason(planned, document, operators) {
  if (planned.mode === 'native') return planned;
  const registered = registeredNamesOf(operators);
  if (registered === null) return planned;
  // only the part that actually runs in the residual can name an operator
  // as "residual": in `row` mode the where/order are pushed (a scalar
  // operator there may even be a Ring 3 UDF) and just the projection runs
  // per row; in `set` mode the whole document re-runs over the candidates
  const residualPart = planned.mode === 'row' ? planned.rowReturn : document;
  const used = registeredOpsUsed(residualPart, registered);
  if (used.length === 0) return planned;
  return {
    ...planned,
    reasons: [
      refusal(used.join(', '), OPERATOR_REASONS.registered(used)),
      ...planned.reasons,
    ],
  };
}

/**
 * Is this node the bare binding variable (the whole item)?
 * @param {any} node
 * @param {number} itSlot
 */
function isItVar(node, itSlot) {
  return node.kind === 'var' && node.external !== true && node.slot === itSlot;
}

/**
 * The typed segments of a singular member path rooted on the binding,
 * with the canonical spelling the physical mapping keys columns by.
 * `null` when the node is not such a path.
 * @param {any} node
 * @param {number} itSlot
 * @returns {{ segments: ({ name: string } | { index: number })[],
 *   canonical: string } | null}
 */
function memberPath(node, itSlot) {
  if (node.kind !== 'path' || node.external === true) return null;
  if (node.rootSlot !== itSlot || node.singular !== true) return null;
  /** @type {({ name: string } | { index: number })[]} */
  const segments = [];
  for (const segment of node.segments) {
    if (segment.descendant === true || segment.selectors.length !== 1) return null;
    const selector = segment.selectors[0];
    if (selector.kind === 'name') segments.push({ name: selector.name });
    else if (selector.kind === 'index') segments.push({ index: selector.index });
    else return null;
  }
  if (segments.length === 0) return null;
  return { segments, canonical: canonicalOf(segments) };
}

/**
 * The `wholeColumn` field of a reference: set where the member's column is
 * an untyped one over a member of several types, which holds the member as
 * the document does, whatever its type.
 * @param {any} shape - { anyKindColumns, columnByCanonical }
 * @param {string} canonical
 * @returns {{ wholeColumn?: true }}
 */
function wholeColumnOf(shape, canonical) {
  const column = shape.columnByCanonical.get(canonical);
  return column !== undefined && shape.anyKindColumns?.has(column) ? { wholeColumn: true } : {};
}

/**
 * A singular member path rooted on the binding → a PlanRef, or null.
 * @param {any} node
 * @param {number} itSlot
 * @param {any} shape - { schema, columnByCanonical }
 * @returns {import('./algebra.js').PlanRef | null}
 */
function pathRef(node, itSlot, shape) {
  const path = memberPath(node, itSlot);
  if (path === null) return null;
  return {
    segments: path.segments,
    type: typeOfPath(shape.schema, path.segments),
    column: shape.columnByCanonical.get(path.canonical) ?? null,
    // a member of several kinds: its column holds the first type's, and
    // answers a value of that kind alone, unless it is an untyped column
    // that holds the member as the document does (`wholeColumn`)
    ...(admitsMixedTypes(shape.schema, path.segments) ? { mixed: true } : {}),
    ...wholeColumnOf(shape, path.canonical),
    // a step a path engine may read off the other kind of container, in a
    // container the schema leaves open: a column spelled that way reads
    // the wrong member of a conforming document
    ...(unpinnedStep(shape.schema, path.segments) ? { unpinned: true } : {}),
  };
}

/**
 * A literal `$get` — `{ $get: [target, 'name'] }`, the runtime form of a
 * path leaf — as the member path it names. An object target yields its
 * member or nothing and every other target yields nothing, which is what
 * the name selector `target['name']` answers, so where the target is the
 * binding or a member the schema types `object` the call is that path and
 * every form that translates a path translates it. Any other `$get` (an
 * untyped target, a name that is no literal string) is returned as it is,
 * and so is one that feeds a string operator (`stringOperand`) unless the
 * member is typed `string` alone: the engine raises on a subject of
 * another kind, and a `$get` is not to join the spellings that answer.
 * @param {any} node
 * @param {number} itSlot
 * @param {any} shape
 * @param {boolean} stringOperand
 * @returns {any}
 */
function getAsPath(node, itSlot, shape, stringOperand) {
  if (node.kind !== 'op' || node.name !== '$get' || node.args.length !== 2) return node;
  const [target, key] = node.args;
  if (key.kind !== 'literal' || typeof key.value !== 'string') return node;
  const parent = isItVar(target, itSlot) ? { segments: [] } : memberPath(target, itSlot);
  if (parent === null || (parent.segments.length > 0
    && schemaNodeAt(shape.schema, parent.segments)?.type !== 'object')) return node;
  if (stringOperand) {
    const families = scalarFamilies(shape.schema, [...parent.segments, { name: key.value }]);
    if (families?.length !== 1 || families[0] !== 'text') return node;
  }
  const select = { descendant: false, selectors: [{ kind: 'name', name: key.value }] };
  return { kind: 'path', card: 2, name: target.name, rootSlot: itSlot, external: false, rootCard: 1,
    segments: [...(target.kind === 'path' ? target.segments : []), select], singular: true,
    docPath: node.docPath };
}

/** The predicate operators whose operands may be a literal `$get`. */
const GET_OPERANDS = new Set(['$exists', '$empty', ...COMPARISONS.keys(), ...STRING_OPS.keys()]);

/**
 * The predicate with every operand that is a literal `$get` over the
 * binding or an object-typed member replaced by its member path. A
 * collection's alone: an entity query assigns each conjunct to a binding
 * by the paths it reads and plans its own forms.
 * @param {any} node
 * @param {number} itSlot
 * @param {any} shape
 * @returns {any}
 */
function withGetPaths(node, itSlot, shape) {
  if (shape.entityFlavors !== undefined || !GET_OPERANDS.has(node.name)) return node;
  const stringOperand = STRING_OPS.has(node.name);
  const args = node.args.map((/** @type {any} */ arg) => getAsPath(arg, itSlot, shape, stringOperand));
  return args.some((/** @type {any} */ arg, /** @type {number} */ i) => arg !== node.args[i])
    ? { ...node, args } : node;
}

/**
 * A literal or external operand, or null.
 * @param {any} node
 * @returns {import('./algebra.js').PlanOperand | null}
 */
function operandOf(node) {
  if (node.kind === 'literal') return { lit: node.value };
  if (node.kind === 'var' && node.external === true) return { ext: node.name };
  return null;
}

/** @param {any} value */
function isScalarLiteral(value) {
  return value === null || typeof value === 'string'
    || typeof value === 'number' || typeof value === 'boolean';
}

// ————— Membership: `$eq` against a list —————
//
// `$eq` is a general comparison (QUERY-FORMAT §8.4): true when ANY item of
// one side equals any item of the other. Against a sequence of scalar
// literals (`{ $seq: [...] }`) or every item of an external
// (`'$ids[*]'`), a singular member is therefore a membership test — and
// so are the equalities of one member inside an `$or`, which the
// disjunction's regroup (`planDisjunction`) gathers into one. Each plans
// to ONE list predicate the emitter binds as one JSON value, whatever
// its length: a flat `OR` of n equalities is n nested expressions, which
// SQLite refuses past about a thousand.

/**
 * The list side of a membership comparison, or null: a `$seq` of scalar
 * literals, or an external's every item (`$x[*]`).
 * @param {any} node
 * @returns {{ list: any[] } | { ext: string } | null}
 */
function membershipOperand(node) {
  if (node.kind === 'op' && node.name === '$seq'
    && node.args.every((arg) => arg.kind === 'literal' && isScalarLiteral(arg.value)))
    return { list: node.args.map((arg) => arg.value) };
  if (node.kind === 'path' && node.external === true && node.singular !== true
    && node.segments.length === 1 && node.segments[0].descendant !== true
    && node.segments[0].selectors.length === 1 && node.segments[0].selectors[0].kind === 'wildcard')
    return { ext: node.name };
  return null;
}

/**
 * The membership plan for one member and one list. String and number
 * items bind as the list; a `null` or a boolean in it is the type test
 * `$eq` against that literal already plans (a present null, a present
 * boolean), composed by `or`. An empty list matches nothing.
 * @param {import('./algebra.js').PlanRef} ref
 * @param {{ list: any[] } | { ext: string }} operand
 */
function membershipPlan(ref, operand) {
  if ('ext' in operand) return exactly({ p: 'in', ref, operand });
  const scalars = [...new Set(operand.list.filter((value) => typeof value === 'string' || typeof value === 'number'))];
  const typeNames = [...new Set(operand.list.filter((value) => value === null || typeof value === 'boolean')
    .map((value) => (value === null ? 'null' : value ? 'true' : 'false')))];
  /** @type {any[]} */
  const items = [];
  if (scalars.length > 0) items.push({ p: 'in', ref, operand: { list: scalars } });
  for (const typeName of typeNames) items.push({ p: 'typeIs', ref, types: [typeName], positive: true });
  if (items.length === 0) return exactly({ p: 'const', value: false });
  return exactly(items.length === 1 ? items[0] : { p: 'or', items });
}

/**
 * `$eq` between a singular member and a list, in either order — or null.
 * @param {any[]} args @param {number} itSlot @param {any} shape
 */
function planMembership(args, itSlot, shape) {
  const [left, right] = args;
  for (const [member, list] of [[left, right], [right, left]]) {
    const ref = pathRef(member, itSlot, shape);
    const operand = ref === null ? null : membershipOperand(list);
    if (ref !== null && operand !== null) return membershipPlan(ref, operand);
  }
  return null;
}

/**
 * The group a translated item of a disjunction regroups into, or null:
 * an exact comparison of one member with a finite number or a
 * well-formed string literal — an equality (one group per member), or
 * a ray (one group per member, JSON type and direction; the planned
 * operator already carries the direction of a literal that stood on
 * the left). A boolean or null became a type test, an external or a
 * list carries no literal, and a promotion carries a pre-filter: none
 * of them regroups. Nor does a literal no bound can carry exactly —
 * an infinity has no JSON spelling (NaN never gets here: it is answered
 * where it is planned) and a lone surrogate is no JSON text — or an equality
 * on an instant column, whose own comparison narrows the column's
 * index by an epoch range that one list of document strings cannot
 * (its rays still fold: the folded bound keeps that range).
 * @param {any} outcome - a translated predicate
 * @param {any} shape - the binding's shape; an entity's names its flavors
 * @returns {string | null}
 */
function regroupKey(outcome, shape) {
  const pred = outcome.pred;
  if (pred.p !== 'cmp' || pred.op === 'ne' || !('lit' in pred.operand)
    || outcome.prefilters.length > 0 || outcome.refinements.length > 0) return null;
  const lit = pred.operand.lit;
  const type = typeof lit;
  if (type === 'number' ? !Number.isFinite(lit) : type !== 'string' || !lit.isWellFormed()) return null;
  const member = canonicalOf(pred.ref.segments);
  if (pred.op !== 'eq') return `${member}\n${type}\n${pred.op === 'gt' || pred.op === 'ge' ? '>' : '<'}`;
  return shape.entityFlavors?.get(member)?.flavor === 'entity-epoch' ? null : member;
}

/**
 * One group's translation: a lone item as it was; two or more
 * equalities as ONE membership list; two or more rays as ONE bound —
 * the least lower or the greatest upper by the engine's own order
 * (numbers by value, strings by code point: `compareJsonScalarLt`,
 * never JavaScript's `<`), the inclusive operator winning a tie.
 * @param {{ ref: any, members: any[] }} group
 * @returns {any}
 */
function foldGroup(group) {
  const members = group.members;
  if (members.length === 1) return members[0];
  if (members[0].pred.op === 'eq')
    return membershipPlan(group.ref, { list: members.map((outcome) => outcome.pred.operand.lit) });
  const lower = members[0].pred.op === 'gt' || members[0].pred.op === 'ge';
  let best = members[0].pred;
  for (let i = 1; i < members.length; i++) {
    const pred = members[i].pred;
    const [a, b] = lower ? [pred.operand.lit, best.operand.lit] : [best.operand.lit, pred.operand.lit];
    if (compareJsonScalarLt(a, b) || (!compareJsonScalarLt(b, a) && (pred.op === 'ge' || pred.op === 'le')))
      best = pred;
  }
  return members.find((outcome) => outcome.pred === best);
}

/**
 * A disjunction, regrouped by member. The normalizer hands the planner
 * a flat `$or` (a nest of `$or`s is one call, its items in order), and
 * every item is translated on its own first: one the planner refuses
 * refuses the whole `$or` — a general comparison never raises, so no
 * group could hide an error the engine would have reported. The exact
 * literal comparisons then regroup ({@link regroupKey}): same-member
 * equalities into one list (strings and numbers together — the emitter
 * compares each kind by its own guarded branch), same-member rays of
 * one JSON type and one direction into one bound ({@link foldGroup}).
 * A group stands where its first item stood; everything else keeps its
 * order. Mixed types, opposite directions and other members never
 * share a bound, and an `$or` is never split between the statement and
 * the engine.
 * @param {any[]} args - the `$or`'s items
 * @param {number} itSlot
 * @param {any} shape
 * @returns {any}
 */
function planDisjunction(args, itSlot, shape) {
  /** @type {any[]} a translated item, or the group standing in its first item's place */
  const slots = [];
  /** @type {Map<string, { ref: any, members: any[] }>} */
  const groups = new Map();
  for (const arg of args) {
    const outcome = planPredicate(arg, itSlot, shape);
    if ('refusal' in outcome) return outcome;
    const key = regroupKey(outcome, shape);
    if (key === null) {
      slots.push(outcome);
      continue;
    }
    let group = groups.get(key);
    if (group === undefined) {
      group = { ref: outcome.pred.ref, members: [] };
      groups.set(key, group);
      slots.push(group);
    }
    group.members.push(outcome);
  }
  const outcomes = slots.map((slot) => ('members' in slot ? foldGroup(slot) : slot));
  if (outcomes.length === 1) return outcomes[0];
  // an implied child makes the composition a SUPERSET either way, so
  // it still narrows honestly — it just stops deciding
  const refinements = outcomes.flatMap((outcome) => outcome.refinements);
  return { pred: { p: 'or', items: outcomes.map((outcome) => outcome.pred) },
    exact: refinements.length === 0,
    prefilters: outcomes.flatMap((outcome) => outcome.prefilters), refinements };
}


// ————— Spatial promotions: the implied conjunct —————
//
// Every other conjunct the planner pushes is a conjunct OF the document:
// it translates exactly or it does not. A spatial predicate cannot be
// translated exactly — there is no `ST_Within` in SQLite and this
// package does not build one — but it IMPLIES one that can be, over the
// derived columns a model declares (`indexes[].derive`): a bounding-box
// overlap, or a geohash-cell range.
//
// An IMPLIED conjunct narrows; it never decides. Three properties make
// that safe, and each is asserted by test:
//
//  1. No false negatives — every row the document's predicate keeps
//     passes the implied one. The proof per rule is in ARCHITECTURE.md's
//     truth table. A row with no derived value at all is not an
//     exception: the box is missing in exactly the cases §8.14's
//     representative position is, so the engine answers false for it
//     too. What a pre-filter DOES change is which rows can raise —
//     one it excludes never reaches the engine — and that is why the
//     precondition below is a schema one.
//  2. Idempotent refinement — the residual re-runs the ORIGINAL
//     predicate over the narrowed candidates, so the answer is the
//     engine's. That is why an implied conjunct forces the SET residual
//     rather than the row one.
//  3. `strict: true` refuses it — an implied conjunct leaves its own
//     reason behind, so the plan is not native and `JD0010` names it.
//
// A promotion reads a member the schema types as an array or an object.
// That precondition is the string operators' rule again: §8.14 answers
// `JQ2001` for a non-geographic operand, so on a member the schema does
// not type as geography a pushed filter could silently answer where the
// engine would throw.

/** The geographic schema types a spatial promotion is allowed over. */
const GEO_TYPES = new Set(['array', 'object']);

/**
 * Does the schema type this member as geography and ONLY as geography?
 * A union of `array` and `object` is the natural declaration for a
 * §8.14 operand (a bare position or a geometry); one that also admits
 * `null` is not, because §8.14 answers `JQ2001` for a `null` operand
 * while a pushed filter would simply not see the row.
 * @param {any} node - a subschema, or `undefined`
 * @returns {boolean}
 */
function isGeographicSchema(node) {
  const declared = node?.type;
  if (typeof declared === 'string') return GEO_TYPES.has(declared);
  return Array.isArray(declared) && declared.length > 0
    && declared.every((type) => GEO_TYPES.has(type));
}

/** `$geohash`'s default precision (QUERY-FORMAT §8.14). */
const GEOHASH_DEFAULT_PRECISION = 9;

/**
 * The interval promotion's reasons. `$overlaps` is §8.16's half-open
 * interval test, and the same rule the spatial promotions live under
 * applies to it: a pre-filter narrows, it never decides, and it may
 * never exclude a row the engine would have RAISED on.
 */
const INTERVAL_REASONS = {
  overlap: 'a half-open bound pre-filter is pushed over the declared interval columns; '
    + 'the exact overlap refines in the engine',
  operands: '$overlaps translates only with one member path and one literal interval',
  probe: 'the literal interval is not a half-open span of two instants '
    + '(the engine ERRORS on an empty or reversed one, whatever the row holds)',
  notInterval: 'the schema does not type the member as an object whose start and end are '
    + 'both REQUIRED and both numeric (a bound the engine ERRORS on must not be '
    + 'silently filtered away)',
  noColumns: 'the interval bounds are not both declared columns (declare an index over '
    + 'each of them)',
};

const SPATIAL_REASONS = {
  within: 'a bounding-box pre-filter is pushed; exact containment refines in the engine',
  distance: 'a geodesic-circle box pre-filter is pushed; the exact distance refines in the engine',
  prefix: "a cell-range pre-filter over the derived column's precision is pushed; "
    + 'the longer prefix refines in the engine',
  membership: 'the cell pre-filter retains unbounded members; the engine preserves '
    + 'the membership error when its search item is empty',
  noIndex: 'no derived spatial index on this member covers the predicate '
    + '(declare indexes[].derive on it)',
  notGeographic: 'spatial predicates translate only over a member the schema types as an '
    + 'array or an object (the engine ERRORS on a non-geographic operand)',
  operand: 'a spatial predicate translates only against a literal value or an external',
  unbounded: 'the probe has no bounding box, so no conservative pre-filter exists',
  pole: 'the circle reaches a pole, where a box has no longitude bound at all — '
    + 'pushing nothing is correct, pushing a wrong box is not',
  wrapped: 'the circle crosses the antimeridian, and a box that crosses it would need two '
    + 'disjuncts this suite\'s box convention does not carry — '
    + 'pushing nothing is correct, pushing a wrong box is not',
  precision: "the cell length must match the derived column's precision",
  rtreeBox: "the box is stored in an R*Tree, whose coordinates are 32-bit floats rounded "
    + 'OUTWARD, so the stored box is a superset of the row\'s; the exact box test refines '
    + 'in the engine',
  radius: 'a distance bound is a finite, non-negative number of metres',
  unboundedFar: 'only a BOUNDED distance is promoted; no box narrows "farther than r"',
};

/**
 * The constant value an AST subtree denotes, or `null` when it denotes
 * anything else. A literal GeoJSON region in a document is NOT a
 * `literal` node — it is the object/array constructor tree the engine
 * builds from the same members — so the planner folds it here to get
 * the value it must compute a probe box from.
 * @param {any} node
 * @returns {{ value: any } | null}
 */
function constantOf(node) {
  if (node.kind === 'literal') return { value: node.value };
  if (node.kind === 'array') {
    const value = [];
    for (const element of node.elements) {
      const item = constantOf(element);
      if (item === null) return null;
      value.push(item.value);
    }
    return { value };
  }
  if (node.kind === 'object') {
    /** @type {any} */
    const value = {};
    for (const entry of node.entries) {
      if (typeof entry.name !== 'string') return null;
      const member = constantOf(entry.expr);
      if (member === null) return null;
      value[entry.name] = member.value;
    }
    return { value };
  }
  return null;
}

/**
 * The derived columns one `(member, derivation)` pair maps to, or
 * `null` when the collection declares no such index. The identity is
 * the same one the physical mapping keys its column set by — path,
 * kind AND precision — so a query at a different precision finds no
 * column rather than the wrong one.
 * @param {any} shape
 * @param {string} canonical
 * @param {'geohash' | 'bbox'} derive
 * @param {number} [precision]
 * @returns {string | { w: string, s: string, e: string, n: string } | null}
 */
/**
 * The R\*Tree virtual table a `bbox` column set is realized as, or
 * `null` when it is realized as four columns under a B-tree — which is
 * also the answer on a driver whose build carries no R\*Tree module,
 * because the physical plan already fell back there (MODEL-FORMAT §4).
 * @param {any} shape
 * @param {string} canonical
 * @returns {{ name: string, columns: string[] } | null}
 */
function rtreeTableOf(shape, canonical) {
  const stem = shape.columnByCanonical?.get(`${canonical}|bbox|`);
  if (stem === undefined) return null;
  return shape.virtualByStem?.get(stem) ?? null;
}

/**
 * The pushed box conjunct for one column set, under whichever physical
 * mapping the collection declares — the same box either way, because
 * the implied-conjunct proof is a proof about BOXES and not about SQL.
 *
 * Under `'rtree'` it is a `rowid` subquery over the virtual table: a
 * conjunct on the collection table, so the `FROM` clause, the residual
 * machinery and `prefilters` are all untouched. A join would be 6 %
 * faster and would need join support the emitter does not have; a
 * correlated `EXISTS` defeats the virtual table's index entirely and is
 * 85x worse than the subquery.
 * @param {{ w: string, s: string, e: string, n: string }} columns
 * @param {{ name: string, columns: string[] } | null} virtual
 * @param {any} probe
 * @returns {{ pred: any, via: 'columns' | 'rtree', columns: string[],
 *   inexact: boolean }}
 */
function boxConjunct(columns, virtual, probe) {
  if (virtual === null) {
    return { pred: { p: 'bboxOverlap', columns, probe },
      via: 'columns', columns: boxColumnList(columns), inexact: false };
  }
  return { pred: { p: 'bboxRtree', table: virtual.name, columns: virtual.columns, probe },
    via: 'rtree', columns: [...virtual.columns], inexact: true };
}

function derivedColumnsOf(shape, canonical, derive, precision) {
  // `precision` is the identity's third component: a geohash column's
  // precision, a vector column's `dims`
  const stem = shape.columnByCanonical?.get(`${canonical}|${derive}|${precision ?? ''}`);
  if (stem === undefined) return null;
  if (derive === 'geohash' || derive === 'vector') return stem;
  /** @type {any} */
  const columns = {};
  for (const component of BBOX_COMPONENTS) columns[`${component}`] = `${stem}_${component}`;
  return columns;
}

/**
 * The vector columns declared over one canonical path, by width. The
 * identity key is `<canonical>|vector|<dims>`, so one path may carry
 * one column per declared width and a probe chooses by its own.
 * @param {any} shape
 * @param {string} canonical
 * @returns {{ column: string, dims: number }[]}
 */
function vectorColumnsOf(shape, canonical) {
  const prefix = `${canonical}|vector|`;
  const found = [];
  for (const [key, column] of shape.columnByCanonical ?? []) {
    if (key.startsWith(prefix))
      found.push({ column, dims: Number(key.slice(prefix.length)) });
  }
  return found;
}

/**
 * A spatial SUBJECT: a singular member path on the binding that the
 * schema types as geography. Answers the canonical path a derived
 * column set is looked up by, or a named refusal.
 * @param {any} node
 * @param {number} itSlot
 * @param {any} shape
 * @param {string} construct
 * @returns {{ canonical: string } | { refusal: { construct: string, reason: string } }}
 */
function spatialSubject(node, itSlot, shape, construct) {
  const path = memberPath(node, itSlot);
  if (path === null || !isGeographicSchema(schemaNodeAt(shape.schema, path.segments)))
    return { refusal: refusal(construct, SPATIAL_REASONS.notGeographic) };
  return { canonical: path.canonical };
}

/** A promotion outcome: a pushed predicate that may still need refining. */
function promotion(pred, prefilter, refinements = []) {
  return { pred, exact: refinements.length === 0, prefilters: [prefilter], refinements };
}

/** The four bbox columns in the order the declared index covers them. */
function boxColumnList(columns) {
  return BBOX_INDEX_ORDER.map((component) => columns[component]);
}

/**
 * P1/P2 — a box predicate over a `bbox`-derived index.
 *
 * `$bbox-intersects(path, probe)` is EXACT: the derived columns ARE the
 * row's box, so overlap is fully decidable in SQL. `<=`/`>=` and not
 * `<`/`>` because the kernel counts touching edges as intersecting.
 *
 * `$within(path, area)` is IMPLIED by the same overlap: the subject's
 * representative position lies inside its own box (a bare position IS
 * the box; a centroid is a mean of positions and a mean lies within
 * their min/max), and inside the area's surface implies inside the
 * area's box — so the two boxes share at least that position.
 * @param {any} node
 * @param {number} itSlot
 * @param {any} shape
 * @returns {any}
 */
function planBoxPredicate(node, itSlot, shape) {
  const construct = node.name;
  const symmetric = construct === '$bbox-intersects';
  // `$within` asks whether the FIRST value is inside the second, so only
  // the first may be the row; box overlap is symmetric, so either may be
  let subjectAt = 0;
  if (symmetric && memberPath(node.args[0], itSlot) === null
    && memberPath(node.args[1], itSlot) !== null) subjectAt = 1;
  const subject = spatialSubject(node.args[subjectAt], itSlot, shape, construct);
  if ('refusal' in subject) return subject;
  const columns = derivedColumnsOf(shape, subject.canonical, 'bbox');
  if (columns === null) return { refusal: refusal(construct, SPATIAL_REASONS.noIndex) };

  const probeNode = node.args[subjectAt === 0 ? 1 : 0];
  /** @type {any} */
  let probe = null;
  if (probeNode.kind === 'var' && probeNode.external === true) {
    // a GeoJSON object is not a value any database binds, so its four
    // box edges bind instead — computed at bind time from the same
    // kernel the stored columns were computed with
    probe = { ext: probeNode.name };
  }
  else {
    const constant = constantOf(probeNode);
    if (constant === null) return { refusal: refusal(construct, SPATIAL_REASONS.operand) };
    const box = probeBox(constant.value);
    if (box === null) return { refusal: refusal(construct, SPATIAL_REASONS.unbounded) };
    probe = { box };
  }
  const conjunct = boxConjunct(columns, rtreeTableOf(shape, subject.canonical), probe);
  // `$bbox-intersects` is EXACT over the four columns — they ARE
  // `B(row)` — and only IMPLIED over an R*Tree, whose 32-bit float
  // coordinates round outward: the stored box is a superset. No false
  // negatives either way, which is what the pushdown needs; but a superset does
  // not DECIDE, so the exact box test keeps its refinement and
  // `strict: true` is JD0010 where the column mapping ran native
  const exact = construct === '$bbox-intersects' && !conjunct.inexact;
  const refinements = construct === '$bbox-intersects'
    ? (conjunct.inexact ? [refusal(construct, SPATIAL_REASONS.rtreeBox)] : [])
    : [refusal('$within', SPATIAL_REASONS.within)];
  return promotion(conjunct.pred,
    { construct, via: conjunct.via, columns: conjunct.columns, exact }, refinements);
}

/**
 * P3 — a BOUNDED `$distance` is implied by the box of its circle.
 *
 * Recognized: `{$le|$lt: [{$distance: [path, probe]}, r]}` and the
 * mirrored `{$ge|$gt: [r, {$distance: …}]}`. A "farther than r"
 * predicate is deliberately NOT promoted: no box narrows it.
 *
 * The box comes from `circleBounds` on the same sphere and the same
 * `EARTH_RADIUS` the engine's `$distance` measures with, so the two
 * cannot disagree by model rather than by rounding — there is no
 * padding constant here, because no honest value could be chosen for
 * one. Two refusals instead: a circle reaching a pole has no longitude
 * bound at all, and one crossing the antimeridian would need two
 * disjoint boxes this suite's box convention cannot carry.
 * @param {any} node
 * @param {number} itSlot
 * @param {any} shape
 * @returns {any}
 */
function planDistanceBound(node, itSlot, shape) {
  const op = COMPARISONS.get(node.name);
  const upperOnLeft = op === 'le' || op === 'lt';
  const distanceNode = upperOnLeft ? node.args[0] : node.args[1];
  const radiusNode = upperOnLeft ? node.args[1] : node.args[0];
  const radius = constantOf(radiusNode);
  const radiusExternal = radiusNode.kind === 'var' && radiusNode.external === true;
  if (!radiusExternal && (radius === null || typeof radius.value !== 'number'))
    return { refusal: refusal('$distance', SPATIAL_REASONS.operand) };

  let subjectAt = 0;
  if (memberPath(distanceNode.args[0], itSlot) === null
    && memberPath(distanceNode.args[1], itSlot) !== null) subjectAt = 1;
  const subject = spatialSubject(distanceNode.args[subjectAt], itSlot, shape, '$distance');
  if ('refusal' in subject) return subject;
  const columns = derivedColumnsOf(shape, subject.canonical, 'bbox');
  if (columns === null) return { refusal: refusal('$distance', SPATIAL_REASONS.noIndex) };

  const probeNode = distanceNode.args[subjectAt === 0 ? 1 : 0];
  const constant = constantOf(probeNode);
  const centreExternal = probeNode.kind === 'var' && probeNode.external === true;
  if (!centreExternal && constant === null)
    return { refusal: refusal('$distance', SPATIAL_REASONS.operand) };
  if (!radiusExternal && (!Number.isFinite(radius.value) || radius.value < 0)) {
    return { refusal: refusal('$distance', SPATIAL_REASONS.radius) };
  }
  let probe;
  if (centreExternal || radiusExternal) {
    // Both inputs belong to one closed derived slot. Bind-time failure
    // diverts the whole query, preserving the engine's errors and the
    // candidates on the far side of a pole or the antimeridian.
    probe = { circle: {
      centre: centreExternal ? { external: probeNode.name } : { literal: constant.value },
      radius: radiusExternal ? { external: radiusNode.name } : { literal: radius.value },
    } };
  }
  else {
    const at = probePosition(constant.value);
    if (at === null) return { refusal: refusal('$distance', SPATIAL_REASONS.unbounded) };
    const box = probeCircleBox(at, radius.value);
    if (box === null) return { refusal: refusal('$distance', SPATIAL_REASONS.pole) };
    if (box[0] < -180 || box[2] > 180)
      return { refusal: refusal('$distance', SPATIAL_REASONS.wrapped) };
    probe = { box };
  }

  const conjunct = boxConjunct(columns, rtreeTableOf(shape, subject.canonical), probe);
  return promotion(conjunct.pred,
    { construct: '$distance', via: conjunct.via, columns: conjunct.columns, exact: false },
    [refusal('$distance', SPATIAL_REASONS.distance)]);
}

/**
 * The `(canonical, precision)` a `$geohash` call over the binding
 * denotes, or a refusal. The precision must be a literal — it decides
 * WHICH column the derivation maps to.
 * @param {any} node
 * @param {number} itSlot
 * @param {any} shape
 * @param {string} construct
 * @returns {any}
 */
function geohashDerivation(node, itSlot, shape, construct) {
  if (node.kind !== 'op' || node.name !== '$geohash')
    return { refusal: refusal(construct, SPATIAL_REASONS.operand) };
  let precision = GEOHASH_DEFAULT_PRECISION;
  if (node.args.length > 1) {
    const declared = constantOf(node.args[1]);
    if (declared === null || !Number.isInteger(declared.value)
      || declared.value < PRECISION_MIN || declared.value > PRECISION_MAX)
      return { refusal: refusal(construct, SPATIAL_REASONS.operand) };
    precision = declared.value;
  }
  const subject = spatialSubject(node.args[0], itSlot, shape, construct);
  if ('refusal' in subject) return subject;
  const column = derivedColumnsOf(shape, subject.canonical, 'geohash', precision);
  if (column === null) return { refusal: refusal(construct, SPATIAL_REASONS.noIndex) };
  return { column: /** @type {string} */ (column), precision };
}

/**
 * P4, bucketing — `{$starts-with: [{$geohash: [path, k]}, "cell"]}` over
 * a `geohash` index declared at exactly `k`. The column HOLDS the k-
 * character cell, so a prefix test on the expression is a prefix test
 * on the column: exact while the literal is no longer than k, and
 * merely implied beyond it, where the column can only confirm its own
 * first k characters.
 *
 * A prefix range is sargable (the index seeks it); `LIKE` and `substr`
 * both scan.
 * @param {any} node
 * @param {number} itSlot
 * @param {any} shape
 * @returns {any}
 */
function planCellPrefix(node, itSlot, shape) {
  const derivation = geohashDerivation(node.args[0], itSlot, shape, '$starts-with');
  if ('refusal' in derivation) return derivation;
  const pattern = constantOf(node.args[1]);
  if (pattern === null || typeof pattern.value !== 'string' || pattern.value === '')
    return { refusal: refusal('$starts-with', SPATIAL_REASONS.operand) };
  const exact = pattern.value.length <= derivation.precision;
  const cell = exact ? pattern.value : pattern.value.slice(0, derivation.precision);
  // a pattern as long as the column's own cell is an EQUALITY on it;
  // a shorter one is a half-open range, which the index seeks
  const pred = cell.length === derivation.precision
    ? { p: 'cellIn', column: derivation.column, cells: [cell] }
    : { p: 'cellPrefix', column: derivation.column, prefix: cell };
  return promotion(pred,
    { construct: '$starts-with', via: 'columns', columns: [derivation.column], exact },
    exact ? [] : [refusal('$starts-with', SPATIAL_REASONS.prefix)]);
}

/**
 * P4, proximity — the nine-cell probe, promoted to a membership
 * test over one column. The single-cell version misses a point ten metres
 * away across a cell edge, so a single prefix is BUCKETING and only the
 * neighbourhood is proximity; this is the shape §8.14 publishes with
 * the cells inline, where the planner can see them.
 *
 * Recognized: `{$exists: {$index-of: [{$geohash-neighbours: "cell"},
 * {$geohash: [path, k]}]}}`. Admitted only when the cell's length IS k —
 * the membership test compares whole strings, so any other length makes
 * the document's own predicate constantly false and the promotion would
 * be answering a different question. Unbounded rows remain candidates:
 * the engine's membership raises on an empty search item, so the original
 * predicate must still run even when the column covers whole cell strings.
 * @param {any} node
 * @param {number} itSlot
 * @param {any} shape
 * @returns {any}
 */
function planCellNeighbourhood(node, itSlot, shape) {
  const membership = node.args[0];
  const neighbours = membership.args[0];
  const cell = constantOf(neighbours.args[0]);
  if (cell === null || typeof cell.value !== 'string' || cell.value === '')
    return { refusal: refusal('$geohash-neighbours', SPATIAL_REASONS.operand) };
  const derivation = geohashDerivation(membership.args[1], itSlot, shape, '$geohash-neighbours');
  if ('refusal' in derivation) return derivation;
  if (cell.value.length !== derivation.precision)
    return { refusal: refusal('$geohash-neighbours', SPATIAL_REASONS.precision) };
  const cells = cellNeighbourhood(cell.value);
  if (cells.length === 0)
    return { refusal: refusal('$geohash-neighbours', SPATIAL_REASONS.operand) };
  return promotion({ p: 'cellIn', column: derivation.column, cells, keepEmpty: true },
    { construct: '$geohash-neighbours', via: 'columns', columns: [derivation.column],
      exact: false }, [refusal('$geohash-neighbours', SPATIAL_REASONS.membership)]);
}

/** Error candidates cannot be discarded by a different pushed conjunct. */
function neighbourhoodErrorColumns(node, itSlot, shape, columns = new Set()) {
  if (node === null || typeof node !== 'object') return columns;
  if (node.kind === 'op' && node.name === '$index-of'
    && node.args[0]?.name === '$geohash-neighbours') {
    const derivation = geohashDerivation(node.args[1], itSlot, shape, '$geohash-neighbours');
    if (!('refusal' in derivation)) columns.add(derivation.column);
  }
  for (const value of Object.values(node)) {
    if (Array.isArray(value)) {
      for (const child of value) neighbourhoodErrorColumns(child, itSlot, shape, columns);
    }
    else if (value !== null && typeof value === 'object') neighbourhoodErrorColumns(value, itSlot, shape, columns);
  }
  return columns;
}

// ————— The k-nearest promotion: an ORDERING the column pre-filters —————
//
// `$orderby` on a `$similarity` key, descending, `$empty: 'least'`,
// under a `$subsequence` window with a finite limit, over a member a
// `derive: 'vector'` column stores: the one ordering the planner
// promotes. Not to SQL — no ORDER BY is emitted, no per-row similarity
// call, no LIMIT: every SQL spelling of the rank measured slower than
// fetching the packed column and ranking in the engine, and none of
// them runs where no function can be registered — but to a CUT. The
// statement projects (identity, column) under the pushed WHERE; the
// engine scores every row's column against the probe; the rows whose
// score is within `KNN_MARGIN` of the `offset + limit`-th best are the
// candidates. Then the ENGINE decides: the original document — its
// whole `$orderby` (the similarity key over the raw member, every
// secondary key, `$empty`), its window, its `$return` — runs as the set
// residual over exactly those documents.
//
// What makes that exact is the implied-conjunct argument, applied to an
// ordering. The column's score (a dot product over binary32-normalized
// forms) and the engine's key (the cosine of the raw doubles) differ by
// at most ~1e-8, measured; with a margin two orders of magnitude wider
// the engine's top `offset + limit` is a SUBSET of the candidates — a
// row the engine ranks inside the window that the column left out would
// need two true cosines to differ by more than the column can mis-order
// them. Ties at the boundary are included by construction, and the
// engine breaks them by the document's own secondary keys, which is why
// no row-identity tie rule exists here: row identity serves the fetch,
// never the order.
//
// Two shapes reach the window's tail that no cut can order: fewer than
// `offset + limit` rows scored — a small collection, or NULL columns
// (absent, wrong-width, non-finite members) — so the window reaches the
// unrankable rows, which `$empty: 'least'` places LAST in the engine's
// own secondary order. The candidate set is then every row, and the
// collection is no larger than the window.
//
// Preconditions, each a named refusal. The selection must be pushed
// WHOLE — every `$where` conjunct exact, nothing before it — because a
// conjunct left to the residual could drop a candidate the cut counted,
// and an implied one narrows to a superset the residual then shrinks;
// either could leave the window short. The probe must be a literal
// vector of the column's width, or an external: what an external
// carries is the binder's to check at call time, and a bound value that
// is not a vector of that width DIVERTS the call to the residual, where
// the engine answers what it answers everywhere (empty keys for another
// width, its own refusal of a non-array) — never a plan-side error the
// engine would not raise.

const KNN_REASONS = {
  rank: 'k-nearest rank is engine work: the vector column cuts the candidates and the engine orders them',
  direction: 'k-nearest is promoted only descending (higher similarity first)',
  empties: "k-nearest is promoted only under $empty: 'least' (unrankable rows last, where the cut can reach them)",
  collation: 'a collation on a similarity key is refused, not approximated',
  subject: 'the similarity key must compare a singular member path on the binding with a probe',
  probe: 'the probe must be a literal vector (an array of finite numbers) or an external',
  selection: 'k-nearest ranks over the column only when the selection is pushed whole (every $where conjunct exact, no $let or $as before it)',
  window: 'k-nearest needs a window with a finite limit; an unbounded ranking is a full sort in the engine',
  /** @param {string} path @param {number | null} dims */
  noColumn: (path, dims) =>
    `no vector column over ${path}${dims === null ? '' : ` at width ${dims}`}`,
  /** @param {string} path @param {number} want @param {number[]} have */
  dims: (path, want, have) =>
    `the literal probe has ${want} components but the vector column over ${path} is declared at ${have.join(', ')}`,
};

/**
 * The planner's reason VOCABULARY: every cause a plan can name for
 * work it left in the engine, under a stable identifier. An explanation
 * is public behaviour, so the sentences are a closed set — a new
 * promotion adds an entry here, it does not write prose at the refusal
 * site — and a test can then assert that every reason a corpus observes
 * is one of these and nothing else.
 *
 * Most entries are the whole sentence. The four that quote the caller's
 * own values — a vector width, a member path, the registered operators
 * a document used — carry instead the stable opening they always begin
 * with, which is what {@link reasonId} matches them by.
 */
export const PLANNER_REASONS = Object.freeze({
  ...Object.fromEntries(Object.entries(KIND_REASONS)
    .map(([key, text]) => [`kind.${key}`, { text }])),
  ...Object.fromEntries(Object.entries(PREDICATE_REASONS)
    .map(([key, text]) => [`predicate.${key}`, { text }])),
  ...Object.fromEntries(Object.entries(FLWOR_REASONS)
    .map(([key, text]) => [`flwor.${key}`, { text }])),
  ...Object.fromEntries(Object.entries(PLAN_REASONS)
    .map(([key, text]) => [`plan.${key}`, { text }])),
  ...Object.fromEntries(Object.entries(ENTITY_REASONS)
    .map(([key, text]) => [`entity.${key}`, { text }])),
  ...Object.fromEntries(Object.entries(SPATIAL_REASONS)
    .map(([key, text]) => [`spatial.${key}`, { text }])),
  ...Object.fromEntries(Object.entries(INTERVAL_REASONS)
    .map(([key, text]) => [`interval.${key}`, { text }])),
  ...Object.fromEntries(Object.entries(KNN_REASONS)
    .filter(([, text]) => typeof text === 'string')
    .map(([key, text]) => [`knn.${key}`, { text }])),
  ...Object.fromEntries(Object.entries(SERIES_REASONS)
    // the temporal planner spells its code into the sentence, so the
    // reason a plan carries is the code and the sentence at once
    .map(([code, text]) => [`series.${code}`, { text: `${code}: ${text}` }])),
  ...Object.fromEntries(Object.entries(BIND_REASONS)
    .filter(([, text]) => typeof text === 'string')
    .map(([key, text]) => [`bind.${key}`, { text }])),
  'knn.noColumn': { prefix: 'no vector column over ' },
  'knn.dims': { prefix: 'the literal probe has ' },
  'operators.registered': { prefix: 'registered operator' },
  'bind.external': { prefix: 'the external ' },
  'bind.externalLiteral': { prefix: 'a literal is not a value the database binds' },
  // the sentence itself is the dialect's, raised where the path is
  // spelled; the vocabulary claims its stable opening
  'bind.path': { prefix: 'a member name the dialect' },
  // likewise raised where the literal is bound: text the server cannot hold
  'bind.serverText': { prefix: 'a string literal holding U+0000' },
  // likewise raised where the order is spelled: a table naming every
  // spelling of the row identity as a column
  'bind.identity': { prefix: 'a table with columns named rowid' },
});

/**
 * The vocabulary identifier of one reason sentence, or `null` when no
 * entry claims it — an unnamed reason, which the explanation contract
 * treats as a defect rather than a variation.
 * @param {string} reason
 * @returns {string | null}
 */
export function reasonId(reason) {
  for (const [id, entry] of Object.entries(PLANNER_REASONS)) {
    if (entry.text !== undefined) {
      if (entry.text === reason) return id;
    }
    else if (reason.startsWith(entry.prefix)) return id;
  }
  return null;
}

/**
 * What an inequality counts, or any
 * comparison under a `not`, between a member read from the document and an
 * external operand. The statement keeps the operand's kind discriminator
 * beside each such comparison and reads the member through its typed
 * extraction, so a chain of them compiles several times slower, leaf for
 * leaf, than the same number of comparisons against literals.
 */
const EXTERNAL_INEQUALITY_TERMS = 4;

/**
 * What a member's membership in an external list counts, which compiles the
 * slowest of all: every such leaf keeps the list's own kind discriminator and
 * unpacking beside the comparison, whatever the list's length. Read from the
 * document it counts this many; a member in its own column, whose comparison
 * is cheaper, counts a quarter of it, and twice that under a `not`.
 */
const EXTERNAL_LIST_TERMS = 16;

/**
 * The leaf predicates a plan or a predicate carries: every predicate
 * node except the connectives — `and`, `or`, `not` and a `binding`
 * scope — one bound membership list of literals being one leaf and a comparison of
 * two paths decided one family at a time one leaf for each family they
 * share, summed over a
 * collection plan's filter or an entity plan's binding filters and
 * include count filters, over the filters inside the subselects that
 * read a related entity (a hop's test, count, value or order key — a
 * value's twice, for the member and for its type), and
 * over the comparisons between bindings that refine a join; a join's
 * column equality is not a predicate (the server merges equalities and
 * prices them once). What a
 * statement costs the database per row, and what prices it into a JIT
 * compile, grows with this count and never with the depth of the tree,
 * which nests in halves. A leaf is one term, except an inequality, or
 * any comparison under a `not`, between a member read from the document and
 * an external operand, which counts `EXTERNAL_INEQUALITY_TERMS`, and a
 * member's membership in an external list, which counts `EXTERNAL_LIST_TERMS`
 * or less (a member in its own column compiles like one against a literal
 * for the first and cheaper for the second).
 * @param {any} value - a plan, a predicate node, or `null`
 * @returns {number}
 */
export function predicateTerms(value) {
  return termsOf(value, false);
}

/** Whether a member is compared in its own entity column, not read from the document.
 * @param {any} ref */
function ownColumn(ref) {
  return ref.flavor === 'entity-column' || ref.flavor === 'entity-epoch';
}

/**
 * {@link predicateTerms}, knowing whether the predicate sits under a `not`.
 * @param {any} value
 * @param {boolean} negated
 * @returns {number}
 */
function termsOf(value, negated) {
  if (value === null || value === undefined) return 0;
  if (typeof value.p === 'string') {
    switch (value.p) {
      case 'and': case 'or':
        return value.items.reduce((/** @type {number} */ sum, /** @type {any} */ item) => sum + termsOf(item, negated), 0);
      case 'not': return termsOf(value.item, true);
      case 'binding': return termsOf(value.filter, false);
      // two paths decided one family at a time cost a term for each family
      // they can hold in common
      case 'refCmp': return plainFamily(value) !== null ? 1
        : Math.max(1, value.left.families.filter((/** @type {string} */ family) =>
          value.right.families.includes(family)).length);
      // the rows of a related entity tested or counted: the filter inside
      // the subselect is read for every outer row, and the test itself is
      // a leaf where the filter holds none
      case 'hop': return Math.max(1, termsOf(value.hop.filter, false));
      case 'hopCount': return 1 + termsOf(value.hop.filter, false);
      case 'in': {
        if (!('ext' in value.operand)) return 1;
        if (!ownColumn(value.ref)) return EXTERNAL_LIST_TERMS;
        return negated ? EXTERNAL_LIST_TERMS / 2 : EXTERNAL_LIST_TERMS / 4;
      }
      case 'cmp': return 'ext' in value.operand && (negated || value.op === 'ne')
        && !ownColumn(value.ref) ? EXTERNAL_INEQUALITY_TERMS : 1;
      default: return 1;
    }
  }
  let terms = termsOf(value.filter ?? null, false);
  for (const entry of value.filters ?? []) terms += termsOf(entry.filter, false);
  // a value leaf reads its hop twice, once for the member and once for its
  // type, so the statement carries the filter twice
  for (const leaf of value.project?.leaves ?? [])
    terms += termsOf(leaf.count?.filter ?? null, false) + 2 * termsOf(leaf.hop?.filter ?? null, false);
  for (const term of value.order ?? []) terms += termsOf(term.hop?.filter ?? null, false);
  // a comparison between two bindings that is not an equality refines the
  // join, and the server evaluates it once per candidate pair
  for (const join of value.joins ?? [])
    for (const edge of join.on) if (edge.op !== 'eq') terms += 1;
  return terms;
}

/**
 * An entity plan with every hop rewritten by `fn` — the correlated
 * subselects of its predicates, its count and value leaves and its order
 * keys. A caller that narrows every read of a related entity (a profile's
 * mandatory predicate) does it here, once, for every site that reads one.
 * @param {any} plan - an `entity-select` or `entity-join` plan
 * @param {(hop: any) => any} fn
 * @returns {any}
 */
export function mapHops(plan, fn) {
  const predicate = (/** @type {any} */ pred) => {
    switch (pred?.p) {
      case 'and': case 'or': return { ...pred, items: pred.items.map(predicate) };
      case 'not': return { ...pred, item: predicate(pred.item) };
      case 'binding': return { ...pred, filter: predicate(pred.filter) };
      case 'hop': case 'hopCount': return { ...pred, hop: fn(pred.hop) };
      default: return pred;
    }
  };
  return {
    ...plan,
    filters: plan.filters.map((/** @type {any} */ entry) => ({ ...entry, filter: predicate(entry.filter) })),
    order: plan.order === null ? null : plan.order.map((/** @type {any} */ term) =>
      (term.hop === undefined ? term : { ...term, hop: fn(term.hop) })),
    project: plan.project === null ? null : { ...plan.project, leaves: plan.project.leaves.map((/** @type {any} */ leaf) =>
      (leaf.count !== undefined ? { ...leaf, count: fn(leaf.count) }
        : leaf.hop !== undefined ? { ...leaf, hop: fn(leaf.hop) } : leaf)) },
  };
}

/**
 * Every read of a related entity an entity plan's statement makes, in the
 * order its sites appear: a value leaf reads its hop twice, once for the
 * member and once for its type.
 * @param {any} plan
 * @returns {any[]}
 */
export function hopsOf(plan) {
  /** @type {any[]} */
  const found = [];
  mapHops(plan, (hop) => { found.push(hop); return hop; });
  for (const leaf of plan.project?.leaves ?? []) if (leaf.hop !== undefined) found.push(leaf.hop);
  return found;
}

/**
 * A planned document against a dialect's `maxPredicateTerms`: unchanged
 * where the dialect sets no bound, where nothing is planned natively, or
 * where the statement's leaves — the plan's plus `extraTerms`, what the
 * statement carries beside the plan (a profile's mandatory predicate) —
 * stay within it; otherwise the whole document is demoted to the set
 * residual with the reason first, as a member name the dialect cannot
 * spell demotes it. Counted once the planner has regrouped, so a chain
 * that folds to one membership list is one leaf however long it is.
 * @param {any} planned - a `planQuery` or `planEntityQuery` result
 * @param {number | null} maxTerms
 * @param {number} [extraTerms]
 * @returns {any}
 */
export function boundPredicateTerms(planned, maxTerms, extraTerms = 0) {
  if (typeof maxTerms !== 'number' || planned.plan === null) return planned;
  if (predicateTerms(planned.plan) + extraTerms <= maxTerms) return planned;
  const reasons = [refusal('$where', PREDICATE_REASONS.termBound), ...planned.reasons];
  // an entity result names what it referenced; a collection one carries
  // the row residual, the registered fragments, the pre-filters and the
  // temporal record its statement would have used, none of which survive
  return 'referenced' in planned
    ? { ...planned, plan: null, mode: 'set', reasons }
    : { ...planned, plan: null, mode: 'set', reasons, rowReturn: null, udfs: [], prefilters: [], series: null };
}


/**
 * Recognize the k-nearest ordering, or say why not. `null` when the
 * first key is not a `$similarity` at all — an ordinary ordering the
 * caller plans as before. Further key specs are the engine's business
 * (they order the candidates), so nothing here reads them.
 * @param {any} orderby - the flwor's orderby node
 * @param {number} itSlot
 * @param {any} shape
 * @param {boolean} selectionPushed - the WHERE pushed whole and exact,
 *   with nothing before it
 * @returns {{ rank: { column: string, dims: number,
 *   probe: { lit: number[] } | { ext: string } } }
 *   | { refusal: { construct: string, reason: string } } | null}
 */
function planKnnOrder(orderby, itSlot, shape, selectionPushed) {
  const first = orderby.specs[0];
  const key = first.key;
  if (key.kind !== 'op' || key.name !== '$similarity') return null;
  const refuse = (reason) => ({ refusal: refusal('$similarity', reason) });
  if (first.desc !== true) return refuse(KNN_REASONS.direction);
  if (first.emptyGreatest === true) return refuse(KNN_REASONS.empties);
  if (first.collation !== null || first.collationName !== null)
    return refuse(KNN_REASONS.collation);
  // the subject may be either operand; the other is the probe
  let subjectAt = 0;
  if (memberPath(key.args[0], itSlot) === null && memberPath(key.args[1], itSlot) !== null)
    subjectAt = 1;
  const subject = memberPath(key.args[subjectAt], itSlot);
  if (subject === null) return refuse(KNN_REASONS.subject);
  const path = `$${subject.canonical}`;
  const probeNode = key.args[subjectAt === 0 ? 1 : 0];
  const declared = vectorColumnsOf(shape, subject.canonical);

  if (probeNode.kind === 'var' && probeNode.external === true) {
    if (declared.length === 0) return refuse(KNN_REASONS.noColumn(path, null));
    if (!selectionPushed) return refuse(KNN_REASONS.selection);
    // EVERY declared width is an alternative: the plan carries them all
    // and the BIND picks the one the probe's own width names. A `CASE`
    // across the columns would read every one of them per row, and a
    // statement per call would give up the prepared cache
    return { rank: { alternatives: declared.map((entry) =>
      ({ column: entry.column, dims: entry.dims })),
    probe: { ext: probeNode.name } } };
  }
  const constant = constantOf(probeNode);
  if (constant === null || !Array.isArray(constant.value)) return refuse(KNN_REASONS.probe);
  const dims = constant.value.length;
  if (probeVector(constant.value, dims) === null) return refuse(KNN_REASONS.probe);
  const column = derivedColumnsOf(shape, subject.canonical, 'vector', dims);
  if (column === null) {
    return refuse(declared.length === 0
      ? KNN_REASONS.noColumn(path, dims)
      : KNN_REASONS.dims(path, dims, declared.map((entry) => entry.dims)));
  }
  if (!selectionPushed) return refuse(KNN_REASONS.selection);
  return { rank: { alternatives: [{ column: /** @type {string} */ (column), dims }],
    probe: { lit: constant.value } } };
}

/**
 * Dispatch the spatial shapes. Answers `null` when the node is not one
 * of them, so the caller falls through to the rest of the grammar.
 * @param {any} node
 * @param {number} itSlot
 * @param {any} shape
 * @returns {any}
 */
function planSpatial(node, itSlot, shape) {
  if (node.name === '$within' || node.name === '$bbox-intersects')
    return planBoxPredicate(node, itSlot, shape);
  const op = COMPARISONS.get(node.name);
  if (op !== undefined && ORDERING_OPS.has(op)) {
    const upperOnLeft = op === 'le' || op === 'lt';
    const distanceNode = upperOnLeft ? node.args[0] : node.args[1];
    if (distanceNode?.kind === 'op' && distanceNode.name === '$distance')
      return planDistanceBound(node, itSlot, shape);
    // `$distance >= r` — "farther than" — is narrowed by no box at all
    const other = upperOnLeft ? node.args[1] : node.args[0];
    if (other?.kind === 'op' && other.name === '$distance') {
      return { refusal: refusal('$distance', SPATIAL_REASONS.unboundedFar) };
    }
    return null;
  }
  if (node.name === '$starts-with' && node.args[0]?.kind === 'op'
    && node.args[0].name === '$geohash')
    return planCellPrefix(node, itSlot, shape);
  if (node.name === '$exists' && node.args[0]?.kind === 'op'
    && node.args[0].name === '$index-of'
    && node.args[0].args[0]?.kind === 'op'
    && node.args[0].args[0].name === '$geohash-neighbours')
    return planCellNeighbourhood(node, itSlot, shape);
  return null;
}

/**
 * P4 — `$overlaps` over an interval member.
 *
 * The engine's rule (`overlapsInterval`) is one conjunction: two
 * half-open spans share an instant when each starts before the other
 * ends. Over a row whose bounds are declared columns that is two
 * ordinary comparisons, which is why the promotion exists at all.
 *
 * Whether the conjunction is EXACT is the model's to say. The kernel's
 * other half is that a span that is empty or reversed is not `false`,
 * it RAISES (`JQ2001`, through `requireInterval`): a conjunction alone
 * would drop `[500, 100)` for a probe of `[100, 200)` — answering where
 * the engine errors, the one thing a pushdown may never do. A
 * collection that DECLARES the member an interval (`intervals` in the
 * model) holds no such span: the store refuses one before the
 * statement, hook or no hook, and the table's CHECK refuses every
 * other writer. There the conjunction is the operator itself — exact,
 * nothing to refine, no document read per row, and a fetch the bound's
 * index can seek. A declaration that also bounds the span's duration
 * bounds the START from below (a span no longer than D that reaches
 * past the probe's start began after `from - D`), so the start's index
 * is sought between two bounds rather than from the probe's end down to
 * the first row — one-sided, a seek that reads every span begun before
 * the window, and costs more the later the window sits.
 *
 * Undeclared, the schema alone cannot forbid an inverted span (JSON
 * Schema compares no two members), so the pushed form is a PRE-FILTER
 * that keeps every row whose own span is inverted — a comparison
 * between two COLUMNS, which no index bounds, so the statement scans —
 * and the engine raises over the candidates exactly as it would have.
 * What it still buys is the decode: the rows that come back are the
 * ones the operator can be true for, plus the ones it must raise on,
 * rather than the whole collection.
 *
 * The rest of the malformed cases are schema ones, exactly as the
 * spatial promotions' precondition is: a bound the engine errors on
 * (absent, textual, null) cannot be written to a collection whose
 * schema requires two numeric bounds — under a validation hook
 * (`JD2003`), and under a declaration always. A collection with neither
 * stores what it is given, and the guard below drops such a row where
 * the engine would have raised; the declaration is what closes that.
 * @param {any} node
 * @param {number} itSlot
 * @param {any} shape
 * @returns {any}
 */
function planIntervalOverlap(node, itSlot, shape) {
  if (node.args.length !== 2)
    return { refusal: refusal('$overlaps', INTERVAL_REASONS.operands) };
  // the operator is symmetric, so either side may be the row's
  let [subject, probeNode] = node.args;
  if (pathRef(subject, itSlot, shape) === null) [subject, probeNode] = [probeNode, subject];
  const spanRef = pathRef(subject, itSlot, shape);
  const probe = constantOf(probeNode);
  if (spanRef === null || probe === null || pathRef(probeNode, itSlot, shape) !== null)
    return { refusal: refusal('$overlaps', INTERVAL_REASONS.operands) };

  const span = probe.value;
  const from = span === null || typeof span !== 'object' || Array.isArray(span)
    ? null : safeEpoch(span.start);
  const to = span === null || typeof span !== 'object' || Array.isArray(span)
    ? null : safeEpoch(span.end);
  // the probe is the caller's own literal: an empty or reversed one
  // raises for every row, and a plan that answered would hide it
  if (from === null || to === null || !(from < to))
    return { refusal: refusal('$overlaps', INTERVAL_REASONS.probe) };

  const bounds = intervalBounds(spanRef, shape);
  if (bounds === null) return { refusal: refusal('$overlaps', INTERVAL_REASONS.notInterval) };
  if (bounds.start.column === null || bounds.end.column === null)
    return { refusal: refusal('$overlaps', INTERVAL_REASONS.noColumns) };

  const pred = { p: 'interval',
    columns: { start: bounds.start.column, end: bounds.end.column },
    probe: { from, to } };
  // a declaration over these two columns means no stored span is empty,
  // reversed or malformed: the conjunction decides, nothing refines
  const declared = (shape.intervals ?? []).find((interval) =>
    interval.start === bounds.start.column && interval.end === bounds.end.column);
  if (declared !== undefined) {
    // a maximum duration D bounds the start from below as well: a span no
    // longer than D whose end is past `from` started after `from - D`. The
    // probe's start is floored first — a fractional instant is a legal
    // probe, and an integer floor keeps the subtraction exact while
    // bounding no less — and a bound below the least safe integer, which
    // every stored start already satisfies, is left out
    const lower = typeof declared.maxDuration === 'number'
      ? Math.floor(from) - declared.maxDuration : Number.NEGATIVE_INFINITY;
    // the bound columns carry no container: where the span's container is left
    // open, a dialect that reads it off the wrong kind guards the document beside them
    const open = spanRef.unpinned === true ? { unpinned: spanRef.segments } : {};
    return { pred: { ...pred, declared: true, ...(lower >= Number.MIN_SAFE_INTEGER ? { lower } : {}), ...open },
      exact: true, prefilters: [], refinements: [], composable: true };
  }
  return { ...promotion(pred,
    { construct: '$overlaps', via: 'columns',
      columns: [bounds.start.column, bounds.end.column], exact: false },
    [refusal('$overlaps', INTERVAL_REASONS.overlap)]), composable: true };
}

/**
 * The two bound refs of a member the schema types as a half-open
 * interval, or `null` when it does not type it as one.
 *
 * "Types it as one" is the whole precondition: an object and only an
 * object, carrying `start` and `end`, both REQUIRED and both typed
 * numeric and only numeric. A union with `null` or `string` is not an
 * interval here — an RFC 3339 bound is a perfectly good instant to the
 * engine and no epoch column can compare against it. The one rule for
 * what an interval member is: the model's `intervals` declaration is
 * held to it too, with `columnByCanonical` standing for the paths the
 * collection indexes.
 * @param {{ segments: any[] }} spanRef
 * @param {{ schema: any, columnByCanonical: Map<string, string> }} shape
 * @returns {{ start: { segments: any[], type: string, column: string | null },
 *   end: { segments: any[], type: string, column: string | null } } | null}
 */
export function intervalBounds(spanRef, shape) {
  const node = schemaNodeAt(shape.schema, spanRef.segments);
  if (node === undefined || node.type !== 'object') return null;
  const required = Array.isArray(node.required) ? node.required : [];
  if (!required.includes('start') || !required.includes('end')) return null;
  const boundRef = (name) => {
    const bound = node.properties?.[name];
    const type = bound?.type;
    if (typeof type !== 'string' || !isNumericType(type)) return null;
    const segments = [...spanRef.segments, { name }];
    return { segments, type,
      column: shape.columnByCanonical.get(canonicalOf(segments)) ?? null };
  };
  const start = boundRef('start');
  const end = boundRef('end');
  return start === null || end === null ? null : { start, end };
}

/**
 * Translate one predicate node, or explain why not.
 *
 * A translated predicate is EXACT unless it carries `refinements`: an
 * implied spatial conjunct narrows the fetch and leaves the original
 * predicate to the residual, and `prefilters` records what it reads so
 * `explain()` can say whether a declared index is earning its keep.
 * @param {any} node
 * @param {number} itSlot
 * @param {any} shape
 * @returns {{ pred: import('./algebra.js').PlanPredicate, exact: boolean,
 *   prefilters: any[], refinements: { construct: string, reason: string }[] } |
 *   { refusal: { construct: string, reason: string } }}
 */
function planPredicate(node, itSlot, shape) {
  assertDecidedKind(node);
  if (node.kind !== 'op') {
    return { refusal: refusal(node.kind,
      KIND_REASONS[node.kind] ?? PREDICATE_REASONS.notPredicate) };
  }

  if (node.name === '$or') return planDisjunction(node.args, itSlot, shape);
  if (node.name === '$and') {
    const items = [];
    const prefilters = [];
    const refinements = [];
    for (const arg of node.args) {
      const inner = planPredicate(arg, itSlot, shape);
      if ('refusal' in inner) return inner; // a partial $and is not splittable here
      items.push(inner.pred);
      prefilters.push(...inner.prefilters);
      refinements.push(...inner.refinements);
    }
    // an implied child makes the composition a SUPERSET either way, so
    // it still narrows honestly — it just stops deciding
    return { pred: { p: 'and', items },
      exact: refinements.length === 0, prefilters, refinements };
  }
  if (node.name === '$not') {
    const inner = planPredicate(node.args[0], itSlot, shape);
    if ('refusal' in inner) return inner;
    if (inner.refinements.length > 0) {
      // negating a superset is a SUBSET, which drops matching rows —
      // the one composition an implied conjunct may never enter
      return { refusal: refusal('$not', PREDICATE_REASONS.negatedPrefilter) };
    }
    return { pred: { p: 'not', item: inner.pred },
      exact: true, prefilters: inner.prefilters, refinements: [] };
  }

  node = withGetPaths(node, itSlot, shape);

  // a shape that can resolve a navigation hop (an entity binding of one
  // planned query) answers the forms that read a related entity
  if (shape.hop !== undefined) {
    const hopped = shape.hop(node);
    if (hopped !== null) return hopped;
  }

  const spatial = planSpatial(node, itSlot, shape);
  if (spatial !== null) return spatial;

  if (node.name === '$overlaps') return planIntervalOverlap(node, itSlot, shape);

  if (node.name === '$exists' || node.name === '$empty') {
    const ref = pathRef(node.args[0], itSlot, shape);
    if (ref === null) {
      return { refusal: refusal(node.name, PREDICATE_REASONS.existence) };
    }
    return exactly({ p: 'typeIs', ref, types: [], positive: node.name === '$exists' });
  }

  if (node.name === '$eq') {
    const membership = planMembership(node.args, itSlot, shape);
    if (membership !== null) return membership;
  }

  const comparison = COMPARISONS.get(node.name);
  if (comparison !== undefined) {
    let [left, right] = node.args;
    let op = comparison;
    // literal/external on the left: flip the operator around the path
    if (pathRef(left, itSlot, shape) === null && operandOf(left) !== null) {
      [left, right] = [right, left];
      op = /** @type {any} */ ({ lt: 'gt', le: 'ge', gt: 'lt', ge: 'le' })[op] ?? op;
    }
    const ref = pathRef(left, itSlot, shape);
    const operand = operandOf(right);
    if (ref === null || operand === null) {
      const other = pathRef(right, itSlot, shape);
      if (ref !== null && other !== null) {
        const leftFamilies = scalarFamilies(shape.schema, ref.segments);
        const rightFamilies = scalarFamilies(shape.schema, other.segments);
        // two members the schema types as scalars compare by the family of
        // their values; any other operand is deep-equality territory
        if (leftFamilies === null || rightFamilies === null)
          return { refusal: refusal(node.name, PREDICATE_REASONS.joinTerritory) };
        return exactly({ p: 'refCmp', op, left: { ...ref, families: leftFamilies },
          right: { ...other, families: rightFamilies } });
      }
      return { refusal: refusal(node.name, PREDICATE_REASONS.operands) };
    }
    if ('lit' in operand) {
      if (!isScalarLiteral(operand.lit)) {
        return { refusal: refusal(node.name, PREDICATE_REASONS.compoundLiteral) };
      }
      const lit = operand.lit;
      if (typeof lit === 'boolean' || lit === null) {
        if (ORDERING_OPS.has(op)) return exactly({ p: 'const', value: false });
        const typeName = lit === null ? 'null' : lit ? 'true' : 'false';
        return exactly({ p: 'typeIs', ref, types: [typeName], positive: op === 'eq' });
      }
      // NaN equals nothing, orders against nothing and differs from every
      // present member; no database binds it so (SQLite stores NULL,
      // PostgreSQL sorts it above every number), so it is answered here
      if (typeof lit === 'number' && Number.isNaN(lit)) {
        return exactly(op === 'ne'
          ? { p: 'typeIs', ref, types: [], positive: true }
          : { p: 'const', value: false });
      }
    }
    return exactly({ p: 'cmp', op: /** @type {any} */ (op), ref, operand });
  }

  const stringOp = STRING_OPS.get(node.name);
  if (stringOp !== undefined) {
    const ref = pathRef(node.args[0], itSlot, shape);
    const operand = operandOf(node.args[1]);
    if (ref === null || ref.type !== 'string' || stringSubjectRaises(ref, shape)) {
      return { refusal: refusal(node.name, PREDICATE_REASONS.stringSubject) };
    }
    if (operand === null || !('lit' in operand) || typeof operand.lit !== 'string') {
      return { refusal: refusal(node.name, PREDICATE_REASONS.stringPattern) };
    }
    if (operand.lit === '') {
      return { refusal: refusal(node.name, PREDICATE_REASONS.emptyPattern) };
    }
    return exactly({ p: 'strop', kind: /** @type {any} */ (stringOp), ref, operand });
  }

  return { refusal: refusal(node.name, PREDICATE_REASONS.noSpelling) };
}

// ————— Time series: the three closed shapes over a declared index —————
//
// The physical feature is one a model already has: a composite index
// over `[$.series, $.at]`. There is no `derive: 'series'`, no column
// type and no host function — the whole point is that a declared
// numeric epoch column is already 52× reading the instant back out of
// the document, so the work here is recognizing which questions that
// index can answer rather than inventing a place to put time.
//
// Three shapes are recognized, and they are CLOSED:
//
//  1. **range** — every leading column of an instant index pinned by an
//     equality, a half-open range on the instant column, ordered by it.
//     Already a native selection; what this adds is the NAME of the
//     operation, the index it seeks, and the honest reason when the
//     prefix is missing.
//  2. **as-of** — the same prefix with ONE instant bound, ordered by
//     the instant, cut to a finite window. §2.2's 0.003 ms row.
//  3. **bucket** — a fixed-width ladder over the instant column with
//     the exact `sum|mean|min|max|count` aggregates, in both spellings
//     the language has for it: a `$groupby` whose key is
//     `$time-bucket`, and a `$resample` whose spec asks for nothing a
//     `GROUP BY` cannot do.
//
// Everything else is a NAMED core refinement: the fetch narrows through
// the index and the residual — which is the engine running the caller's
// own document — decides. That is what keeps a refinement idempotent,
// and it is why a calendar ladder, a fill policy, a rolling window and
// an as-of JOIN cost a bounded fetch rather than a wrong answer.

/**
 * The source a packed spelling stands for. `["$[*]"]` — an array
 * constructor of exactly one element — is what a `$for` unpacks back
 * into the rows (QUERY-FORMAT §6.2): `@jarenjs/linq` binds every
 * iterated source that way so an array-valued ROW stays one item. Over
 * a collection or an entity array the rows are objects, so the packed
 * and the bare spelling are the same rows, and the planner reads
 * through the packing rather than sending the document to the residual.
 * @param {any} node
 * @returns {any}
 */
function unpacked(node) {
  return node?.kind === 'array' && node.elements?.length === 1 ? node.elements[0] : node;
}

/** Is this node the whole collection — `$[*]` over the input document,
 * bare or packed? */
function isCollectionSource(node) {
  const path = unpacked(node);
  return path?.kind === 'path' && path.name === '$' && path.external !== true
    && path.rootSlot === 0 && path.singular !== true
    && path.segments.length === 1 && path.segments[0].descendant !== true
    && path.segments[0].selectors.length === 1
    && path.segments[0].selectors[0].kind === 'wildcard';
}

/**
 * The collection-side operand of a root series operator: the bare
 * `$[*]`, or a FLWOR over it whose `$where` is the narrowing.
 * @param {any} node
 * @returns {{ flwor: any } | null}
 */
function collectionOperand(node) {
  if (isCollectionSource(node)) return { flwor: null };
  if (node?.kind === 'flwor' && node.forBindings.length === 1
    && isCollectionSource(node.forBindings[0]?.expr))
    return { flwor: node };
  return null;
}

/**
 * A typed reference to one top-level member of the collection's
 * documents — what a spec's row selector ultimately names.
 * @param {any} shape
 * @param {string} name
 * @returns {import('./algebra.js').PlanRef}
 */
function memberRef(shape, name) {
  const segments = [{ name }];
  const canonical = canonicalOf(segments);
  return {
    segments,
    type: typeOfPath(shape.schema, segments),
    column: shape.columnByCanonical.get(canonical) ?? null,
    ...wholeColumnOf(shape, canonical),
  };
}

/**
 * The instants a plan-time literal series carries, under one selector.
 * `null` when the operand is not a literal array of records, or when
 * one of them names no instant — either way the planner has no bound to
 * add and says so rather than guessing one.
 * @param {any} node
 * @param {any} selector - the spec's `leftAt`/`rightAt`, or undefined
 * @returns {{ min: number, max: number, keys: any[] | null } | null}
 */
function literalInstants(node, selector, keySelector) {
  const constant = constantOf(node);
  if (constant === null || !Array.isArray(constant.value) || constant.value.length === 0)
    return null;
  const at = selector === undefined ? 'at' : singularSelector(selector);
  const by = keySelector === undefined ? null : singularSelector(keySelector);
  if (at === null || (keySelector !== undefined && by === null)) return null;
  let min = Infinity;
  let max = -Infinity;
  const keys = by === null ? null : [];
  for (const row of constant.value) {
    if (row === null || typeof row !== 'object') return null;
    const instant = row[at];
    if (typeof instant !== 'number' || !Number.isFinite(instant)) return null;
    if (instant < min) min = instant;
    if (instant > max) max = instant;
    if (keys !== null) {
      const key = row[by];
      if (typeof key !== 'string' && typeof key !== 'number') return null;
      if (!keys.includes(key)) keys.push(key);
    }
  }
  return { min, max, keys };
}

/**
 * The native bucket a `$resample` spec asks for, or the FIRST reason it
 * is a refinement instead. The rules are asked in one fixed order, so a
 * spec always names the same reason on every host.
 * @param {any} spec - the frozen literal
 * @param {any} shape
 * @returns {{ bucket: import('./algebra.js').PlanBucket } | { code: string }}
 */
function resampleBucket(spec, shape) {
  // the clock first, because a named zone is resolved by HOST code the
  // planner does not have: asking the kernel about it would report the
  // missing provider rather than the reason a ladder is not native
  if (spec.zone !== undefined && spec.zone !== 'UTC') return { code: 'named-zone' };
  // The kernel's own rules, asked once, by running it over NO rows:
  // `analyzeQuery` does not
  // compile an operator, so a spec the kernel refuses reaches the
  // planner before the engine has had its say, and a plan that answered
  // where the engine raises is the one thing a pushdown may never do.
  try {
    resampleSeries([], spec);
  }
  catch {
    return { code: 'invalid-spec' };
  }
  if (spec.fill !== undefined && spec.fill !== 'omit') return { code: 'fill-policy' };
  const fn = NATIVE_AGGREGATES[spec.aggregate ?? 'mean'];
  if (fn === undefined) return { code: 'unsupported-aggregate' };
  const ladder = fixedLadder(spec, compileBuckets);
  if ('code' in ladder) return ladder;
  // a row selector is a singular path whose `$` is the ROW, so it names
  // a member — and a member is what a declared column stands for. One
  // that names a path INTO a member names no column, and says so
  const atName = spec.at === undefined ? 'at' : singularSelector(spec.at);
  const valueName = spec.value === undefined ? 'value' : singularSelector(spec.value);
  if (atName === null || valueName === null) return { code: 'row-selector' };
  const at = memberRef(shape, atName);
  const instantBad = instantRefusal(at);
  if (instantBad !== null) return { code: instantBad };
  const value = memberRef(shape, valueName);
  // the kernel reads the reading of EVERY row, whatever the aggregate, so a
  // count needs a numeric reading as a sum does; a reading of two types
  // folds as its first in SQL, where the engine refuses the mixed sequence
  const valueBad = valueRefusal(value)
    ?? (admitsMixedTypes(shape.schema, value.segments) ? 'value-not-numeric' : null);
  if (valueBad !== null) return { code: valueBad };
  // the engine adds left to right, which no SQL sum reproduces over doubles
  if (fn !== 'rows' && floatingAccumulation({ fn, ref: value })) return { code: 'floating-accumulation' };
  // The bucket shape, exactly: the bucket's start, its reading, and the count
  // of SOURCE rows — which is `COUNT(*)` whether or not it is also the
  // answer, because `aggregate: 'count'` returns that same number
  return { bucket: {
    ref: at,
    every: ladder.every,
    origin: ladder.origin,
    as: 'at',
    order: 'asc',
    aggregates: [
      { fn: /** @type {any} */ (fn), ref: fn === 'rows' ? null : value, as: 'value' },
      { fn: /** @type {any} */ ('rows'), ref: null, as: 'count' },
    ],
    // a member the schema leaves optional may be absent, which SQL reads as
    // the `NULL` of a measured gap and the kernel refuses
    ...(Array.isArray(shape.schema?.required) && shape.schema.required.includes(valueName)
      ? {} : { reading: value }),
  } };
}

/**
 * The ladder a `$groupby` key spells, when the key is a `$time-bucket`
 * over a member path with literal width and origin.
 * @param {any} key - the grouping key expression node
 * @param {number} itSlot
 * @param {any} shape
 * @returns {{ ref: any, every: number, origin: number } | { code: string } | null}
 *   `null` when the key is not a `$time-bucket` at all
 */
function groupLadder(key, itSlot, shape) {
  if (key?.kind !== 'op' || key.name !== '$time-bucket') return null;
  const [atNode, everyNode, originNode, contextNode] = key.args;
  if (everyNode.kind !== 'literal') return { code: 'nonliteral-spec' };
  if (originNode !== undefined && originNode.kind !== 'literal')
    return { code: 'nonliteral-spec' };
  /** @type {any} */
  const spec = { every: everyNode.value };
  if (originNode !== undefined && originNode.value !== null) spec.origin = originNode.value;
  if (contextNode !== undefined) {
    if (contextNode.kind !== 'raw') return { code: 'nonliteral-spec' };
    const context = contextNode.value;
    if (context?.zone !== undefined) return { code: 'named-zone' };
    if (context?.offset !== undefined) spec.offset = context.offset;
  }
  const ladder = fixedLadder(spec, compileBuckets);
  if ('code' in ladder) return ladder;
  const ref = pathRef(atNode, itSlot, shape);
  const instantBad = instantRefusal(ref);
  if (instantBad !== null) return { code: instantBad };
  return { ref, every: ladder.every, origin: ladder.origin };
}

/**
 * The closed projection of a bucket grouping: one member per answered
 * value, each of them the group key, a `$count` of the whole binding,
 * `$min` or `$max` over a schema-typed numeric path, or `$sum` or `$avg`
 * over a path the schema types `integer` (a floating one is the engine's).
 * A path that admits a stored `null` is the engine's too.
 * @param {any} ret - the `$return` node
 * @param {number} itSlot
 * @param {number} keySlot
 * @param {any} shape
 * @returns {{ as: string, aggregates: any[] } | { code: string }}
 */
function bucketProjection(ret, itSlot, keySlot, shape) {
  if (ret?.kind !== 'object') return { code: 'nonnative-grouping' };
  let as = null;
  const aggregates = [];
  for (const entry of ret.entries) {
    const expr = entry.expr;
    if (expr.kind === 'var' && expr.external !== true && expr.slot === keySlot) {
      if (as !== null) return { code: 'nonnative-grouping' };
      as = entry.name;
      continue;
    }
    if (expr.kind !== 'op') return { code: 'nonnative-grouping' };
    if (expr.name === '$count') {
      // `$count` over the BINDING is the group's row count; over a path
      // it counts the rows that HAVE the member, which SQL's
      // `COUNT(column)` does not reproduce for a JSON `null`
      if (!isItVar(expr.args[0], itSlot)) return { code: 'nonnative-grouping' };
      aggregates.push({ fn: 'rows', ref: null, as: entry.name, empty: 'null' });
      continue;
    }
    const fn = { $sum: 'sum', $avg: 'avg', $min: 'min', $max: 'max' }[expr.name];
    if (fn === undefined) return { code: 'nonnative-grouping' };
    const ref = pathRef(expr.args[0], itSlot, shape);
    const valueBad = valueRefusal(ref)
      ?? (admitsMixedTypes(shape.schema, ref.segments) ? 'value-not-numeric' : null);
    if (valueBad !== null) return { code: valueBad };
    if (floatingAccumulation({ fn, ref })) return { code: 'floating-accumulation' };
    // a stored null is an item of the engine's sequence, which it refuses
    // (`JQ2001`); SQL skips it, so a reading that admits one is the engine's
    if (nullReading(ref, shape.schema) === 'present') return { code: 'nullable-reading' };
    // what an aggregate over NO numbers says, in the ENGINE's words:
    // `$sum` of an empty sequence is 0 and the other three are the
    // empty sequence, which an object constructor leaves the member out
    // for. SQL answers `NULL` for all four, so the mapping is the plan's
    aggregates.push({ fn, ref, as: entry.name, empty: fn === 'sum' ? 'zero' : 'omit' });
  }
  if (as === null || aggregates.length === 0) return { code: 'nonnative-grouping' };
  return { as, aggregates };
}

/**
 * Which way the groups come out. The engine's own rule is order of
 * FIRST APPEARANCE (§6.5), which over a collection is the earliest row
 * identity in each group; an `$orderby` on the key alone replaces it.
 * @param {any} orderby
 * @param {number} keySlot
 * @returns {'asc' | 'desc' | 'first-seen' | null} `null` when the
 *   ordering is one this plan cannot reproduce
 */
function bucketOrder(orderby, keySlot) {
  if (orderby === null) return 'first-seen';
  if (orderby.specs.length !== 1) return null;
  const spec = orderby.specs[0];
  if (spec.collation !== null || spec.collationName !== null) return null;
  const key = spec.key;
  if (key.kind !== 'var' || key.external === true || key.slot !== keySlot) return null;
  return spec.desc === true ? 'desc' : 'asc';
}

/**
 * The record a refused grouping leaves behind: the same question, named
 * and reasoned, over whatever the fetch still narrows.
 * @param {import('./algebra.js').Plan} plan
 * @param {any} shape
 * @param {string} code
 * @param {string} construct
 * @returns {any}
 */
function refinedGrouping(plan, shape, code, construct) {
  const facts = filterFacts(plan.filter);
  let column = null;
  for (const [name] of facts.bounds) {
    if (instantIndexesOver(shape, name, 2).length > 0) column = name;
  }
  const index = seekingIndexFor(shape, column, facts, 2);
  const bound = column === null ? null : facts.bounds.get(column);
  return seriesRecord({
    mode: plan.filter === null ? 'engine' : 'hybrid',
    operation: 'bucket',
    index: index === null ? null : index.name,
    prefix: index === null ? [] : index.prefix,
    range: bound === undefined || bound === null ? null : { column, ...bound },
    refinement: 'resampleSeries',
    reasons: [seriesReason(code, construct)],
  });
}

/**
 * Classify a planned selection as a temporal range or as-of lookup, or
 * answer `null` when the document asked no such question. The plan is
 * NOT changed: this names what the selection already is, and which
 * declared index it seeks through.
 * @param {import('./algebra.js').Plan} plan
 * @param {any} shape
 * @param {boolean} ordered - the ordering was pushed whole
 * @returns {any} the series record, or null
 */
function classifySelection(plan, shape, ordered) {
  const facts = filterFacts(plan.filter);
  // the instant column is the one a DECLARED index ends with; without
  // such an index the collection has no instant and the question was
  // an ordinary one
  const candidates = [];
  for (const [column, bound] of facts.bounds) {
    if (instantIndexesOver(shape, column, 2).length === 0) continue;
    candidates.push([column, bound]);
  }
  if (candidates.length !== 1) return null;
  const [column, bound] = candidates[0];
  const index = seekingIndexFor(shape, column, facts, 2);
  const bounded = bound.from !== null || bound.to !== null;
  const twoSided = bound.from !== null && bound.to !== null;
  const orderedByInstant = ordered && plan.order !== null && plan.order.length === 1
    && plan.order[0].ref.column === column;
  const operation = twoSided ? 'range'
    : (orderedByInstant && plan.window !== null && plan.window.limit !== null) ? 'asof'
      : bounded ? 'range' : null;
  if (operation === null) return null;
  const reasons = index === null ? [seriesReason('missing-series-prefix', '$where')] : [];
  return seriesRecord({
    mode: index === null ? 'engine' : 'native',
    operation,
    index: index === null ? null : index.name,
    prefix: index === null ? [] : index.prefix,
    range: {
      from: bound.from, fromOp: bound.fromOp, to: bound.to, toOp: bound.toOp, column,
    },
    reasons,
  });
}


/**
 * The bucket a `$groupby` phrase spells, or the reason it is not one.
 * @param {any} node - the flwor node
 * @param {number} itSlot
 * @param {any} shape
 * @returns {{ bucket: any } | { code: string }}
 */
function planBucketGrouping(node, itSlot, shape) {
  if (node.groupby.keys.length !== 1) return { code: 'nonnative-grouping' };
  const key = node.groupby.keys[0];
  const ladder = groupLadder(key.expr, itSlot, shape);
  if (ladder === null) return { code: 'nonnative-grouping' };
  if ('code' in ladder) return ladder;
  const projection = bucketProjection(node.ret, itSlot, key.slot, shape);
  if ('code' in projection) return projection;
  const order = bucketOrder(node.orderby, key.slot);
  if (order === null) return { code: 'nonnative-grouping' };
  return { bucket: {
    ref: ladder.ref,
    every: ladder.every,
    origin: ladder.origin,
    as: projection.as,
    order,
    aggregates: projection.aggregates,
  } };
}

/**
 * The tolerance of an as-of spec in milliseconds, or `null` for one
 * that bounds nothing. A NEGATIVE tolerance is a broken document the
 * engine refuses, and narrowing by it would move the bounds INWARD —
 * so it bounds nothing here and the engine raises, which is the same
 * rule `safeEpoch` follows for an instant that names none.
 */
function toleranceMs(tolerance) {
  if (tolerance === undefined) return null;
  if (typeof tolerance === 'number')
    return Number.isFinite(tolerance) && tolerance >= 0 ? tolerance : null;
  try {
    const span = compileBuckets({ every: tolerance }, {});
    return span.calendar || span.width < 0 ? null : span.width;
  }
  catch {
    return null;
  }
}

/**
 * The epoch a spec member names, or `null` when it names none.
 *
 * A planner may never raise on the ENGINE's behalf: `analyzeQuery` does
 * not compile an operator, so a spec whose `start` is not an instant
 * reaches here before the engine has had its say. Refusing to narrow is
 * the right answer — the residual compiles the caller's own document
 * and raises the `JQ0003` it would have raised anyway.
 * @param {any} value
 * @returns {number | null}
 */
function safeEpoch(value) {
  if (value === undefined) return null;
  try {
    const at = toEpoch(value);
    return Number.isFinite(at) ? at : null;
  }
  catch {
    return null;
  }
}

/**
 * An instant bound as a pushable conjunct over the instant column.
 *
 * Every caller is a REFINEMENT — the bound narrows and the kernel
 * decides over what comes back — and the member is one the model
 * declared a column for, so the bound reads that column and nothing
 * else. Without the guard the statement stops parsing every row's
 * document to discriminate a member whose column already carries it,
 * which is the whole cost of the fetch on a large series.
 */
function instantBound(ref, op, value) {
  return ref.column !== null
    ? { p: 'colCmp', op, column: ref.column, operand: { lit: value } }
    : { p: 'cmp', op, ref, operand: { lit: value } };
}

/** The same, for a bound whose value the database itself answers. */
function seekBound(ref, op, name) {
  return { p: 'colCmp', op, column: ref.column, operand: { seek: name } };
}

/** One key of the probes' own membership test, over the key column. */
function keyBound(ref, key) {
  return { p: 'colCmp', op: 'eq', column: ref.column, operand: { lit: key } };
}

/**
 * The rows whose key is one of the probes' keys: one equality, or one
 * bound membership list however many keys the probes name (a leaf per
 * key would put a long batch past the dialect's term bound, and lose
 * the narrowing it exists for).
 * @param {any} ref - the key's ref, known to carry a column
 * @param {(string | number)[]} keys
 * @returns {any}
 */
function keysBound(ref, keys) {
  return keys.length === 1 ? keyBound(ref, keys[0]) : { p: 'in', ref, operand: { list: keys } };
}

/**
 * The bounds a frozen spec implies for the collection side, as pushable
 * conjuncts. Every one of them is an IMPLIED conjunct: it narrows the
 * fetch and decides nothing, because the residual re-runs the caller's
 * own document — the whole operator — over what comes back.
 * @returns {{ preds: any[], range: any }}
 */
function impliedInstantBounds(ref, from, to) {
  const preds = [];
  if (from !== null) preds.push(instantBound(ref, 'ge', from));
  if (to !== null) preds.push(instantBound(ref, 'le', to));
  return { preds, range: { column: ref.column, from, fromOp: from === null ? null : 'ge',
    to, toOp: to === null ? null : 'le' } };
}

/**
 * The anchors an UNTOLERANCED as-of batch can ask the store for.
 *
 * A tolerance already closes both sides by arithmetic — `probes.min -
 * tolerance` is a real instant bound — so a seek would buy nothing and
 * none is built. Without one, the open side has no arithmetic bound at
 * all: the row that answers the earliest probe is the last row at or
 * before it, however far back that lies, and today the whole history
 * below the probes is fetched.
 *
 * The tight bound is the data's own. Per group, the row answering the
 * earliest probe sits at `MAX(at) WHERE at <= probes.min`; matches only
 * move FORWARD as the probe does, so no row below that group's anchor
 * can answer any probe. A single global `MAX` would be unsound — it can
 * come from a group whose anchor is later than another's, dropping that
 * other group's only candidate — so the fold is the LEAST of the
 * groups' anchors, which every group's answer is at or above. The
 * comparison stays inclusive, so rows sharing the anchor instant reach
 * the kernel and its duplicate rule decides among them.
 *
 * Ungrouped (no `by`), there is one group and the inner fold is the
 * answer. A keyed batch whose key names no column of its own gets no
 * seek: grouping by an extracted member would read the very rows the
 * anchor exists to skip.
 * @param {any} at - the instant ref, known to carry a column
 * @param {any} byRef - the key ref, or null when the batch has no key
 * @param {{ min: number, max: number, keys: any[] | null }} probes
 * @param {number | null} tolerance
 * @param {string} direction
 * @returns {any[]}
 */
function anchorSeeks(at, byRef, probes, tolerance, direction) {
  // an untyped column can answer a text where the anchor is declared a number
  if (tolerance !== null || at.wholeColumn === true) return [];
  if (byRef !== null && byRef.column === null) return [];
  const group = byRef === null ? null : byRef;
  const keys = byRef === null ? null : probes.keys;
  const kind = at.type === 'string' ? 'text' : 'number';
  /** @type {any[]} */
  const found = [];
  if (direction === 'backward' || direction === 'nearest') {
    found.push({ name: 'asof.lower', kind, ref: at,
      bound: { op: 'le', lit: probes.min }, inner: 'max', outer: 'min', group, keys });
  }
  if (direction === 'forward' || direction === 'nearest') {
    found.push({ name: 'asof.upper', kind, ref: at,
      bound: { op: 'ge', lit: probes.max }, inner: 'min', outer: 'max', group, keys });
  }
  return found;
}

/**
 * Plan a document that IS a series operator over the collection.
 *
 * The collection is one of the operator's operands, so the narrowing is
 * that operand's own `$where` plus what the frozen spec implies, and
 * the kernel — the engine running the caller's document over the
 * fetched candidates — decides. A `$resample` whose spec asks for
 * nothing a `GROUP BY` cannot do is the one exception: it is native,
 * and answers the bucket records itself.
 * @param {any} root
 * @param {any} shape
 * @returns {any} `null` when the operator is not over this collection
 */
function planSeriesOperator(root, shape) {
  const name = root.name;
  /** @type {any} */
  let operandNode = null;
  /** @type {any} */
  let probesNode = null;
  /** @type {any} */
  let spec = null;
  if (name === '$resample' || name === '$rolling') {
    operandNode = root.args[0];
    spec = root.args[1]?.kind === 'raw' ? root.args[1].value : null;
  }
  else {
    spec = root.args.length === 3
      ? (root.args[2].kind === 'raw' ? root.args[2].value : null) : {};
    // narrowing is only sound on the RIGHT side: an as-of join answers
    // once per LEFT row, so every left row is needed whatever it matches
    if (collectionOperand(root.args[1]) !== null) {
      operandNode = root.args[1];
      probesNode = root.args[0];
    }
    else if (collectionOperand(root.args[0]) !== null) {
      operandNode = root.args[0];
    }
  }
  const operand = operandNode === null ? null : collectionOperand(operandNode);
  if (operand === null || spec === null || typeof spec !== 'object') return null;

  const inner = operand.flwor === null
    ? { plan: selectPlan(shape.collection), reasons: [], prefilters: [] }
    : planFlwor(operand.flwor, shape, undefined, undefined);
  const plan = inner.plan;
  // the operand's own clauses stay the engine's: the residual runs the
  // WHOLE document, so a projection or an ordering inside it is applied
  // there and only its pushed conjuncts narrow
  plan.order = null;
  plan.window = null;

  const reasons = [];
  const prefilters = [...(inner.prefilters ?? [])];
  const at = memberRef(shape,
    spec.at !== undefined ? (singularSelector(spec.at) ?? 'at')
      : (name === '$asof' && probesNode !== null && spec.rightAt !== undefined
        ? (singularSelector(spec.rightAt) ?? 'at') : 'at'));

  if (name === '$resample') {
    const outcome = resampleBucket(spec, shape);
    if ('bucket' in outcome) {
      // native: the ladder, the aggregate and the count are the plan's
      const bucket = outcome.bucket;
      bucket.aggregates[0].empty = 'null';
      bucket.aggregates[1].empty = 'null';
      plan.bucket = bucket;
      const windowFrom = safeEpoch(spec.start);
      const windowTo = safeEpoch(spec.end);
      if (windowFrom !== null) plan.filter = conjoin(plan.filter,
        instantBound(bucket.ref, 'ge', windowFrom));
      if (windowTo !== null) plan.filter = conjoin(plan.filter,
        instantBound(bucket.ref, 'lt', windowTo));
      const facts = filterFacts(plan.filter);
      const index = seekingIndexFor(shape, bucket.ref.column, facts);
      const bound = facts.bounds.get(bucket.ref.column) ?? null;
      return {
        plan,
        native: inner.reasons.length === 0,
        reasons: inner.reasons,
        prefilters,
        series: seriesRecord({
          mode: 'native',
          operation: 'resample',
          index: index === null ? null : index.name,
          prefix: index === null ? [] : index.prefix,
          range: bound === null ? null : { column: bucket.ref.column, ...bound },
          ladder: { every: bucket.every, origin: bucket.origin, calendar: false },
          aggregates: bucket.aggregates.map((a) => a.as),
          reasons: index === null ? [seriesReason('missing-series-prefix', name)] : [],
        }),
      };
    }
    reasons.push(seriesReason(outcome.code, name));
  }
  else if (name === '$rolling') {
    reasons.push(seriesReason('rolling-refinement', name));
  }
  else {
    reasons.push(seriesReason('asof-refinement', name));
  }

  // the refinement: narrow through the index by whatever the spec makes
  // provable, and let the engine's own kernel decide over what comes back
  let range = null;
  /** @type {any[]} the anchors the plan asks the store for, for explain */
  const seeks = [];
  if (name === '$resample' && at.column !== null) {
    const from = safeEpoch(spec.start);
    const to = safeEpoch(spec.end);
    if (from !== null || to !== null) {
      if (from !== null) plan.filter = conjoin(plan.filter, instantBound(at, 'ge', from));
      if (to !== null) plan.filter = conjoin(plan.filter, instantBound(at, 'lt', to));
      range = { column: at.column, from, fromOp: from === null ? null : 'ge',
        to, toOp: to === null ? null : 'lt' };
      prefilters.push({ construct: name, via: 'columns', columns: [at.column], exact: false });
    }
  }
  else if (name === '$asof' && probesNode !== null) {
    const probes = literalInstants(probesNode, spec.leftAt, spec.by);
    const byRef = probes === null || spec.by === undefined ? null
      : memberRef(shape, /** @type {string} */ (singularSelector(spec.by)));
    if (probes !== null && at.column !== null) {
      const tolerance = toleranceMs(spec.tolerance);
      const direction = spec.direction ?? 'backward';
      let from = null;
      let to = null;
      if (direction === 'backward') {
        to = probes.max;
        if (tolerance !== null) from = probes.min - tolerance;
      }
      else if (direction === 'forward') {
        from = probes.min;
        if (tolerance !== null) to = probes.max + tolerance;
      }
      else if (tolerance !== null) {
        from = probes.min - tolerance;
        to = probes.max + tolerance;
      }
      const bounds = impliedInstantBounds(at, from, to);
      for (const pred of bounds.preds) plan.filter = conjoin(plan.filter, pred);
      if (bounds.preds.length > 0) {
        range = bounds.range;
        prefilters.push({ construct: name, via: 'columns', columns: [at.column], exact: false });
      }
      // the OPEN side, which no arithmetic over the probes can close:
      // the row answering the earliest probe may lie arbitrarily far
      // before it, so the tight bound is the data's own anchor
      for (const seek of anchorSeeks(at, byRef, probes, tolerance, direction)) {
        plan.seeks.push(seek);
        plan.filter = conjoin(plan.filter,
          seekBound(at, seek.bound.op === 'le' ? 'ge' : 'le', seek.name));
        seeks.push({ side: seek.bound.op === 'le' ? 'lower' : 'upper',
          column: at.column, probe: seek.bound.lit, op: seek.bound.op === 'le' ? 'ge' : 'le' });
        prefilters.push({ construct: name, via: 'columns', columns: [at.column], exact: false });
      }
    }
    // and the keys, whether or not the instant has a column of its own:
    // a right row whose group no left row names can match nothing, so a
    // membership test over the probes' own keys narrows and never drops
    if (probes !== null && probes.keys !== null && probes.keys.length > 0) {
      if (byRef !== null && byRef.column !== null) {
        plan.filter = conjoin(plan.filter, keysBound(byRef, probes.keys));
        prefilters.push({ construct: name, via: 'columns',
          columns: [byRef.column], exact: false });
      }
    }
  }

  const facts = filterFacts(plan.filter);
  const index = seekingIndexFor(shape, at.column, facts);
  // one code, once: an instant with no column of its own already said
  // this when the ladder refused, and saying it twice reads as two facts
  if (index === null && !reasons.some((r) => r.code === 'missing-series-prefix'))
    reasons.push(seriesReason('missing-series-prefix', name));
  const narrowed = plan.filter !== null;
  return {
    plan,
    native: false,
    reasons: [...reasons, ...inner.reasons],
    prefilters,
    series: seriesRecord({
      mode: narrowed ? 'hybrid' : 'engine',
      operation: { $resample: 'resample', $rolling: 'rolling', $asof: 'asof-join' }[name],
      index: narrowed && index !== null ? index.name : null,
      prefix: narrowed && index !== null ? index.prefix : [],
      range,
      seeks,
      refinement: { $resample: 'resampleSeries', $rolling: 'rollingSeries',
        $asof: 'asOfJoin' }[name],
      reasons,
    }),
  };
}

/**
 * The GENERAL grouping: a `$groupby` whose keys are safe member paths
 * and whose `$return` is built from those keys, the closed aggregate
 * set, literals and constructors. `null` when the shape is not one the
 * plan can rebuild — the fixed temporal bucket is tried FIRST and is a
 * different, narrower promotion; this is what the rest of the groupings
 * fall to instead of the engine.
 *
 * The rules that make it agree with the engine, each one a refusal
 * rather than an approximation:
 *
 * - a key is a singular schema-typed scalar path, so
 *   the group SQL forms is the group the engine forms. An ABSENT key is
 *   its own group, and its value comes back with its JSON type beside
 *   it, so the decoder can leave the member out exactly as the object
 *   constructor does;
 * - the `$return` may not read the binding: after a grouping the tuple
 *   variable holds the group's rows, and an object member of several
 *   items is the engine's own error, not something to reproduce;
 * - an aggregate over no values is the ENGINE's answer: `$count` and
 *   `$sum` are `0`, the other three are the empty sequence and their
 *   member is omitted. SQL answers `NULL` for all of them, so the
 *   mapping rides the plan.
 *
 * Over a join (`owners`, the bindings by slot) a key or an aggregate reads
 * the binding its path starts at, and records it; `$count` of any binding
 * is the tuple count. Only the groups in the order the engine meets them
 * are planned there: the rows of a join come out of a derived table that
 * numbers them in the nested-loop order, and an ordering, or the one form
 * of a sum that tests the group's own rows, keeps the engine.
 * @param {any} node - the FLWOR node
 * @param {number} itSlot
 * @param {any} shape
 * @param {(node: any, slot: number, shape: any) => any} [resolve]
 * @param {Map<number, any> | null} [owners]
 * @returns {any | null}
 */
function planGeneralGrouping(node, itSlot, shape, resolve = pathRef, owners = null) {
  if (owners !== null && node.orderby !== null) return null;
  const keys = [];
  /** @type {Map<number, number>} */
  const keySlot = new Map();
  for (const key of node.groupby.keys) {
    const read = groupedPath(key.expr, itSlot, shape, resolve, owners);
    if (read === null || read.ref.type === 'unknown' || !holdsOnlyScalars(read.ref, read.shape.schema))
      return null;
    keySlot.set(key.slot, keys.length);
    keys.push({ as: key.name, ref: read.ref, ...(read.binding === undefined ? {} : { binding: read.binding }) });
  }
  const aggregates = [];
  /** @type {Map<string, number>} */
  const byAggregate = new Map();
  const build = (child) => {
    assertDecidedKind(child);
    if (child.kind === 'literal') return { p: 'lit', value: child.value };
    if (child.kind === 'var' && child.external !== true && keySlot.has(child.slot))
      return { p: 'key', index: keySlot.get(child.slot) };
    if (child.kind === 'op') {
      const entry = groupAggregate(child, itSlot, shape, resolve, owners);
      if (entry === null) return null;
      // one aggregate per distinct (function, empty answer, binding, path):
      // two members that ask the same question are one SQL aggregate, a sum
      // that is `null` over no values is not the sum that is `0`, and the
      // same member of two bindings is two questions
      const identity = `${entry.fn}:${entry.empty}:${entry.binding ?? ''}:${entry.ref === null ? '' : canonicalOf(entry.ref.segments)}`;
      let index = byAggregate.get(identity);
      if (index === undefined) {
        index = aggregates.length;
        aggregates.push(entry);
        byAggregate.set(identity, index);
      }
      return { p: 'agg', index };
    }
    if (child.kind === 'object') {
      const members = [];
      for (const entry of child.entries) {
        const built = build(entry.expr);
        if (built === null) return null;
        members.push({ name: entry.name, node: built });
      }
      return { p: 'object', members };
    }
    if (child.kind === 'array') {
      const items = [];
      for (const element of child.elements) {
        const built = build(element);
        if (built === null) return null;
        items.push(built);
      }
      return { p: 'array', items };
    }
    return null;
  };
  const tree = build(node.ret);
  if (tree === null) return null;
  const order = groupOrder(node.orderby, keySlot, build);
  if (order === null) return null;
  // Group equality accepts null and boolean keys; ordering them raises
  // JQ2005. SQL ordering must not hide that engine error.
  if (order !== 'first-seen' && order.some((term) =>
    term.aggregate === undefined && !orderable(keys[term.index].ref, shape.schema))) return null;
  return { keys, aggregates, tree, order };
}

/**
 * One aggregate of a grouped `$return`, or `null`. `$count` over the
 * BINDING is the group's row count; over a path it counts the rows that
 * HAVE the member, which `COUNT(column)` does not reproduce for a
 * stored `null`.
 * @param {any} node - an `op` node
 * @param {number} itSlot
 * @param {any} shape
 * @param {(node: any, slot: number, shape: any) => any} [resolve]
 * @param {Map<number, any> | null} [owners] - the bindings of a join, by slot
 * @returns {{ as: string, fn: string, ref: any, empty: string, countsNulls?: true, binding?: string } | null}
 */
function groupAggregate(node, itSlot, shape, resolve = pathRef, owners = null) {
  // SQL's nullable sum is authored explicitly: test for any non-null
  // values, sum exactly that sequence, otherwise return a literal null.
  if (owners === null && node.name === '$if' && node.args[0]?.name === '$exists'
    && node.args[1]?.name === '$sum' && node.args[2]?.kind === 'literal' && node.args[2].value === null) {
    const filtered = (phrase) => {
      if (phrase?.kind !== 'flwor' || phrase.forBindings.length !== 1 || phrase.letBindings.length
        || phrase.groupby !== null || phrase.orderby !== null || phrase.fold !== null
        || phrase.count !== null || phrase.asChecks !== null) return null;
      const binding = phrase.forBindings[0];
      if (!isItVar(unpacked(binding.expr), itSlot) || binding.window !== null || binding.atSlot !== -1 || binding.allowingEmpty) return null;
      const ref = resolve(phrase.ret, binding.slot, shape);
      const where = phrase.where;
      if (ref === null || !isNumericType(ref.type) || admitsMixedTypes(shape.schema, ref.segments)
        || where?.name !== '$ne') return null;
      const other = resolve(where.args[0], binding.slot, shape);
      return other !== null && canonicalOf(other.segments) === canonicalOf(ref.segments)
        && where.args[1]?.kind === 'literal' && where.args[1].value === null ? ref : null;
    };
    const test = filtered(node.args[0].args[0]);
    const sum = filtered(node.args[1].args[0]);
    return test !== null && sum !== null && canonicalOf(test.segments) === canonicalOf(sum.segments)
      ? { fn: 'sum', ref: sum, empty: 'null' } : null;
  }
  if (node.name === '$count') {
    // every tuple of a group holds one row of each binding, so the count of
    // any binding is the count of the group's rows
    return (owners === null ? isItVar(node.args[0], itSlot)
      : node.args[0].kind === 'var' && node.args[0].external !== true && owners.has(node.args[0].slot))
      ? { fn: 'rows', ref: null, empty: 'zero' } : null;
  }
  const fn = AGGREGATES.get(node.name);
  if (fn === undefined || fn === 'count') return null;
  const read = groupedPath(node.args[0], itSlot, shape, resolve, owners);
  const numeric = fn === 'sum' || fn === 'avg';
  // a member of two types folds as its first in SQL, where the engine
  // refuses the mixed sequence (`JQ2001`); a column that reads a NULL as a
  // present `null` is a sequence holding one, which SQL skips and the
  // engine refuses the same way, so the statement counts those NULLs
  // beside the aggregate (`countsNulls`) and the runtime refuses the answer
  const acceptable = read !== null && (!numeric || isNumericType(read.ref.type))
    && orderable(read.ref, read.shape.schema, true);
  if (!acceptable) return null;
  // what an aggregate over NO values says, in the ENGINE's words
  return { fn, ref: read.ref, empty: fn === 'sum' ? 'zero' : 'omit',
    ...(read.ref.nullPolicy === 'null' ? { countsNulls: true } : {}),
    ...(read.binding === undefined ? {} : { binding: read.binding }) };
}

/**
 * The member path a grouping reads, resolved on the binding it starts at:
 * the one grouped binding, or — over a join, where `owners` maps each
 * binding's slot — whichever binding its root names, recorded by name.
 * `null` when the node is not a path the plan can resolve there.
 * @param {any} expr
 * @param {number} itSlot
 * @param {any} shape
 * @param {(node: any, slot: number, shape: any) => any} resolve
 * @param {Map<number, any> | null} owners
 * @returns {{ ref: any, shape: any, binding?: string } | null}
 */
function groupedPath(expr, itSlot, shape, resolve, owners) {
  if (owners === null) {
    const ref = resolve(expr, itSlot, shape);
    return ref === null ? null : { ref, shape };
  }
  const owner = expr.kind === 'path' ? owners.get(expr.rootSlot) : undefined;
  if (owner === undefined) return null;
  const ref = resolve(expr, owner.slot, owner.shape);
  return ref === null ? null : { ref, shape: owner.shape, binding: owner.name };
}

/**
 * How the groups come out: the engine's order of FIRST APPEARANCE
 * (§6.5) when nothing declares otherwise, else the group-key ordering
 * an `$orderby` asked for. Proven aggregate expressions share the
 * return's aggregate slots, including aggregates used only to order.
 * @param {any} orderby
 * @param {Map<number, number>} keySlot
 * @param {(node: any) => any} build
 * @returns {any}
 */
function groupOrder(orderby, keySlot, build) {
  if (orderby === null) return 'first-seen';
  const terms = [];
  for (const spec of orderby.specs) {
    if (spec.collation !== null || spec.collationName !== null) return null;
    const key = spec.key;
    let target;
    if (key.kind === 'var' && key.external !== true && keySlot.has(key.slot))
      target = { index: keySlot.get(key.slot) };
    else {
      // A floating sum or average accumulates in the engine's order, which
      // SQL does not reproduce (SQLite also compensates rounding), so the
      // callers keep such an aggregate in the engine by name. An integer one
      // is exact beside its guard, and counts and extrema have no
      // accumulation order: each of them decides a group's place.
      if (!['$count', '$min', '$max', '$sum', '$avg'].includes(key.name)) return null;
      const aggregate = key.kind === 'op' ? build(key) : null;
      if (aggregate?.p !== 'agg') return null;
      target = { aggregate: aggregate.index };
    }
    terms.push({ ...target, desc: spec.desc === true,
      nullsFirst: (spec.emptyGreatest === true) === (spec.desc === true) });
  }
  return terms;
}

/**
 * The tree a `$distinct` rebuilds each group's item from, out of the tree of
 * its `$return`: the same tree with every leaf read as the group key of its
 * index. Only objects, literals and leaves qualify. The members of an object
 * are named, so two rows that differ in a leaf answer different objects and
 * two that agree answer one; the elements of an array are not named and a leaf
 * that finds nothing is skipped, so rows that hold different leaves can answer
 * the same array (`[$it.a, $it.b]` of `{a: 'x'}` and of `{b: 'x'}`), which the
 * engine keeps as one item and a grouping by the leaves as two.
 * @param {any} node - a node of a projection tree
 * @returns {any | null}
 */
function distinctTree(node) {
  if (node.p === 'lit') return node;
  if (node.p === 'leaf') return { p: 'key', index: node.index };
  if (node.p !== 'object') return null;
  const members = [];
  for (const member of node.members) {
    const built = distinctTree(member.node);
    if (built === null) return null;
    members.push({ name: member.name, node: built });
  }
  return { p: 'object', members };
}

/**
 * Whether a grouping's order ranks any two groups apart: it names every
 * group key, and two groups differ in one of them. An order that does not
 * (an aggregate, a key left out, none at all) leaves ties, and tied groups
 * come out by first appearance.
 * @param {{ keys: any[], order: 'first-seen' | { index?: number, aggregate?: number }[] }} group
 * @returns {boolean}
 */
function ranksGroupsApart(group) {
  const order = group.order;
  return order !== 'first-seen' && group.keys.every((_, index) =>
    order.some((term) => term.aggregate === undefined && term.index === index));
}

/**
 * Whether a grouping is ordered by an integer sum or average: a value that
 * is exact only while the guard of its own group holds, and a statement
 * reads the guard of the groups it returns, not of those a window leaves out.
 * @param {{ aggregates: { fn: string }[], order: 'first-seen' | { aggregate?: number }[] }} group
 * @returns {boolean}
 */
function ordersByAccumulation(group) {
  return group.order !== 'first-seen' && group.order.some((term) =>
    term.aggregate !== undefined && ['sum', 'avg'].includes(group.aggregates[term.aggregate].fn));
}

/**
 * The operators a constructor may apply and still leave a row's evaluation
 * unneeded: the engine evaluates the return of every row, so a window or a
 * count that evaluates only some rows, or none, answers as the engine does
 * only where the rows it skips cannot raise. Each entry names the operand it
 * accepts, and with that operand the operator does not raise:
 * - `plain`: a literal or a singular member path (a sequence of several
 *   items raises);
 * - `string`: a singular member path that holds a string or nothing, which
 *   gives `""` (a length, `0`) where the member is absent, while a `null`, a
 *   number, an array or an object raises;
 * - `path`: a singular member path of any type.
 * @type {ReadonlyMap<string, { arity: number, operand: 'plain' | 'string' | 'path' }>}
 */
export const TOTAL_OPERATORS = new Map([
  ['$default', { arity: 2, operand: 'plain' }],
  ['$upper', { arity: 1, operand: 'string' }],
  ['$lower', { arity: 1, operand: 'string' }],
  ['$string-length', { arity: 1, operand: 'string' }],
  ['$count', { arity: 1, operand: 'path' }],
  ['$exists', { arity: 1, operand: 'path' }],
]);

/**
 * Whether a reference holds a string or nothing. The schema must type it
 * exactly `string`: the type {@link typeOfPath} reports is the first of a
 * union, and a union with `null` or a number holds what a string operator
 * raises on. The path must be one the schema places as the engine reads it:
 * a name reads the member of an object, a non-negative index the element of
 * an array (a prefix item, else `items`), and every step on another kind of
 * value reads nothing; a negative index is refused. A column must store text,
 * with no codec past `text`, and read no NULL as a present `null`
 * ({@link nullReading}); an epoch column keeps a number beside the string and
 * proves nothing here.
 * @param {any} ref
 * @param {any} schema - the schema that types the reference
 * @returns {boolean}
 */
function holdsOnlyStrings(ref, schema) {
  if (countsFromTheEnd(ref)) return false;
  if (schemaNodeAt(schema, ref.segments)?.type !== 'string' || nullReading(ref, schema) !== 'none') return false;
  switch (ref.flavor) {
    case undefined: case 'entity-doc': return true;
    case 'entity-column': return ref.storage === 'string' && (ref.codec === undefined || ref.codec === 'text');
    default: return false;
  }
}

/**
 * Whether an operator node applies one of the {@link TOTAL_OPERATORS} to
 * operands it accepts.
 * @param {any} op - an `op` node
 * @param {(node: any) => { ref: any, schema: any } | null} resolve - the
 *   singular member path a node is, with the schema that types it, or `null`
 *   when the node is no such path
 * @returns {boolean}
 */
function cannotRaise(op, resolve) {
  const rule = TOTAL_OPERATORS.get(op.name);
  if (rule === undefined || op.args.length !== rule.arity) return false;
  return op.args.every((/** @type {any} */ arg) => {
    if (arg.kind === 'literal') return rule.operand === 'plain';
    const found = resolve(arg);
    return found !== null && (rule.operand !== 'string' || holdsOnlyStrings(found.ref, found.schema));
  });
}

/**
 * Whether a `$where` conjunct cannot raise in the engine, whatever a row
 * holds. A general equality or inequality (`$eq`, `$ne`) compares any two
 * sequences — objects and arrays deeply, a `null` or an absent member as
 * itself — and raises on none, so over operands that are literals, the
 * binding, its singular member paths or operators {@link cannotRaise}
 * accepts, it is total; so are `$exists` and `$empty` of such an operand,
 * and `$and`, `$or` and `$not` of such conjuncts. An ordering raises on
 * operands it cannot order, and anything else is assumed to raise.
 * @param {any} node
 * @param {number} itSlot
 * @param {any} shape
 * @returns {boolean}
 */
function conjunctCannotRaise(node, itSlot, shape) {
  if (node.kind !== 'op') return false;
  const resolve = (/** @type {any} */ arg) => {
    const found = pathRef(arg, itSlot, shape);
    return found === null ? null : { ref: found, schema: shape.schema };
  };
  const operand = (/** @type {any} */ arg) => arg.kind === 'literal' || isItVar(arg, itSlot)
    || pathRef(arg, itSlot, shape) !== null || (arg.kind === 'op' && cannotRaise(arg, resolve));
  switch (node.name) {
    case '$and': case '$or': return node.args.every((/** @type {any} */ arg) => conjunctCannotRaise(arg, itSlot, shape));
    case '$not': return conjunctCannotRaise(node.args[0], itSlot, shape);
    case '$exists': case '$empty': return node.args.length === 1 && operand(node.args[0]);
    case '$eq': case '$ne': return node.args.length === 2 && node.args.every(operand);
    default: return false;
  }
}

/**
 * The projection TREE one `$return` compiles to, or `null` when the
 * shape is not one the plan can rebuild. Object and array constructors,
 * literals, whole collection bindings and singular member paths compose;
 * a function call, conditional or dynamic member refuses the WHOLE projection, because a projection
 * that dropped part of what the caller asked for would be a wrong
 * answer, not a partial one.
 *
 * Distinct paths are collected once: a path named twice is one fetched
 * column and two leaves pointing at it. A constant tree needs only a
 * row marker from SQL: the selection contributes its cardinality.
 *
 * With `total`, an operator it accepts stands in the tree as an opaque node.
 * Such a tree proves that a constructor yields one item per row and cannot
 * raise; it is no projection a statement can fetch, so only a caller that
 * asks the proof gets one.
 * @param {any} node - the `$return` AST node
 * @param {number} itSlot
 * @param {any} shape
 * @param {((op: any) => boolean) | undefined} [total]
 * @returns {{ tree: any, leaves: import('./algebra.js').PlanRef[] } | null}
 */
function projectionTree(node, itSlot, shape, total = undefined) {
  /** @type {import('./algebra.js').PlanRef[]} */
  const leaves = [];
  /** @type {Map<string, number>} */
  const byCanonical = new Map();
  const build = (child) => {
    assertDecidedKind(child);
    if (child.kind === 'literal') return { p: 'lit', value: child.value };
    if (child.kind === 'path' || isItVar(child, itSlot)) {
      const ref = isItVar(child, itSlot)
        ? { segments: [], type: 'unknown', column: null } : pathRef(child, itSlot, shape);
      if (ref === null) return null;
      const canonical = canonicalOf(ref.segments);
      let index = byCanonical.get(canonical);
      if (index === undefined) {
        index = leaves.length;
        leaves.push(ref);
        byCanonical.set(canonical, index);
      }
      return { p: 'leaf', index };
    }
    if (child.kind === 'object') {
      const members = [];
      for (const entry of child.entries) {
        const built = build(entry.expr);
        if (built === null) return null;
        members.push({ name: entry.name, node: built });
      }
      return { p: 'object', members };
    }
    if (child.kind === 'array') {
      const items = [];
      for (const element of child.elements) {
        const built = build(element);
        if (built === null) return null;
        items.push(built);
      }
      return { p: 'array', items };
    }
    if (total !== undefined && child.kind === 'op' && total(child)) return { p: 'opaque' };
    return null;
  };
  const tree = build(node);
  return tree === null ? null : { tree, leaves };
}

/**
 * The conjuncts of a raw `$where` as the query normalizer reads them: an
 * `$and` argument that is itself an `$and` is part of the call, so the
 * conjuncts are the leaves of the nest in order, each with the place the
 * caller wrote it.
 * @param {any} rawWhere
 * @param {string} mount - where the `$where` sits in the caller's document
 * @returns {{ fragment: any, mount: string }[]}
 */
function rawConjunctsOf(rawWhere, mount) {
  const nested = (/** @type {any} */ value) => value !== null && typeof value === 'object' && !Array.isArray(value)
    && Object.keys(value).length === 1 && Object.hasOwn(value, '$and') && Array.isArray(value.$and);
  if (!nested(rawWhere)) return [];
  /** @type {{ fragment: any, mount: string }[]} */
  const found = [];
  const pending = [{ items: rawWhere.$and, path: `${mount}/$and`, next: 0 }];
  while (pending.length > 0) {
    const top = pending[pending.length - 1];
    if (top.next >= top.items.length) {
      pending.pop();
      continue;
    }
    const index = top.next++;
    const value = top.items[index];
    const path = `${top.path}/${index}`;
    if (nested(value)) pending.push({ items: value.$and, path: `${path}/$and`, next: 0 });
    else found.push({ fragment: value, mount: path });
  }
  return found;
}

/**
 * Plan a FLWOR node into a select plan, recording refusals. When a
 * conjunct refuses native translation, the injected `udf` hook may
 * promote it to a deterministic-function predicate instead (the
 * deterministic-function hatch — the hook is supplied by the query layer, capability-gated,
 * and absent means no hatch).
 * @param {any} node
 * @param {any} shape - { collection, schema, columnByCanonical }
 * @param {any} rawFlwor - The raw FLWOR document (conjunct fragments
 *   for the hook — the AST has no unparser)
 * @param {((fragment: any, binding: string) => { name: string, key: string } | null) | undefined} udfHook
 * @returns {{ plan: import('./algebra.js').Plan,
 *   reasons: { construct: string, reason: string }[],
 *   whereFullyPushed: boolean, orderPushed: boolean,
 *   projectionNative: boolean, totalReturn: boolean, itSlot: number, itName: string | null,
 *   udfs: string[], prefilters: any[],
 *   knn: { column: string, dims: number, probe: any } | null }}
 *   `knn` is the recognized k-nearest ordering, pending the window
 *   the caller peels; its ordering is then never pushed. `totalReturn`
 *   is set when the return is not a projection the statement can fetch but
 *   is a constructor that yields one item per row and cannot raise: the
 *   rows are then its items, and a count or a window may leave rows
 *   unevaluated unless a conjunct runs as a registered function (`udfs`),
 *   which the database stops evaluating once the window is full, where the
 *   engine evaluates it on every row and raises where it does. No conjunct
 *   after one that can raise narrows the rows (`afterRaising`), so a count
 *   evaluates it on every row the engine does
 */
function planFlwor(node, shape, rawFlwor, udfHook) {
  const reasons = [];
  const plan = selectPlan(shape.collection);

  // the one recognised source shape: a single plain binding over $[*]
  // (bare or packed — one check, `isCollectionSource`, for every site)
  const binding = node.forBindings[0];
  const sourceIsCollection = node.forBindings.length === 1
    && isCollectionSource(binding?.expr)
    && binding.window === null && binding.atSlot === -1
    && binding.allowingEmpty === false;
  if (!sourceIsCollection) {
    reasons.push(refusal('$for', FLWOR_REASONS.binding));
    return { plan, reasons, whereFullyPushed: false, orderPushed: false,
      projectionNative: false, totalReturn: false, projectedTree: null,
      itSlot: -1, itName: null, udfs: [], prefilters: [],
      knn: null, bucket: null, group: null, bucketRefusal: null };
  }
  const itSlot = binding.slot;
  // the document's own name for the collection binding. The residual and
  // the UDF hatch both wrap raw fragments in a synthetic one-row query,
  // and that wrapper must bind what the fragments actually reference —
  // the name is the document's to choose, never this package's.
  const itName = binding.name;

  if (node.fold !== null) reasons.push(refusal('$fold', KIND_REASONS.let));
  if (node.letBindings.length > 0) reasons.push(refusal('$let', KIND_REASONS.let));
  if (node.asChecks !== null) reasons.push(refusal('$as', FLWOR_REASONS.as));
  // A grouping is an unconditional residual EXCEPT in one closed shape:
  // a fixed-width `$time-bucket` key with the exact aggregates, which
  // is a `GROUP BY` over integer arithmetic. The bucket then owns the
  // ordering and the projection too, so it is decided before either.
  let bucket = null;
  let group = null;
  let bucketRefusal = null;
  if (node.groupby !== null && node.fold === null && node.letBindings.length === 0
    && node.asChecks === null && node.count === null) {
    const grouped = planBucketGrouping(node, itSlot, shape);
    if ('bucket' in grouped) bucket = grouped.bucket;
    else {
      // not the fixed temporal ladder: the GENERAL grouping is the next
      // question, and only when it refuses too does the engine group
      group = planGeneralGrouping(node, itSlot, shape);
      if (group === null || group.aggregates.some(floatingAccumulation)) {
        // the engine groups — and when the grouping itself translated, a
        // floating sum or average among its aggregates is the named cause
        bucketRefusal = grouped.code;
        reasons.push(group === null ? seriesReason(grouped.code, '$groupby')
          : refusal('$groupby', PLAN_REASONS.floatingAccumulation));
        group = null;
      }
    }
  }
  else if (node.groupby !== null) reasons.push(refusal('$groupby', KIND_REASONS.let));
  if (node.count !== null) reasons.push(refusal('$count clause', KIND_REASONS.let));
  const structureClean = reasons.length === 0;
  // $let and $as run BEFORE $where in clause order: a row our pushed
  // conjunct would exclude could still make the engine throw inside a
  // binding — narrowing is only sound when nothing precedes the where
  const narrowingSound = node.letBindings.length === 0 && node.asChecks === null;

  // WHERE: a top-level $and splits — translated conjuncts push, the
  // rest stay for the residual (pure narrowing). A refused conjunct
  // may still ride the deterministic-function hatch when the hook
  // accepts its raw fragment.
  let whereFullyPushed = true;
  const udfs = [];
  const prefilters = [];
  if (!narrowingSound) whereFullyPushed = false;
  else if (node.where !== null) {
    const split = node.where.kind === 'op' && node.where.name === '$and';
    const conjuncts = split ? node.where.args : [node.where];
    const rawWhere = rawFlwor?.$where;
    const found = split ? rawConjunctsOf(rawWhere, '/$where') : [{ fragment: rawWhere, mount: '/$where' }];
    // the fragments line up with the normalized conjuncts or ride no hatch
    const rawConjuncts = found.length === conjuncts.length ? found : [];
    // the conjunct's own place in the caller's document rides the call
    // as a literal, so the shared function can report an engine error
    // where the caller wrote the fragment
    // `raises` marks a function that can raise on a row: a cursor then
    // reads the statement whole before its first item, as the engine
    // evaluates the filter on every row before it yields one
    const hatched = (/** @type {number} */ i, /** @type {boolean} */ raises) => {
      const promoted = udfHook !== undefined && rawConjuncts[i]?.fragment !== undefined
        ? udfHook(rawConjuncts[i].fragment, itName)
        : null;
      if (promoted === null) return false;
      plan.filter = conjoin(plan.filter, { p: 'udf', name: promoted.name, key: promoted.key,
        mount: rawConjuncts[i].mount, ...(raises ? { raises: true } : {}) });
      udfs.push(promoted.name);
      return true;
    };
    // The engine evaluates the conjuncts in order and stops at the first
    // false one. From the first conjunct that can raise — one the engine
    // decides, or one that runs as a registered function, unless it is
    // proven total — a later conjunct must not narrow the rows, since an
    // index seek on it never visits a row the earlier one raises on: it
    // runs as a registered function, which the statement evaluates after
    // the earlier one, or stays in the residual. A translated conjunct
    // cannot raise (one refused for a lone surrogate was translated), so
    // the ones before keep narrowing
    let raising = false;
    for (let i = 0; i < conjuncts.length; i++) {
      const construct = conjuncts[i].kind === 'op' ? conjuncts[i].name : '$where';
      let outcome = raising ? { refusal: refusal(construct, PREDICATE_REASONS.afterRaising) }
        : planPredicate(conjuncts[i], itSlot, shape);
      const translated = !('refusal' in outcome);
      if (translated && bindsLoneSurrogate(outcome.pred))
        outcome = { refusal: refusal(construct, PREDICATE_REASONS.loneSurrogate) };
      if ('refusal' in outcome) {
        const raises = !translated && !conjunctCannotRaise(conjuncts[i], itSlot, shape);
        if (raises) raising = true;
        if (!hatched(i, raises)) {
          reasons.push(outcome.refusal);
          whereFullyPushed = false;
        }
        continue;
      }
      plan.filter = conjoin(plan.filter, outcome.pred);
      prefilters.push(...outcome.prefilters);
      if (outcome.refinements.length === 0) continue;
      // an IMPLIED conjunct narrows and leaves the original predicate
      // to be decided — by the residual, or, when the hatch takes the
      // same fragment, by the engine's own operator IN the statement.
      // The composition is the ordinary index-friendly one: the cheap
      // conjunct prunes, the exact one decides, and every row the
      // exact one would RAISE on is still handed to it. Only the
      // interval promotion asks for it today; the spatial ones have
      // not been proven under the hatch and keep their residual
      raising = true;
      if (outcome.composable === true && hatched(i, true)) continue;
      for (const refinement of outcome.refinements) {
        reasons.push(refinement);
        whereFullyPushed = false;
      }
    }
  }

  // A later conjunct must not hide an earlier membership error. Retain
  // every potentially empty search row through the combined SQL filter;
  // the original WHERE then decides whether short-circuiting reaches it.
  const errorColumns = neighbourhoodErrorColumns(node.where, itSlot, shape);
  if (errorColumns.size > 0 && plan.filter !== null) {
    if (!(plan.filter.p === 'cellIn' && plan.filter.keepEmpty === true
      && errorColumns.size === 1 && errorColumns.has(plan.filter.column))) {
      plan.filter = { p: 'or', items: [plan.filter, ...[...errorColumns].map((column) =>
        ({ p: 'cellIn', column, cells: [], keepEmpty: true }))] };
    }
    whereFullyPushed = false;
    if (!reasons.some((entry) => entry.reason === SPATIAL_REASONS.membership))
      reasons.push(refusal('$geohash-neighbours', SPATIAL_REASONS.membership));
  }

  // ORDER BY: all terms or none — a partially pushed ordering is wrong.
  // A k-nearest ordering is the third outcome: not pushed, but
  // recognized for the column to pre-filter (the reason is the
  // caller's to name once the window is known)
  let orderPushed = false;
  let knn = null;
  const grouped = bucket !== null || group !== null;
  const ranked = grouped || node.orderby === null ? null
    : planKnnOrder(node.orderby, itSlot, shape, whereFullyPushed && structureClean);
  // a grouping owns its own ordering: the groups' order is the bucket's
  // or the group's, and an `$orderby` over the keys is inside it
  if (grouped) orderPushed = true;
  else if (ranked !== null) {
    if ('rank' in ranked) knn = ranked.rank;
    else reasons.push(ranked.refusal);
  }
  else if (node.orderby !== null) {
    const terms = [];
    let refused = null;
    for (const spec of node.orderby.specs) {
      const ref = pathRef(spec.key, itSlot, shape);
      if (ref === null || !orderable(ref, shape.schema)) {
        refused = refusal('$orderby', FLWOR_REASONS.orderPath);
        break;
      }
      if (spec.collation !== null || spec.collationName !== null) {
        refused = refusal('$collation', FLWOR_REASONS.collation);
        break;
      }
      terms.push({ ref, desc: spec.desc === true, emptyGreatest: spec.emptyGreatest === true });
    }
    if (refused !== null) reasons.push(refused);
    else if (terms.length > 0) {
      plan.order = terms;
      orderPushed = true;
    }
  }
  else {
    orderPushed = true; // nothing to push
  }

  // RETURN: the bare binding is the native whole-document projection,
  // and a SINGLE member path over the binding projects that path into
  // the statement (its value beside its JSON type, so a present null,
  // a boolean and an absent member each read back as the engine
  // answers them). Nothing else is projected: the residual rules that
  // make a projection safe hold only when the whole selection is
  // pushed, which the caller decides — a projection that dropped a
  // member a residual conjunct still needs would be a wrong answer
  let projectionNative = false;
  let totalReturn = false;
  /** @type {import('./algebra.js').PlanRef | null} */
  let projectedPath = null;
  /** @type {{ tree: any, leaves: any[] } | null} */
  let projectedTree = null;
  assertDecidedKind(node.ret);
  const tree = grouped || isItVar(node.ret, itSlot)
    ? null : projectionTree(node.ret, itSlot, shape);
  // a grouping IS the projection: its own tree rebuilds each group
  if (grouped) projectionNative = true;
  else if (isItVar(node.ret, itSlot)) projectionNative = true;
  else {
    const ref = pathRef(node.ret, itSlot, shape);
    if (ref !== null) {
      projectionNative = true;
      projectedPath = ref;
    }
    else if (tree !== null) {
      projectionNative = true;
      projectedTree = tree;
    }
    else {
      reasons.push(refusal('$return', FLWOR_REASONS.projection));
      // an object or array constructor is one item per row; where every
      // operator in it cannot raise, no row needs evaluating to count or to window the rows
      totalReturn = (node.ret.kind === 'object' || node.ret.kind === 'array')
        && projectionTree(node.ret, itSlot, shape, (op) => cannotRaise(op, (arg) => {
          const found = pathRef(arg, itSlot, shape);
          return found === null ? null : { ref: found, schema: shape.schema };
        })) !== null;
    }
  }

  return {
    plan,
    reasons,
    whereFullyPushed: whereFullyPushed && structureClean,
    orderPushed: orderPushed && structureClean,
    projectionNative,
    totalReturn,
    projectedPath,
    projectedTree,
    itSlot,
    itName,
    udfs,
    prefilters,
    knn,
    bucket,
    group,
    bucketRefusal,
  };
}

/**
 * Compose peeled `$subsequence` windows into one: the innermost applies
 * first, so offsets add and each outer limit is cut to what the inner
 * one left. `null` when nothing was peeled.
 * @param {{ offset: number, limit: number | null }[]} windows -
 *   outermost first, as peeled
 * @returns {{ offset: number, limit: number | null } | null}
 */
function composeWindows(windows) {
  if (windows.length === 0) return null;
  let offset = 0;
  let limit = null;
  for (let i = windows.length - 1; i >= 0; i--) {
    const w = windows[i];
    offset += w.offset;
    if (w.limit !== null) {
      limit = limit === null ? w.limit : Math.min(Math.max(limit - w.offset, 0), w.limit);
    }
    else if (limit !== null) {
      limit = Math.max(limit - w.offset, 0);
    }
  }
  return { offset, limit };
}

/**
 * Plan a whole document against one collection.
 * @param {any} document - The raw query document (kept beside the AST
 *   for residual construction — the AST has no unparser)
 * @param {any} shape - { collection, schema, columnByCanonical }
 * @param {{ udf?: (fragment: any, binding: string) => { name: string, key: string } | null }} [options]
 * @returns {{
 *   analysis: any,
 *   plan: import('./algebra.js').Plan | null,
 *   mode: 'native' | 'row' | 'set' | 'knn',
 *   reasons: { construct: string, reason: string }[],
 *   rowReturn: any,
 *   udfs: string[],
 *   prefilters: { construct: string, via: 'columns' | 'rtree',
 *     columns: string[], exact: boolean }[],
 *   series: any,
 * }}
 *   `series` is the temporal record (`series.js`) when the document
 *   asked a §8.16 question, and `null` when it did not.
 */
/**
 * The whole-collection scan a bare root wildcard means: the degenerate
 * query of every pen (`'$[*]'`, LINQ-FORMAT's "the degenerate query is a
 * JSONPath string") is planned as the `$for` phrase over the collection
 * it abbreviates — a row cursor from an open statement — instead of the
 * path barrier that would fetch the collection whole and walk it in JS.
 */
const ROOT_SCAN = Object.freeze({ $for: Object.freeze({ it: '$[*]' }), $return: '$it' });

/** The planner's complete result shape, including fresh empty collections.
 * Field order follows the published plan result; default arrays belong to this call.
 * @param {any} analysis @param {any} [plan]
 * @param {'native' | 'row' | 'set' | 'knn'} [mode]
 * @param {any[]} [reasons] @param {any} [rowReturn] @param {string[]} [udfs]
 * @param {any[]} [prefilters] @param {any} [series] */
function collectionResult(analysis, plan = null, mode = 'set', reasons = [],
  rowReturn = null, udfs = [], prefilters = [], series = null) {
  return { analysis, plan, mode, reasons, rowReturn, udfs, prefilters, series };
}

function planCollectionCore(document, shape, options = undefined) {
  if (document === '$[*]') document = ROOT_SCAN;
  const analysis = analyzeQuery(document, analyzeOptionsFor(shape?.operators));
  if (rootReads(analysis.root) < 2) return planCollectionPhrase(document, analysis, shape, options);
  // A second read of the root sees what the engine is handed as the
  // collection: the row residual hands it one row, and a pushed conjunct,
  // the deterministic-function hatch or a k-nearest cut hand it the rows
  // they keep. Planned without the hooks — nothing is registered for a
  // narrowing this plan cannot keep — and answered over the whole
  // collection unless the plan already fetches all of it.
  const planned = planCollectionPhrase(document, analysis, shape, undefined);
  if (fetchesWhole(planned)) return planned;
  return collectionResult(analysis, null, 'set', [refusal('$', PLAN_REASONS.rootRead)], null, [], [],
    planned.series === null ? null
      : { ...planned.series, mode: 'engine', index: null, prefix: [], range: null, seeks: [] });
}

/**
 * How many places a document reads the collection root: the input
 * document itself (`$`), a path over it (`$.a`, `$[0]`, `$[*]`), and an
 * absolute query inside any path filter (`$it.xs[?@ == $[0].n]` — a
 * filter names no variable, so its `$` is the input document). A phrase
 * the planner narrows reads it once, through its binding or a temporal
 * operator's operand.
 * @param {any} root - the analysis root node
 * @returns {number}
 */
function rootReads(root) {
  let reads = 0;
  // an explicit stack: a document's nesting depth is the caller's
  const pending = [root];
  while (pending.length > 0) {
    const node = pending.pop();
    switch (node.kind) {
      case 'var':
        if (node.slot === 0 && node.external !== true) reads++;
        break;
      case 'path':
        if (node.rootSlot === 0 && node.external !== true) reads++;
        reads += filterRootReads(node.segments);
        break;
      case 'object':
        for (const entry of node.entries) pending.push(entry.expr);
        break;
      case 'map':
        for (const pair of node.pairs) pending.push(pair.key, pair.value);
        break;
      case 'array':
        for (const element of node.elements) pending.push(element);
        break;
      case 'op':
      case 'call':
        for (const arg of node.args) pending.push(arg);
        break;
      case 'let':
      case 'quant':
        for (const binding of node.bindings) pending.push(binding.expr);
        pending.push(node.kind === 'let' ? node.ret : node.satisfies);
        break;
      case 'flwor':
        if (node.fold !== null) pending.push(node.fold.expr);
        for (const binding of [...node.forBindings, ...node.letBindings]) pending.push(binding.expr);
        if (node.where !== null) pending.push(node.where);
        for (const key of node.groupby?.keys ?? []) pending.push(key.expr);
        for (const spec of node.orderby?.specs ?? []) pending.push(spec.key);
        pending.push(node.ret);
        break;
      default: // a literal, or a raw operand no evaluation reads
        break;
    }
  }
  return reads;
}

/**
 * The absolute queries inside a path's filter selectors, nested filters
 * included: the segment list a path node carries is plain JSON.
 * @param {readonly any[]} segments
 * @returns {number}
 */
function filterRootReads(segments) {
  let reads = 0;
  const pending = segments.flatMap((segment) => segment.selectors
    .filter((selector) => selector.kind === 'filter').map((selector) => selector.expr));
  while (pending.length > 0) {
    const node = pending.pop();
    if (node === null || typeof node !== 'object') continue;
    if (node.kind === 'query' && node.query?.relative === false) reads++;
    for (const value of Array.isArray(node) ? node : Object.values(node)) pending.push(value);
  }
  return reads;
}

/**
 * Whether a plan hands the engine the whole collection: a set residual
 * with nothing pushed that narrows the fetch.
 * @param {any} planned
 * @returns {boolean}
 */
function fetchesWhole(planned) {
  const { mode, plan } = planned;
  return mode === 'set' && (plan === null
    || (plan.filter === null && plan.seeks.length === 0 && plan.rank === null && plan.window === null));
}

/**
 * Plan one analysed document against one collection (see
 * {@link planCollectionCore}).
 * @param {any} document @param {any} analysis @param {any} shape @param {any} options
 */
function planCollectionPhrase(document, analysis, shape, options) {
  let root = analysis.root;
  assertDecidedKind(root);

  // peel top-level $subsequence windows (0-based start[, length])
  let rawInner = document;
  const windows = [];
  while (root.kind === 'op' && root.name === '$subsequence') {
    const [inner, start, length] = root.args;
    if (start?.kind !== 'literal' || !isWindowBound(start.value)
      || (length !== undefined && (length.kind !== 'literal' || !isWindowBound(length.value)))) {
      // non-literal bounds: the whole document is a set residual
      return collectionResult(analysis, null, 'set', [refusal('$subsequence', PLAN_REASONS.windowBounds)]);
    }
    windows.push({ offset: start.value, limit: length === undefined ? null : length.value });
    root = inner;
    rawInner = Array.isArray(rawInner?.$subsequence) ? rawInner.$subsequence[0] : rawInner;
    assertDecidedKind(root);
  }

  // a top-level aggregate over a FLWOR: one of the core five, or a
  // REGISTERED aggregate the store declared pushable and the driver can
  // register (Ring 3). Only a one-operand aggregate can be declared
  // pushable at all — a SQL fold over zero rows never sees a second
  // operand, and `aggregateSpec` refuses the declaration at open — so
  // the recognizer here reads the phrase and nothing else
  const distinct = root.kind === 'op' && root.name === '$distinct';
  if (distinct) {
    root = root.args[0];
    rawInner = rawInner?.$distinct;
    assertDecidedKind(root);
  }
  let aggregate = null;
  const registeredAggregate = root.kind === 'op' && !AGGREGATES.has(root.name)
    ? (options?.aggregate?.(root.name) ?? null) : null;
  if (!distinct && root.kind === 'op' && (AGGREGATES.has(root.name) || registeredAggregate !== null)) {
    if (windows.length > 0) {
      return collectionResult(analysis, null, 'set', [refusal(root.name, PLAN_REASONS.windowedAggregate)]);
    }
    aggregate = registeredAggregate === null
      ? { name: root.name, fn: AGGREGATES.get(root.name) }
      : { name: root.name, fn: 'registered', sql: registeredAggregate.sql };
    root = root.args[0];
    rawInner = rawInner?.[aggregate.name] ?? rawInner;
    assertDecidedKind(root);
  }

  // a document that IS a series operator over the collection: the
  // operand's own conjuncts (and what the frozen spec implies) narrow
  // through the index, and the kernel decides over what comes back
  if (!distinct && aggregate === null && root.kind === 'op' && SERIES_ROOT_OPS.includes(root.name)) {
    const temporal = planSeriesOperator(root, shape);
    if (temporal !== null) {
      // a peeled `$subsequence` composes as it does everywhere — over a
      // NATIVE bucket it is a LIMIT on the ascending groups, which is
      // the same items the kernel's own window would have kept; over a
      // refinement the residual applies it, so the plan keeps none
      const window = windows.length === 0 ? null : composeWindows(windows);
      if (temporal.native && window !== null) temporal.plan.window = window;
      return collectionResult(analysis, temporal.plan, temporal.native ? 'native' : 'set',
        temporal.native ? [] : temporal.reasons, null, [], temporal.prefilters,
        temporal.series);
    }
  }

  if (root.kind !== 'flwor') {
    return collectionResult(analysis, null, 'set', [refusal(root.kind, KIND_REASONS[root.kind] ?? PLAN_REASONS.notFlwor)]);
  }

  const flwor = planFlwor(root, shape, rawInner, options?.udf);
  const { plan } = flwor;
  const fullyPushed = flwor.whereFullyPushed && flwor.orderPushed;
  // the rows are the items of a constructor that cannot raise, and a count or
  // a window may leave some unevaluated, unless a conjunct runs as a registered function
  const rowsAreItems = flwor.totalReturn && flwor.udfs.length === 0;

  if (distinct) {
    // the items are one scalar path, or the object a constructor of such paths and literals builds
    const single = flwor.projectedPath;
    const built = single !== null || flwor.projectedTree === null ? null : distinctTree(flwor.projectedTree.tree);
    const leaves = single !== null ? [single] : built === null ? [] : flwor.projectedTree.leaves;
    // rows ordered by the projected path alone leave the groups in that path's order; any other ordering
    // numbers the rows by it, and a group stands where its first row does
    const ordering = root.orderby === null ? 'none'
      : single !== null && plan.order !== null
        && plan.order.every((term) => canonicalOf(term.ref.segments) === canonicalOf(single.segments)) ? 'path' : 'rows';
    // the keys the rows are numbered by are typed as any ordering types them, which reads a negative index off
    // the items of a tuple, where the last element of a short one is a prefix item
    const numberedByEnd = ordering === 'rows' && plan.order !== null && plan.order.some((term) => countsFromTheEnd(term.ref));
    if (!fullyPushed || flwor.group !== null || flwor.bucket !== null || leaves.length === 0
      || !leaves.every((ref) => holdsOnlyScalars(ref, shape.schema)) || numberedByEnd) {
      return collectionResult(analysis, null, 'set', [refusal('$distinct', PLAN_REASONS.distinctProjection)]);
    }
    // a conjunct that runs as a registered function can go unevaluated on a row the engine evaluates and raises
    // on, so only a path alone (unordered, or ordered by itself) lowers beside one
    if ((single === null || ordering === 'rows') && flwor.udfs.length > 0) {
      return collectionResult(analysis, null, 'set', [refusal('$distinct', PLAN_REASONS.registeredFunction)]);
    }
    // DISTINCT and GROUP BY share the query language's key relation. An absent path contributes no
    // item, including under a window; an object constructor yields an item for every row.
    if (single !== null) plan.filter = conjoin(plan.filter, { p: 'typeIs', ref: single, types: [], positive: true });
    plan.group = {
      keys: leaves.map((ref) => ({ as: single !== null ? 'distinct' : canonicalOf(ref.segments), ref })),
      aggregates: [],
      tree: single !== null ? { p: 'key', index: 0 } : built,
      order: ordering === 'path' ? plan.order.map((term) => ({ index: 0, desc: term.desc,
        nullsFirst: (term.emptyGreatest === true) === (term.desc === true) })) : 'first-seen',
    };
    if (ordering !== 'rows') plan.order = null;
    plan.window = windows.length === 0 ? null : composeWindows(windows);
    return collectionResult(analysis, plan, 'native', [], null, flwor.udfs, flwor.prefilters);
  }

  if (flwor.knn !== null) {
    // the k-nearest mode: the recognized ordering under a window with
    // a finite limit, composed exactly as pushed windows are. The plan
    // keeps no order and no window — both are the engine's over the
    // cut — and the reason strict mode names is the rank itself
    const window = aggregate === null ? composeWindows(windows) : null;
    if (window !== null && window.limit !== null) {
      plan.rank = { ...flwor.knn, offset: window.offset, limit: window.limit,
        margin: KNN_MARGIN };
      return collectionResult(analysis, plan, 'knn',
        [refusal('$orderby', KNN_REASONS.rank), ...flwor.reasons], null, flwor.udfs, flwor.prefilters);
    }
    flwor.reasons.unshift(refusal('$subsequence', KNN_REASONS.window));
  }

  if (aggregate !== null) {
    // aggregates need the WHOLE selection native (their input is the
    // full sequence, not a narrowed candidate set)
    if (!fullyPushed) {
      return collectionResult(analysis, null, 'set', flwor.reasons, null, [], flwor.prefilters);
    }
    if (flwor.bucket !== null || flwor.group !== null || flwor.bucketRefusal != null) {
      if (aggregate.fn === 'count' && flwor.group !== null
        && ['object', 'array', 'lit'].includes(flwor.group.tree.p)
        && flwor.group.aggregates.every((entry) => entry.fn === 'rows')) {
        plan.group = flwor.group;
        plan.aggregate = { fn: 'count', ref: null };
        return collectionResult(analysis, plan, 'native', [], null, flwor.udfs, flwor.prefilters);
      }
      // the phrase's items are its GROUPS; a COUNT(*) over the rows
      // answered the row count for a `$count` of the groups
      return collectionResult(analysis, null, 'set', [refusal(aggregate.name, PLAN_REASONS.groupedAggregate)]);
    }
    if (aggregate.fn === 'count') {
      // a constructor that cannot raise is one item per row, so the rows are the count
      if (!flwor.projectionNative && !rowsAreItems) {
        return collectionResult(analysis, null, 'set', [refusal('$count',
          flwor.totalReturn ? PLAN_REASONS.registeredFunction : PLAN_REASONS.countProjection)]);
      }
      // a count over one member path counts the rows where the member
      // is PRESENT — an absent member yields no item — so the presence
      // test rides the WHERE and the count stays a COUNT(*)
      if (flwor.projectedPath !== null) {
        plan.filter = conjoin(plan.filter,
          { p: 'typeIs', ref: flwor.projectedPath, types: [], positive: true });
      }
      plan.aggregate = { fn: 'count', ref: null };
      return collectionResult(analysis, plan, 'native',
        [], null, flwor.udfs, flwor.prefilters,
        classifySelection(plan, shape, true));
    }
    const ref = pathRef(root.ret, flwor.itSlot, shape);
    // a registered aggregate declares `seq<number>`, so its input is the
    // numeric family too — and a path that admits `null` is refused for
    // every aggregate alike: SQL cannot tell a stored null from an
    // absent member, and the engine's sequence has an item for one and
    // not the other; so is a path of two types, which SQL reads as its
    // first where the engine refuses the mixed sequence
    const numeric = aggregate.fn === 'sum' || aggregate.fn === 'avg'
      || aggregate.fn === 'registered';
    const acceptable = ref !== null && (!numeric || isNumericType(ref.type)) && orderable(ref, shape.schema);
    if (!acceptable) {
      return collectionResult(analysis, null, 'set', [refusal(aggregate.name, PLAN_REASONS.aggregatePath)]);
    }
    if (floatingAccumulation({ fn: aggregate.fn, ref })) {
      // the engine adds, but only over the rows the pushed selection
      // keeps: the set residual's narrowed fetch, in collection order
      const narrowing = underSetMode(classifySelection(plan, shape, false));
      plan.order = null;
      plan.window = null;
      return collectionResult(analysis, plan, 'set', [refusal(aggregate.name, PLAN_REASONS.floatingAccumulation)],
        null, flwor.udfs, flwor.prefilters, narrowing);
    }
    plan.aggregate = aggregate.fn === 'registered'
      ? { fn: 'registered', ref, operator: aggregate.name, sql: aggregate.sql }
      : { fn: /** @type {any} */ (aggregate.fn), ref };
    return collectionResult(analysis, plan, 'native',
      [], null, aggregate.fn === 'registered' ? [...flwor.udfs, aggregate.sql] : flwor.udfs, flwor.prefilters,
      classifySelection(plan, shape, true));
  }

  // windows push only onto a fully pushed selection
  if (windows.length > 0 && fullyPushed) plan.window = composeWindows(windows);

  // the temporal bucket: only over a WHOLE pushed selection, because a
  // conjunct the residual would still apply would arrive after the rows
  // were already summed. A window over groups ordered by an integer sum or
  // average stays in the engine: the guard beside each sum is read on the
  // rows the statement returns, and a group the window leaves out could
  // rank elsewhere in the engine's order
  const windowedAccumulation = windows.length > 0 && flwor.group !== null
    && ordersByAccumulation(flwor.group);
  if (flwor.group !== null && fullyPushed && aggregate === null && !windowedAccumulation
    && (windows.length === 0 || ['object', 'array', 'lit'].includes(flwor.group.tree.p)
      || (flwor.group.tree.p === 'agg'
        && flwor.group.aggregates[flwor.group.tree.index].empty === 'zero'))) {
    plan.group = flwor.group;
    return collectionResult(analysis, plan, 'native', [], null, flwor.udfs, flwor.prefilters);
  }

  if (flwor.bucket !== null && fullyPushed && (windows.length === 0 || plan.window !== null)) {
    plan.bucket = flwor.bucket;
    const facts = filterFacts(plan.filter);
    const index = seekingIndexFor(shape, plan.bucket.ref.column, facts);
    const bound = facts.bounds.get(plan.bucket.ref.column) ?? null;
    return collectionResult(analysis, plan, 'native',
      [], null, flwor.udfs, flwor.prefilters,
      seriesRecord({
        mode: 'native',
        operation: 'bucket',
        index: index === null ? null : index.name,
        prefix: index === null ? [] : index.prefix,
        range: bound === null ? null : { column: plan.bucket.ref.column, ...bound },
        ladder: { every: plan.bucket.every, origin: plan.bucket.origin, calendar: false },
        aggregates: plan.bucket.aggregates.map((a) => a.as),
        reasons: index === null ? [seriesReason('missing-series-prefix', '$groupby')] : [],
      }));
  }

  // a RECOGNIZED grouping that did not lower: the engine groups, and the
  // projection branches below must not claim the shape as their own —
  // a grouping IS the projection, and answering it as one would answer
  // per row instead of per group
  const groupedResidual = flwor.group !== null || flwor.bucket !== null;
  if (groupedResidual && windows.length > 0) {
    flwor.reasons.push(refusal('$groupby', windowedAccumulation
      ? PLAN_REASONS.windowedAccumulation : PLAN_REASONS.windowedGroup));
  }

  // A window stops the statement once it is full, so a row past it never
  // meets a conjunct that runs as a registered function, which the engine
  // evaluates on every row: a window of a projection, or of a constructor
  // whose rows are its items, stays in the engine beside one, and names
  // that cause first
  const windowBesideFunction = !groupedResidual && fullyPushed && windows.length > 0
    && flwor.udfs.length > 0 && (flwor.projectionNative || flwor.totalReturn);
  if (windowBesideFunction) flwor.reasons.unshift(refusal('$subsequence', PLAN_REASONS.registeredFunction));

  if (!groupedResidual && fullyPushed && flwor.projectionNative && !windowBesideFunction
    && (windows.length === 0 || plan.window !== null)) {
    if (flwor.projectedPath !== null) {
      plan.project = { path: flwor.projectedPath };
      // A path yields no item for an absent member. Windows count the
      // projected items, so discard those rows before applying LIMIT.
      if (windows.length > 0) plan.filter = conjoin(plan.filter,
        { p: 'typeIs', ref: flwor.projectedPath, types: [], positive: true });
    }
    else if (flwor.projectedTree !== null) plan.project = flwor.projectedTree;
    return collectionResult(analysis, plan, 'native',
      [], null, flwor.udfs, flwor.prefilters,
      classifySelection(plan, shape, flwor.orderPushed));
  }

  // the row residual: everything but the projection pushed. A window rides
  // along only where the rows are the items
  if (!groupedResidual && fullyPushed && !flwor.projectionNative
    && (windows.length === 0 || rowsAreItems)) {
    const rawFlwor = rawInner;
    const name = flwor.itName ?? 'it';
    // A COMPLETE one-row document: its binding and projection travel together,
    // so callers never have to re-wrap or pair them.
    return collectionResult(analysis, plan, 'row',
      flwor.reasons, {
        $for: { [name]: '$[*]' },
        $return: [rawFlwor?.$return ?? `$${name}`],
      }, flwor.udfs, flwor.prefilters,
      flwor.bucketRefusal == null
        ? classifySelection(plan, shape, flwor.orderPushed)
        : refinedGrouping(plan, shape, flwor.bucketRefusal, '$groupby'));
  }

  // the set residual: pushed conjuncts narrow, the engine answers — so
  // a temporal selection here is never `native`, whatever index it
  // seeks through: the index narrows the fetch (hybrid) or nothing does
  // (engine), and the record follows the PLAN mode, not the index alone
  const narrowing = flwor.bucketRefusal == null
    ? underSetMode(classifySelection(plan, shape, false))
    : refinedGrouping(plan, shape, flwor.bucketRefusal, '$groupby');
  plan.order = null;
  plan.window = null;
  return collectionResult(analysis, plan, 'set', flwor.reasons, null, flwor.udfs, flwor.prefilters, narrowing);
}

/**
 * A temporal record under a set-mode plan: the database only narrows,
 * the engine answers.
 * @param {any} series - a `classifySelection` record, or null
 * @returns {any}
 */
function underSetMode(series) {
  if (series === null || series.mode !== 'native') return series;
  return { ...series, mode: series.index === null ? 'engine' : 'hybrid' };
}

/**
 * Plan a whole document against one collection. The store's registered
 * operators (Ring 2) ride in `shape.operators` — the planner recognises
 * them as vocabulary but keeps them in the residual, and names them in
 * the reasons when it does.
 * @param {any} document - The raw query document (kept beside the AST
 *   for residual construction — the AST has no unparser)
 * @param {any} shape - { collection, schema, columnByCanonical, operators? }
 * @param {{ udf?: (fragment: any) => { name: string, key: string } | null }} [options]
 * @returns {{
 *   analysis: any,
 *   plan: import('./algebra.js').Plan | null,
 *   mode: 'native' | 'row' | 'set' | 'knn',
 *   reasons: { construct: string, reason: string }[],
 *   rowReturn: any,
 *   udfs: string[],
 *   prefilters: { construct: string, via: 'columns' | 'rtree',
 *     columns: string[], exact: boolean }[],
 *   series: any,
 * }}
 */
export function planQuery(document, shape, options = undefined) {
  const peeled = peelWrappedResult(document);
  const planned = { ...planCollectionCore(peeled.document, shape, options), wrapped: peeled.wrapped };
  return prependRegisteredReason(planned, document, shape?.operators);
}

/**
 * A chain's element terminal wraps its phrase in a one-item array
 * constructor — `[<phrase>]`, the window that keeps an array-valued item
 * one item (QUERY-PEN §6) — so the document a store receives from
 * `toArray()`/`first()` is that constructor around the phrase. Read
 * through it: the phrase inside plans as it would bare, and the engines
 * answer its rows as the ONE array the constructor yields (`wrapped`),
 * which is exactly the engine's own answer for the document. Anything
 * else inside the brackets plans as itself and falls to the residual,
 * where the whole document — brackets included — runs in the engine.
 * @param {any} document
 * @returns {{ document: any, wrapped: boolean }}
 */
function peelWrappedResult(document) {
  return Array.isArray(document) && document.length === 1
    ? { document: document[0], wrapped: true }
    : { document, wrapped: false };
}

// ————— The entity document kind (one planner, two document kinds) —————

/**
 * Build the planner shape for one entity: canonical top-level paths
 * map to REAL columns (flavor `entity-column`), epoch date columns to
 * their derived integer twins (flavor `entity-epoch`), and everything
 * else stays a document path over the entity's JSONB column (the
 * phase-A guarded forms).
 * @param {any} entity - normalized entity (model.js)
 * @param {any} entityMapping - explainMapping(...).entities[name]
 * @returns {any}
 */
export function entityShape(entity, entityMapping) {
  /** @type {Map<string, any>} */
  const flavors = new Map();
  for (const column of entityMapping.columns) {
    const epoch = column.source === 'epoch(document)';
    flavors.set(canonicalOf([{ name: column.name }]), {
      column: column.physical ?? column.name,
      flavor: epoch ? 'entity-epoch' : 'entity-column',
      storage: column.storage,
      codec: column.codec,
      codecColumn: column.codec === undefined ? undefined : column,
      nullPolicy: column.null,
      format: epoch ? entity.properties.get(column.name)?.format : undefined,
      unsafe: column.nativeQuery === false || column.codec !== undefined
        && !['text', 'integer', 'number', 'boolean', 'date', 'datetime'].includes(column.codec),
    });
  }
  // an inferred foreign key has no property of its own: its column
  // stores the referenced key's type, and compares as that type does
  for (const fk of entityMapping.foreignKeys) {
    const fkCanonical = canonicalOf([{ name: fk.column }]);
    if (!flavors.has(fkCanonical))
      flavors.set(fkCanonical, { column: fk.column, flavor: 'entity-column', storage: fk.referencesType, foreignKey: true });
  }
  return {
    collection: entity.name,
    schema: entity.schema,
    columnByCanonical: new Map(),
    entityFlavors: flavors,
    columnOnly: entityMapping.document === false,
  };
}

/**
 * Resolve a singular member path on an entity binding to a flavored
 * PlanRef.
 * @param {any} node - a path AST node
 * @param {number} slot
 * @param {any} shape - from {@link entityShape}
 * @returns {any | null}
 */
export function entityPathRef(node, slot, shape) {
  const ref = pathRef(node, slot, shape);
  if (ref === null) return null;
  const canonical = canonicalOf(ref.segments);
  const flavored = shape.entityFlavors.get(canonical);
  if (flavored?.unsafe || (shape.columnOnly && flavored === undefined)) return null;
  if (flavored !== undefined) {
    return {
      ...ref,
      column: flavored.column,
      flavor: flavored.flavor,
      storage: flavored.storage,
      format: flavored.format,
      nullPolicy: flavored.nullPolicy,
      codec: flavored.codec,
      codecColumn: flavored.codecColumn,
    };
  }
  // a nested path rides the JSONB document with the phase-A guards;
  // strip nothing — jsonb_extract addresses the doc column directly
  return { ...ref, flavor: 'entity-doc' };
}

/**
 * A navigation hop: one plain FLWOR over a declared entity, correlated with
 * the bindings in `outer` by column equalities. Its `$where` is conjuncts,
 * each a correlation equality {@link crossBindingComparison} proves over
 * columns that read no NULL as a `null`, or a predicate over the hop's own
 * binding, and its `$return` is that binding
 * bare or one singular member path of it. An ordering, a `$let`, a grouping,
 * a window, a second binding or a hop out of a hop is not a hop: an inner
 * ordering can raise where a statement could not.
 * @param {any} inner - a `flwor` node
 * @param {Map<number, any>} outer - slot → the bindings the hop correlates with
 * @param {Map<string, any>} entities
 * @param {any} mapping
 * @returns {{ hop: { entity: string, binding: string, edges: any[], filter: any },
 *   binding: any, member: any } | null} `member` is the returned path
 *   node, or `null` for the binding itself
 */
function planHop(inner, outer, entities, mapping) {
  if (inner?.kind !== 'flwor' || inner.forBindings.length !== 1 || inner.groupby !== null
    || inner.fold !== null || inner.orderby !== null || inner.letBindings.length
    || inner.asChecks !== null || inner.count !== null) return null;
  const source = inner.forBindings[0];
  const entity = bindingEntity(source, entities);
  if (entity === null || source.window !== null || source.atSlot !== -1 || source.allowingEmpty) return null;
  const ret = inner.ret;
  const bare = ret.kind === 'var' && ret.external !== true && ret.slot === source.slot;
  if (!bare && !(ret.kind === 'path' && ret.external !== true && ret.rootSlot === source.slot
    && ret.singular === true)) return null;
  const shape = entityShape(entities.get(entity), mapping.entities[entity]);
  const binding = { name: source.name, slot: source.slot, entity, shape };
  const scope = new Map([...outer, [binding.slot, binding]]);
  const conjuncts = inner.where?.kind === 'op' && inner.where.name === '$and' ? inner.where.args : [inner.where];
  const edges = [];
  let filter = null;
  for (const conjunct of conjuncts) {
    if (conjunct === null) continue;
    const cross = conjunct.kind === 'op' && conjunct.name === '$eq'
      ? crossBindingComparison(conjunct, scope) : null;
    if (cross !== null && (cross.left.binding === binding || cross.right.binding === binding)) {
      edges.push({ left: { binding: cross.left.binding.name, ref: cross.left.ref },
        right: { binding: cross.right.binding.name, ref: cross.right.ref } });
      continue;
    }
    const slots = new Set(); collectBindingSlots(conjunct, scope, slots);
    if (slots.size !== 1 || !slots.has(binding.slot)) return null;
    const planned = planEntityPredicate(conjunct, binding.slot, shape);
    if ('refusal' in planned) return null;
    filter = conjoin(filter, planned.pred);
  }
  if (!edges.length) return null;
  return { hop: { entity, binding: binding.name, edges, filter }, binding, member: bare ? null : ret };
}

/**
 * Whether a hop reaches at most one row of its entity for each outer row:
 * its equalities cover every column of the entity's declared key.
 * @param {{ entity: string, binding: string, edges: any[] }} hop
 * @param {any} mapping
 * @returns {boolean}
 */
function hopKeyed(hop, mapping) {
  const keys = mapping.entities[hop.entity].keys;
  const covered = new Set(hop.edges.flatMap((edge) => [edge.left, edge.right])
    .filter((side) => side.binding === hop.binding).map((side) => canonicalOf(side.ref.segments)));
  return keys.length > 0 && keys.every((key) => covered.has(canonicalOf([{ name: key }])));
}

/**
 * A planned hop whose rows are the ones that carry the member it returns:
 * the engine's sequence has one item per row where the member is present, so
 * a test or a count of it conjoins that presence. A hop returning its binding
 * is returned as it was.
 * @param {{ hop: any, binding: any, member: any }} planned
 * @returns {{ hop: any, binding: any, member: any } | { refusal: { construct: string, reason: string } }}
 */
function hopWithPresence(planned) {
  if (planned.member === null) return planned;
  const present = planEntityPredicate({ kind: 'op', card: 1, name: '$exists', args: [planned.member] },
    planned.binding.slot, planned.binding.shape);
  return 'refusal' in present ? present
    : { ...planned, hop: { ...planned.hop, filter: conjoin(planned.hop.filter, present.pred) } };
}

/**
 * The predicate forms that read a related entity: the existence or emptiness
 * of a hop, a comparison of the member a hop returns, and a comparison of the
 * count of a hop. `null` when the node is none of them, so it plans as any
 * other predicate; a hop out of shape is refused by its reason.
 * @param {any} node - an `op` node
 * @param {any} outerBinding - the binding the predicate belongs to
 * @param {Map<string, any>} entities
 * @param {any} mapping
 * @returns {any}
 */
function planHopPredicate(node, outerBinding, entities, mapping) {
  const isHop = (arg) => arg?.kind === 'flwor';
  const isCount = (arg) => arg?.kind === 'op' && arg.name === '$count' && isHop(arg.args[0]);
  const existence = node.name === '$exists' || node.name === '$empty';
  if (!existence && !COMPARISONS.has(node.name)) return null;
  const hopAt = node.args.findIndex((arg) => isHop(arg) || isCount(arg));
  if (hopAt === -1 || node.args.some((arg, i) => i !== hopAt && (isHop(arg) || isCount(arg)))
    || (existence && !isHop(node.args[hopAt]))) return null;
  const counted = isCount(node.args[hopAt]);
  const planned = planHop(counted ? node.args[hopAt].args[0] : node.args[hopAt],
    new Map([[outerBinding.slot, outerBinding]]), entities, mapping);
  if (planned === null) return { refusal: refusal(node.name, ENTITY_REASONS.hopShape) };
  if (existence || counted) {
    const guarded = hopWithPresence(planned);
    if ('refusal' in guarded) return guarded;
    if (existence) {
      const test = { p: 'hop', hop: guarded.hop };
      return exactly(node.name === '$exists' ? test : { p: 'not', item: test });
    }
    return planHopCount(node, hopAt, guarded.hop);
  }
  // a comparison of the member the hop returns is the comparison of the
  // related rows, existentially: general comparisons raise on no operand pair
  if (planned.member === null) return null;
  const compared = planEntityPredicate(
    { ...node, args: node.args.map((arg, i) => (i === hopAt ? planned.member : arg)) },
    planned.binding.slot, planned.binding.shape);
  if ('refusal' in compared) return compared;
  return exactly({ p: 'hop', hop: { ...planned.hop, filter: conjoin(planned.hop.filter, compared.pred) } });
}

/**
 * A count compared with a number is a comparison of two numbers; a count is
 * always present, so against anything that is not a number — NaN included —
 * only `$ne` holds. The literal is the integers the comparison admits, as for
 * an integer column.
 * @param {any} node - the comparison
 * @param {number} hopAt - which operand is the count
 * @param {any} hop
 * @returns {any}
 */
function planHopCount(node, hopAt, hop) {
  const operand = operandOf(node.args[1 - hopAt]);
  if (operand === null) return null;
  if ('ext' in operand) return { refusal: refusal(node.name, ENTITY_REASONS.external) };
  const named = COMPARISONS.get(node.name);
  const op = hopAt === 1 ? ({ lt: 'gt', le: 'ge', gt: 'lt', ge: 'le' })[named] ?? named : named;
  const lit = operand.lit;
  if (typeof lit !== 'number' || Number.isNaN(lit)) return exactly({ p: 'const', value: op === 'ne' });
  const bound = integerBound(op, lit);
  if (bound === 'none' || bound === 'present') return exactly({ p: 'const', value: bound === 'present' });
  return exactly({ p: 'hopCount', hop, ...(bound ?? { op, lit }) });
}

/**
 * The projection TREE of an ENTITY query: the same closed shape a
 * collection projection composes — objects, arrays, literals and
 * singular member paths — with each leaf carrying the BINDING it reads
 * from, so the statement extracts it from that binding's alias. A leaf
 * may also read a RELATED entity — the rows a hop counts, or the one
 * member a keyed hop reaches — as a correlated subselect. The reason
 * comes back when the shape is not one the plan can rebuild. A constant
 * tree fetches a row marker, preserving the selection's cardinality.
 * With `total`, an operator it accepts stands in the tree as an opaque
 * node, as in the collection's tree: a proof for a count, never a projection.
 * @param {any} node - the `$return` AST node
 * @param {Map<number, any>} byName - binding slot → binding
 * @param {Map<string, any>} entities
 * @param {any} mapping
 * @param {((op: any) => boolean) | undefined} [total]
 * @returns {{ tree: any, leaves: any[] } | { blocked: string }}
 */
function entityProjectionTree(node, byName, entities, mapping, total = undefined) {
  const leaves = [];
  /** @type {string | null} the reason of the first hop that could not be a leaf */
  let blocked = null;
  /** @type {Map<string, number>} */
  const byCanonical = new Map();
  const build = (child) => {
    assertDecidedKind(child);
    if (child.kind === 'literal') return { p: 'lit', value: child.value };
    if (child.kind === 'op' && child.name === '$count' && child.args[0]?.kind === 'flwor') {
      // the rows of a related entity counted in the row's own statement
      const planned = planHop(child.args[0], byName, entities, mapping);
      const counted = planned === null ? null : hopWithPresence(planned);
      if (counted === null || 'refusal' in counted) {
        blocked ??= counted === null ? ENTITY_REASONS.hopShape : counted.refusal.reason;
        return null;
      }
      const index = leaves.length;
      leaves.push({ count: counted.hop });
      return { p: 'leaf', index };
    }
    if (child.kind === 'flwor') {
      // a hop read as a value: one row, or none, of the related entity
      const planned = planHop(child, byName, entities, mapping);
      if (planned === null) {
        blocked ??= ENTITY_REASONS.hopShape;
        return null;
      }
      const ref = planned.member === null ? null
        : entityPathRef(planned.member, planned.binding.slot, planned.binding.shape);
      if (ref === null || !hopKeyed(planned.hop, mapping)) {
        blocked ??= ENTITY_REASONS.hopValue;
        return null;
      }
      const index = leaves.length;
      leaves.push({ hop: planned.hop, ref });
      return { p: 'leaf', index };
    }
    if (child.kind === 'path') {
      const binding = child.external === true ? undefined : byName.get(child.rootSlot);
      if (binding === undefined) return null;
      const ref = entityPathRef(child, child.rootSlot, binding.shape);
      if (ref === null) return null;
      const identity = `${binding.name}${canonicalOf(ref.segments)}`;
      let index = byCanonical.get(identity);
      if (index === undefined) {
        index = leaves.length;
        leaves.push({ binding: binding.name, ref });
        byCanonical.set(identity, index);
      }
      return { p: 'leaf', index };
    }
    if (child.kind === 'object') {
      const members = [];
      for (const entry of child.entries) {
        const built = build(entry.expr);
        if (built === null) return null;
        members.push({ name: entry.name, node: built });
      }
      return { p: 'object', members };
    }
    if (child.kind === 'array') {
      const items = [];
      for (const element of child.elements) {
        const built = build(element);
        if (built === null) return null;
        items.push(built);
      }
      return { p: 'array', items };
    }
    if (total !== undefined && child.kind === 'op' && total(child)) return { p: 'opaque' };
    return null;
  };
  const tree = build(node);
  return tree === null ? { blocked: blocked ?? ENTITY_REASONS.projection } : { tree, leaves };
}

/**
 * The grouping an entity `$distinct` is: one key for each leaf of its return, which is one mapped column or an
 * object constructor of them and literals, and the groups in the order the engine meets them. `null` for any
 * other phrase: one with an ordering or a grouping of its own, or a return with a leaf that is no mapped column
 * of a scalar type (a document member, an epoch, a hop, a count or the binding itself) or an array.
 * @param {any} flwor - the FLWOR the `$distinct` ranges over
 * @param {any[]} bindings
 * @param {Map<number, any>} byName - the bindings, by slot
 * @param {Map<string, any>} entities
 * @param {any} mapping
 * @returns {{ group: any, leaf: { binding: string, ref: any } | null } | null} `leaf` is the one leaf a bare
 *   column return reads
 */
function planEntityDistinct(flwor, bindings, byName, entities, mapping) {
  if (flwor.groupby !== null || flwor.orderby !== null) return null;
  const built = entityProjectionTree(flwor.ret, byName, entities, mapping);
  if (!('tree' in built) || built.leaves.length === 0) return null;
  const tree = distinctTree(built.tree);
  const schemaOf = (/** @type {any} */ leaf) => bindings.find((entry) => entry.name === leaf.binding)?.shape.schema;
  if (tree === null || !built.leaves.every((/** @type {any} */ leaf) => leaf.count === undefined && leaf.hop === undefined
    && leaf.ref.flavor === 'entity-column' && !['date', 'datetime'].includes(leaf.ref.codec)
    && holdsOnlyScalars(leaf.ref, schemaOf(leaf)))) return null;
  return {
    group: { keys: built.leaves.map((/** @type {any} */ leaf) => ({ as: canonicalOf(leaf.ref.segments), ref: leaf.ref,
      ...(bindings.length > 1 ? { binding: leaf.binding } : {}) })), aggregates: [], tree, order: 'first-seen' },
    leaf: tree.p === 'key' ? built.leaves[0] : null,
  };
}

/** The family of value each storage class of a mapped column compares as in the database. */
const STORED_FAMILIES = new Map([['integer', 'number'], ['number', 'number'], ['string', 'string']]);

/**
 * The one comparison family a mapped column has — what the database
 * compares and what the engine compares — or `null` when it has none that
 * both agree on: a boolean; a column whose property is a union of kinds
 * (the schema's first type is a claim about one of them, the column stores
 * another); a column whose schema type is not the family its storage holds
 * (an `integer` over a text column); a column of no declared type, except a
 * foreign key no property declares when `undeclaredKeys` is set, which has
 * the family of the key it references, the type its column stores and the
 * type of the member the engine's documents carry for it.
 * @param {any} binding
 * @param {any} ref
 * @param {boolean} undeclaredKeys
 * @returns {'number' | 'string' | null}
 */
function columnFamily(binding, ref, undeclaredKeys) {
  if (ref === null || ref.flavor !== 'entity-column' || ref.mixed === true) return null;
  const stored = STORED_FAMILIES.get(ref.storage);
  if (stored === undefined) return null;
  if (ref.type === 'unknown') {
    return undeclaredKeys && binding.shape.entityFlavors.get(canonicalOf(ref.segments))?.foreignKey === true
      ? /** @type {'number' | 'string'} */ (stored) : null;
  }
  return (isNumericType(ref.type) ? 'number' : ref.type) === stored ? /** @type {'number' | 'string'} */ (stored) : null;
}

/**
 * A comparison whose two sides are member paths on DIFFERENT bindings,
 * as a join edge (`edge`: an equality that attaches a binding), a
 * refinement or a hop's correlation — or `null` when it is not one this
 * plan can prove. Both sides must be mapped columns of the same comparison
 * family ({@link columnFamily}): SQL compares by what a column stores, the
 * engine by JSON type, so a string column against a number column would
 * answer differently on the two sides (SQLite pairs `'1'` with `1`,
 * PostgreSQL has no such operator), and a schema that claims another kind
 * than the column holds would hide it.
 *
 * Nulls decide the rest. A column whose policy reads a NULL back as a
 * present `null` ({@link nullReading}) gives the engine a `null` it equates
 * with another and differs from every other value, where SQL does neither.
 * A column whose NULL reads back as no member gives the engine an empty
 * sequence, which compares like SQL's unknown. So an equality that
 * attaches a binding is refused only when BOTH sides can read a present
 * `null` (the engine pairs them, SQL pairs none); a refinement or a hop
 * correlation refuses any side that can read one, in either way.
 * An epoch column is refused too — it stores an integer beside a document
 * string the engine reads, and the two need not order alike across mixed
 * stored precisions.
 * @param {any} node - an `op` node whose name is a comparison
 * @param {Map<number, any>} byName - binding slot → binding
 * @param {boolean} [edge] - the equality attaches a binding: it also reads an undeclared foreign key as the key it references and admits a column that can read an absent null
 * @returns {{ op: string, left: any, right: any } | null}
 */
function crossBindingComparison(node, byName, edge = false) {
  const [left, right] = node.args;
  const leftBinding = left?.kind === 'path' ? byName.get(left.rootSlot) : undefined;
  const rightBinding = right?.kind === 'path' ? byName.get(right.rootSlot) : undefined;
  if (leftBinding === undefined || rightBinding === undefined
    || leftBinding === rightBinding) return null;
  const leftRef = entityPathRef(left, left.rootSlot, leftBinding.shape);
  const rightRef = entityPathRef(right, right.rootSlot, rightBinding.shape);
  const family = columnFamily(leftBinding, leftRef, edge);
  if (family === null || family !== columnFamily(rightBinding, rightRef, edge)) return null;
  const reads = [nullReading(leftRef, leftBinding.shape.schema), nullReading(rightRef, rightBinding.shape.schema)];
  if (edge ? reads.every((read) => read === 'present') : reads.some((read) => read !== 'none')) return null;
  return {
    op: COMPARISONS.get(node.name),
    left: { binding: leftBinding, ref: leftRef },
    right: { binding: rightBinding, ref: rightRef },
  };
}

/** An integer column holds nothing at or beyond the 64-bit edge. */
const INT64_EDGE = 2 ** 63;

/**
 * An integer column compared with a number that is not an integer of its
 * own range — a fraction, an infinity, a magnitude past 64 bits — as the
 * integers the comparison admits: `null` when the literal is such an
 * integer (it compares as it stands), `'none'` or `'present'` when no
 * integer or every integer answers, else the `le`/`ge` bound that means
 * the same (`x < 2.5` is `x <= 2`).
 * @param {string} op
 * @param {number} lit
 * @returns {null | 'none' | 'present' | { op: 'le' | 'ge', lit: number }}
 */
function integerBound(op, lit) {
  if (Number.isInteger(lit) && Math.abs(lit) < INT64_EDGE) return null;
  if (op === 'eq') return 'none';
  if (op === 'ne') return 'present';
  const above = lit >= INT64_EDGE;
  const below = lit <= -INT64_EDGE;
  if (op === 'lt' || op === 'le') return above ? 'present' : below ? 'none' : { op: 'le', lit: Math.floor(lit) };
  return below ? 'present' : above ? 'none' : { op: 'ge', lit: Math.ceil(lit) };
}

/**
 * Plan one predicate over an entity binding: the same operator
 * grammar as phase A, with entity-flavored refs. Reuses
 * {@link planPredicate} for the recognition, then re-resolves refs
 * through the flavor table.
 * @param {any} node
 * @param {number} slot
 * @param {any} shape
 * @returns {{ pred: any } | { refusal: { construct: string, reason: string } }}
 */
export function planEntityPredicate(node, slot, shape) {
  const outcome = planPredicate(node, slot, shape);
  if ('refusal' in outcome) return outcome;
  /** @type {{ construct: string, reason: string } | null} */
  let blocked = null;
  const reflavor = (pred) => {
    if (pred.p === 'and' || pred.p === 'or')
      return { ...pred, items: pred.items.map(reflavor) };
    if (pred.p === 'not') return { ...pred, item: reflavor(pred.item) };
    if (pred.p === 'refCmp') {
      // the entity emitters compare two members of one plain family; a
      // pair that needs the family dispatch of a collection stays with the
      // engine. A column whose policy reads a NULL as a present `null` can
      // hold one whatever its schema omits, and an equality or inequality
      // takes it for a value (the engine pairs two, SQL pairs none), so
      // that side has the family of null too.
      const withNull = (side) => {
        const read = shape.entityFlavors.get(canonicalOf(side.segments))?.nullPolicy;
        return read === 'null' && !side.families.includes('null') && (pred.op === 'eq' || pred.op === 'ne')
          ? { ...side, families: [...side.families, 'null'] } : side;
      };
      pred = { ...pred, left: withNull(pred.left), right: withNull(pred.right) };
      if (plainFamily(pred) === null) {
        blocked = refusal(`$${pred.op}`, PREDICATE_REASONS.joinTerritory);
        return pred;
      }
      const flavor = (ref) => reflavor({ p: 'typeIs', ref, types: [], positive: true }).ref;
      return { ...pred, left: flavor(pred.left), right: flavor(pred.right) };
    }
    if (!('ref' in pred) || pred.ref === null) return pred;
    const canonical = canonicalOf(pred.ref.segments);
    const flavored = shape.entityFlavors.get(canonical);
    if (shape.columnOnly && (flavored === undefined || flavored.unsafe)) {
      blocked = refusal('physical', PREDICATE_REASONS.physicalCodec);
      return pred;
    }
    if (flavored === undefined) {
      // externals against DOC paths are not translated here (the
      // phase-A external forms assume the collection layout)
      if ((pred.p === 'cmp' || pred.p === 'in') && 'ext' in pred.operand) {
        blocked = refusal('$eq', ENTITY_REASONS.external);
      }
      return { ...pred, ref: { ...pred.ref, flavor: 'entity-doc' } };
    }
    const ref = { ...pred.ref, column: flavored.column,
      flavor: flavored.flavor, storage: flavored.storage, format: flavored.format,
      codec: flavored.codec, codecColumn: flavored.codecColumn, nullPolicy: flavored.nullPolicy };
    if (flavored.codec === 'integer' && pred.p === 'cmp' && typeof pred.operand.lit === 'number') {
      // an integer column takes no fraction, infinity or 64-bit overflow as a
      // value of its own type (PostgreSQL refuses the statement), and holds
      // none: the comparison means the integers it admits
      const bound = integerBound(pred.op, pred.operand.lit);
      if (bound === 'none') return { p: 'const', value: false };
      if (bound === 'present') return { p: 'typeIs', ref, types: [], positive: true };
      if (bound !== null) return { ...pred, ref, op: bound.op, operand: { lit: bound.lit } };
    }
    if (flavored.flavor === 'entity-epoch' && pred.p === 'in' && 'ext' in pred.operand) {
      // an epoch member compares as its document string; an external list
      // against the document layout is not translated
      blocked = refusal('$eq', ENTITY_REASONS.external);
      return { ...pred, ref };
    }
    if (flavored.storage === 'boolean' && pred.p === 'in' && 'ext' in pred.operand) {
      // the list binds no boolean, so the column could only answer false —
      // and a `true` in the bound list must match
      blocked = refusal('$eq', ENTITY_REASONS.booleanList);
      return { ...pred, ref };
    }
    if (flavored.flavor === 'entity-epoch' && pred.p === 'cmp') {
      if ('ext' in pred.operand) {
        blocked = refusal(pred.op, ENTITY_REASONS.external);
        return { ...pred, ref };
      }
      // the plan-time instant translation: an ordering comparison
      // against a literal of the column's own family (Z-normalized
      // date-time, or a plain date on a date column) gains the ±1s
      // epoch range the emitter narrows the index with; anything else
      // simply keeps the guarded document forms — sound, unassisted
      if (pred.op !== 'ne' && typeof pred.operand.lit === 'string') {
        const lit = pred.operand.lit;
        const epoch = flavored.format === 'date'
          ? (/^\d{4}-\d{2}-\d{2}$/.test(lit) ? getEpochOfDateOnlyRFC3339(lit) : NaN)
          : (lit.includes('T') && lit.endsWith('Z') ? getEpochOfDateTimeRFC3339(lit) : NaN);
        if (typeof epoch === 'number' && Number.isFinite(epoch))
          return { ...pred, ref, epoch };
      }
    }
    return { ...pred, ref };
  };
  const pred = reflavor(outcome.pred);
  if (blocked !== null) return { refusal: blocked };
  return { pred };
}

/**
 * A FLWOR whose `$let` variables are each a bracketed hop that nothing reads
 * but `{ $count: '$g[*]' }` — the group join that counts its children —
 * counts the hop itself: the count is written in place of the variable's and
 * the `$let` dropped. Any other read of a variable, or any other `$let`,
 * leaves the FLWOR as it is.
 * @param {any} root - a `flwor` node
 * @returns {any}
 */
function inlineCountedLets(root) {
  if (root.letBindings.length === 0) return root;
  /** @type {Map<number, any>} */
  const hops = new Map();
  for (const binding of root.letBindings) {
    const expr = binding.expr;
    if (expr.kind !== 'array' || expr.elements.length !== 1 || expr.elements[0].kind !== 'flwor') return root;
    hops.set(binding.slot, expr.elements[0]);
  }
  const countedSlot = (node) => {
    const path = node.kind === 'op' && node.name === '$count' ? node.args[0] : null;
    return path?.kind === 'path' && path.external !== true && hops.has(path.rootSlot)
      && path.segments.length === 1 && path.segments[0].descendant !== true
      && path.segments[0].selectors.length === 1 && path.segments[0].selectors[0].kind === 'wildcard'
      ? path.rootSlot : -1;
  };
  let onlyCounted = true;
  /** @type {Set<number>} */
  const counted = new Set();
  const scan = (node, inLet) => {
    if (node === null || typeof node !== 'object') return;
    if (Array.isArray(node)) { for (const item of node) scan(item, inLet); return; }
    const slot = countedSlot(node);
    if (slot !== -1 && !inLet) { counted.add(slot); return; }
    if ((node.kind === 'path' && hops.has(node.rootSlot)) || (node.kind === 'var' && hops.has(node.slot))) onlyCounted = false;
    for (const [key, value] of Object.entries(node)) if (key !== 'docPath') scan(value, inLet);
  };
  scan({ ...root, letBindings: [] }, false);
  for (const hop of hops.values()) scan(hop, true);
  if (!onlyCounted || counted.size !== hops.size) return root;
  const rewrite = (node) => {
    if (node === null || typeof node !== 'object') return node;
    if (Array.isArray(node)) return node.map(rewrite);
    const slot = countedSlot(node);
    if (slot !== -1) return { ...node, args: [hops.get(slot)] };
    return Object.fromEntries(Object.entries(node).map(([key, value]) => [key, key === 'docPath' ? value : rewrite(value)]));
  };
  return rewrite({ ...root, letBindings: [] });
}

/**
 * Plan an ENTITY query document: a FLWOR whose bindings range over
 * `$.<Entity>[*]` arrays of the multi-entity root. One binding is a
 * guarded selection; two bindings joined by a key equality become an
 * INNER equijoin (exactly the engine's cross-product-plus-filter
 * semantics, which is what keeps the oracle honest). Everything else
 * is the set residual over the fetched root.
 * @param {any} document
 * @param {Map<string, any>} entities - normalized entities
 * @param {any} mapping - explainMapping result
 * @param {{ functions?: any, extensions?: any } | null} [operators] -
 *   the store's registered operators (Ring 2); recognised as vocabulary,
 *   kept in the set residual over the fetched root
 * @returns {any}
 */
function flattenEntityProjection(root) {
  const simple = (node) => node.kind === 'literal' || node.kind === 'var'
    || (node.kind === 'path' && node.singular)
    || (node.kind === 'object' && node.entries.every((e) => simple(e.expr)));
  const plain = (node) => node?.kind === 'flwor' && node.fold === null
    && node.letBindings.length === 0 && node.asChecks === null && node.count === null
    && node.groupby === null && node.limits === null;
  if (!plain(root)) return root;
  while (root.forBindings.length === 1) {
    const outer = root.forBindings[0];
    if (outer.atSlot !== -1 || outer.allowingEmpty || outer.window !== null) break;
    const inner = flattenEntityProjection(unpacked(outer.expr));
    if (!plain(inner) || inner.orderby !== null || !simple(inner.ret)
      || !['object', 'var'].includes(inner.ret.kind)) break;
    let blocked = false;
    const resolve = (projection, segments) => {
      if (!segments.length) return projection;
      if (projection.kind === 'object') {
        const [part, ...rest] = segments;
        const name = !part.descendant && part.selectors.length === 1 && part.selectors[0].kind === 'name'
          ? part.selectors[0].name : null;
        const member = projection.entries.find((e) => e.name === name);
        if (member) return resolve(member.expr, rest);
      }
      if (projection.kind === 'var' && !projection.external)
        return { kind: 'path', card: 2, name: projection.name, rootSlot: projection.slot,
          external: false, rootCard: 1, segments, singular: true, docPath: projection.docPath };
      if (projection.kind === 'path' && projection.singular)
        return { ...projection, segments: [...projection.segments, ...segments] };
      blocked = true; return projection;
    };
    const substitute = (node) => {
      if (node === null || typeof node !== 'object') return node;
      if (Array.isArray(node)) return node.map(substitute);
      if (node.kind === 'literal') return node;
      if (node.kind === 'var' && !node.external && node.slot === outer.slot) return inner.ret;
      if (node.kind === 'path' && !node.external && node.rootSlot === outer.slot) {
        if (!node.singular) { blocked = true; return node; }
        return resolve(inner.ret, node.segments);
      }
      return Object.fromEntries(Object.entries(node).map(([key, value]) => [key, substitute(value)]));
    };
    const where = substitute(root.where), ret = substitute(root.ret), orderby = substitute(root.orderby);
    if (blocked) break;
    root = { ...root, forBindings: inner.forBindings, ret, orderby,
      where: inner.where === null ? where : where === null ? inner.where
        : { kind: 'op', card: 1, name: '$and', args: [inner.where, where], docPath: root.docPath } };
  }
  return root;
}

function planEntityQueryCore(document, entities, mapping, operators) {
  const analysis = analyzeQuery(document, analyzeOptionsFor(operators));
  let root = analysis.root;
  assertDecidedKind(root);

  const referenced = [...collectEntityRoots(document, entities)];
  const residual = (construct, reason) => ({
    analysis, mode: 'set', plan: null, referenced,
    reasons: [{ construct, reason }],
  });

  // peel literal windows exactly as the collection planner does
  const windows = [];
  while (root.kind === 'op' && root.name === '$subsequence') {
    const [inner, start, length] = root.args;
    if (start?.kind !== 'literal' || !isWindowBound(start.value)
      || (length !== undefined && (length.kind !== 'literal' || !isWindowBound(length.value))))
      return residual('$subsequence', PLAN_REASONS.windowBounds);
    windows.push({ offset: start.value, limit: length === undefined ? null : length.value });
    root = inner;
    assertDecidedKind(root);
  }
  let aggregate = null;
  if (root.kind === 'op' && ['$count', '$sum', '$avg', '$min', '$max'].includes(root.name) && windows.length === 0) {
    aggregate = root.name.slice(1);
    root = root.args[0];
    assertDecidedKind(root);
  }
  // `$some`/`$every` over one entity array tests its rows: some row
  // satisfies, or no row fails to (a planned predicate is total, so its
  // negation holds exactly where it fails). It is a count of the rows the
  // test selects, answered as a boolean
  let quantifier = null;
  if (root.kind === 'quant' && aggregate === null && windows.length === 0 && root.bindings.length === 1) {
    const [source] = root.bindings;
    quantifier = root.some ? 'some' : 'every';
    aggregate = 'count';
    root = { kind: 'flwor', card: 3, fold: null, letBindings: [], asChecks: null, groupby: null,
      orderby: null, count: null, limits: null,
      forBindings: [{ ...source, atSlot: -1, allowingEmpty: false, window: null }],
      where: root.some ? root.satisfies : { kind: 'op', card: 1, name: '$not', args: [root.satisfies] },
      ret: { kind: 'var', card: 1, name: source.name, slot: source.slot, external: false } };
  }
  // a `$distinct` over a FLWOR groups the leaves of its return
  const distinct = root.kind === 'op' && root.name === '$distinct' && aggregate === null && quantifier === null;
  if (distinct) {
    root = root.args[0];
    assertDecidedKind(root);
  }
  if (root.kind !== 'flwor')
    return residual(root.kind, ENTITY_REASONS.notFlwor);
  root = flattenEntityProjection(inlineCountedLets(root));
  if (root.fold !== null || root.letBindings.length > 0 || root.asChecks !== null
    || root.count !== null)
    return residual('$let', KIND_REASONS.let);

  // bindings must each range over one entity's array
  const bindings = [];
  for (const binding of root.forBindings) {
    const sourceEntity = bindingEntity(binding, entities);
    if (sourceEntity === null
      || binding.window !== null || binding.atSlot !== -1 || binding.allowingEmpty !== false)
      return residual('$for', ENTITY_REASONS.bindingRoot);
    bindings.push({
      name: binding.name,
      slot: binding.slot,
      entity: sourceEntity,
      shape: entityShape(entities.get(sourceEntity), mapping.entities[sourceEntity]),
    });
  }
  const byName = new Map(bindings.map((binding) => [binding.slot, binding]));
  // a binding's predicates may read a related entity through a hop
  for (const binding of bindings)
    binding.shape.hop = (node) => planHopPredicate(node, binding, entities, mapping);
  const distinction = distinct ? planEntityDistinct(root, bindings, byName, entities, mapping) : null;
  if (distinct && distinction === null) return residual('$distinct', ENTITY_REASONS.distinct);
  const group = distinction !== null ? distinction.group
    : root.groupby === null ? null : aggregate === null && !windows.length
      ? planGeneralGrouping(root, bindings[0].slot, bindings[0].shape, entityPathRef,
        bindings.length > 1 ? byName : null) : null;
  if (!distinct && root.groupby !== null && group === null) return residual('$groupby', ENTITY_REASONS.projection);
  if (group && [...group.keys, ...group.aggregates].some((entry) => entry.ref && entry.ref.flavor !== 'entity-column'))
    return residual('$groupby', ENTITY_REASONS.projection);
  // Integer accumulations carry a runtime exactness proof. Floating
  // accumulations and date-codec validation need the decoded evaluator.
  if (group && [...group.keys, ...group.aggregates].some((entry) => entry.ref
    && (['date', 'datetime'].includes(entry.ref.codec) || floatingAccumulation(entry))))
    return residual('$groupby', ENTITY_REASONS.projection);
  // Groups an order leaves tied come out by first appearance: over a compound
  // physical key that is the smallest key TUPLE, which the minima of the key
  // columns taken one by one do not give. A join numbers its rows instead,
  // by every binding's identity, so its first appearance is exact.
  if (group && bindings.length === 1 && !ranksGroupsApart(group)
    && entities.get(bindings[0].entity).physical?.keys.length > 1)
    return residual('$groupby', ENTITY_REASONS.groupOrder);
  const conjuncts = root.where === null
    ? []
    : root.where.kind === 'op' && root.where.name === '$and'
      ? root.where.args
      : [root.where];

  /** Every column equality between two DIFFERENT bindings: the edges of
   * the relation graph the join order is built over. */
  const edges = [];
  /** Cross-binding comparisons that are not equalities. They REFINE a
   * match, they never make one: a binding still attaches by an
   * equality, so a range between two bindings can never be the thing
   * that turns a product into a join. */
  const refinements = [];
  const filters = new Map(bindings.map((binding) => [binding.slot, null]));
  const scopedFilters = [];
  // Boolean composition may span bindings once mandatory equijoin
  // edges establish the candidate tuples. Each leaf still has exactly
  // one owner and uses that binding's existing total predicate forms.
  const scopedPredicate = (node) => {
    if (node.kind === 'op' && (node.name === '$and' || node.name === '$or')) {
      const items = node.args.map(scopedPredicate);
      return items.some((item) => item === null) ? null
        : { p: node.name === '$and' ? 'and' : 'or', items };
    }
    if (node.kind === 'op' && node.name === '$not') {
      const item = scopedPredicate(node.args[0]);
      return item === null ? null : { p: 'not', item };
    }
    const slots = new Set();
    collectBindingSlots(node, byName, slots);
    if (slots.size !== 1) return null;
    const slot = [...slots][0];
    const binding = byName.get(slot);
    const outcome = planEntityPredicate(node, slot, binding.shape);
    return 'refusal' in outcome ? null
      : { p: 'binding', binding: binding.name, filter: outcome.pred };
  };
  const reasons = [];
  let whereFullyPushed = true;
  for (const conjunct of conjuncts) {
    // a column equality between two bindings is a join edge, whatever
    // the binding count — several between one pair simply conjoin — when
    // the database pairs the rows as the engine does; any other equality
    // is no edge, and falls to the conjunct rules below
    if (bindings.length > 1 && conjunct.kind === 'op' && conjunct.name === '$eq') {
      const edge = crossBindingComparison(conjunct, byName, true);
      if (edge !== null) {
        edges.push({ left: edge.left, right: edge.right });
        continue;
      }
    }
    // a cross-binding comparison that is not an equality: a refinement
    if (bindings.length > 1 && conjunct.kind === 'op'
      && COMPARISONS.has(conjunct.name) && conjunct.name !== '$eq') {
      const refinement = crossBindingComparison(conjunct, byName);
      if (refinement !== null) {
        refinements.push(refinement);
        continue;
      }
    }
    // otherwise the conjunct must belong wholly to ONE binding
    const slots = new Set();
    collectBindingSlots(conjunct, byName, slots);
    if (slots.size !== 1) {
      const scoped = scopedPredicate(conjunct);
      if (scoped !== null) { scopedFilters.push(scoped); continue; }
      reasons.push(refusal('$where', ENTITY_REASONS.conjunctBinding));
      whereFullyPushed = false;
      continue;
    }
    const slot = [...slots][0];
    const binding = byName.get(slot);
    const planned = planEntityPredicate(conjunct, slot, binding.shape);
    const outcome = 'refusal' in planned || !bindsLoneSurrogate(planned.pred) ? planned
      : { refusal: refusal(conjunct.kind === 'op' ? conjunct.name : '$where', PREDICATE_REASONS.loneSurrogate) };
    if ('refusal' in outcome) {
      reasons.push(outcome.refusal);
      whereFullyPushed = false;
      continue;
    }
    filters.set(slot, conjoin(filters.get(slot), outcome.pred));
  }
  // the join ORDER: start at the first binding and attach, one at a
  // time, any binding an edge connects to what is already attached.
  // A binding nothing connects would be a CARTESIAN product — the one
  // thing a nested-loop plan must never emit by accident — so a graph
  // that does not close is the residual, named
  const joins = [];
  if (bindings.length > 1) {
    const attached = new Set([bindings[0].name]);
    joins.push({ binding: bindings[0].name, on: [] });
    let progress = true;
    while (attached.size < bindings.length && progress) {
      progress = false;
      for (const binding of bindings) {
        if (attached.has(binding.name)) continue;
        const on = edges.filter((edge) =>
          (edge.left.binding === binding && attached.has(edge.right.binding.name))
          || (edge.right.binding === binding && attached.has(edge.left.binding.name)));
        if (on.length === 0) continue;
        joins.push({ binding: binding.name, on });
        attached.add(binding.name);
        progress = true;
        break;
      }
    }
    if (attached.size < bindings.length)
      return residual('$for', ENTITY_REASONS.joinKey);
    // an edge between two bindings that were BOTH already attached is a
    // further equality, not another join: it rides the later one's ON,
    // which is where a nested loop can use it. A non-equality refinement
    // rides the same place, for the same reason
    const place = (entry) => {
      const later = joins.findLast((join) =>
        join.binding === entry.left.binding.name || join.binding === entry.right.binding.name);
      later.on.push(entry);
    };
    for (const edge of edges) {
      if (!joins.some((join) => join.on.includes(edge))) place(edge);
    }
    for (const refinement of refinements) place(refinement);
  }
  else if (refinements.length > 0) {
    // one binding cannot have a cross-binding comparison; this is
    // unreachable, and the graph walk above is what makes it so
    reasons.push(refusal('$where', ENTITY_REASONS.conjunctBinding));
    whereFullyPushed = false;
  }

  // the return is one bare binding — the entity's own documents — or a
  // SHAPE the projection tree rebuilds from the bindings' members
  const retBinding = root.ret.kind === 'var' && root.ret.external !== true
    ? byName.get(root.ret.slot) : undefined;
  const built = retBinding === undefined && group === null
    ? entityProjectionTree(root.ret, byName, entities, mapping) : null;
  const projection = built !== null && 'tree' in built ? built : null;
  // a count fetches no projection: over a constructor of one item per row
  // whose operators cannot raise, the rows are the count
  const counted = built !== null && projection === null && aggregate === 'count'
    && (root.ret.kind === 'object' || root.ret.kind === 'array')
    && 'tree' in entityProjectionTree(root.ret, byName, entities, mapping, (op) => cannotRaise(op, (arg) => {
      const binding = arg.kind === 'path' && arg.external !== true ? byName.get(arg.rootSlot) : undefined;
      const found = binding === undefined ? null : entityPathRef(arg, arg.rootSlot, binding.shape);
      return found === null ? null : { ref: found, schema: binding.shape.schema };
    }));
  if (built !== null && projection === null && !counted) {
    reasons.push(refusal('$return', built.blocked));
  }
  let scalarAggregate = null;
  if (aggregate !== null && aggregate !== 'count') {
    const leaf = projection?.tree.p === 'leaf' ? projection.leaves[projection.tree.index] : null;
    if (bindings.length !== 1 || !leaf?.ref || leaf.hop !== undefined || leaf.ref.flavor !== 'entity-column'
      || !['text', 'integer', 'number'].includes(leaf.ref.codec)
      || floatingAccumulation({ fn: aggregate, ref: leaf.ref })
      || admitsMixedTypes(bindings[0].shape.schema, leaf.ref.segments))
      return residual(`$${aggregate}`, ENTITY_REASONS.scalarAggregate);
    scalarAggregate = { fn: aggregate, ref: leaf.ref };
  }
  if (projection?.tree.p === 'leaf' && !projection.leaves[projection.tree.index].count && (aggregate === 'count' || windows.length > 0)) {
    const leaf = projection.leaves[projection.tree.index];
    const present = { p: 'typeIs', ref: leaf.ref, types: [], positive: true };
    // an item exists only where the member does: for a hop leaf, where a
    // related row carries it
    const owner = leaf.hop === undefined ? bindings.find((entry) => entry.name === leaf.binding) : bindings[0];
    filters.set(owner.slot, conjoin(filters.get(owner.slot), leaf.hop === undefined ? present
      : { p: 'hop', hop: { ...leaf.hop, filter: conjoin(leaf.hop.filter, present) } }));
  }

  // a bare leaf yields an item only where its member is present, so a group of absent members is no item
  // (and no window may count it)
  if (distinction?.leaf != null) {
    const owner = bindings.find((entry) => entry.name === distinction.leaf.binding);
    filters.set(owner.slot, conjoin(filters.get(owner.slot), { p: 'typeIs', ref: distinction.leaf.ref, types: [], positive: true }));
  }

  // ordering over flavored refs of either binding
  let order = null;
  let orderPushed = true;
  if (root.orderby !== null && group === null) {
    const terms = [];
    for (const spec of root.orderby.specs) {
      // the key is a member of a binding, or the member one keyed hop
      // reaches in the related row (which has none, or one)
      let key = spec.key;
      let binding;
      let hop = null;
      let blocked = ENTITY_REASONS.order;
      if (key.kind === 'flwor') {
        const planned = planHop(key, byName, entities, mapping);
        if (planned === null) blocked = ENTITY_REASONS.hopShape;
        else if (planned.member === null || !hopKeyed(planned.hop, mapping)) blocked = ENTITY_REASONS.hopValue;
        else {
          ({ hop, binding } = planned);
          key = planned.member;
        }
      }
      else if (key.kind === 'path') binding = byName.get(key.rootSlot);
      const ref = binding === undefined ? null : entityPathRef(key, key.rootSlot, binding.shape);
      // a boolean orders in SQL and is `JQ2005` in the engine on either
      // flavor, and so does a member of two types; a document path that
      // admits null stores a present null (a COLUMN stores it absent,
      // §9.3, so a nullable column pushes)
      if (ref === null || (ref.flavor === 'entity-doc' && ref.type === 'unknown')
        || holdsBoolean(ref)
        || nullReading(ref, binding.shape.schema) === 'present'
        || admitsMixedTypes(binding.shape.schema, ref.segments)
        || spec.collation !== null || spec.collationName !== null) {
        orderPushed = false;
        reasons.push(refusal('$orderby', blocked));
        break;
      }
      terms.push({ binding, ref, hop, desc: spec.desc === true, emptyGreatest: spec.emptyGreatest === true });
    }
    if (orderPushed) order = terms;
  }

  const fullyPushed = whereFullyPushed && orderPushed
    && (retBinding !== undefined || projection !== null || group !== null || counted);
  if (!fullyPushed) {
    return { analysis, mode: 'set', plan: null, referenced, reasons };
  }
  for (const filter of scopedFilters) {
    const slot = bindings[0].slot;
    filters.set(slot, conjoin(filters.get(slot), filter));
  }

  let window = null;
  if (windows.length > 0) {
    let offset = 0;
    let limit = null;
    for (let i = windows.length - 1; i >= 0; i--) {
      const w = windows[i];
      offset += w.offset;
      if (w.limit !== null) limit = limit === null ? w.limit : Math.min(Math.max(limit - w.offset, 0), w.limit);
      else if (limit !== null) limit = Math.max(limit - w.offset, 0);
    }
    window = { offset, limit };
  }

  return {
    analysis,
    mode: 'native',
    referenced,
    reasons: [],
    plan: {
      planVersion: PLAN_VERSION,
      alg: bindings.length > 1 ? 'entity-join' : 'entity-select',
      bindings: bindings.map((binding) => ({ name: binding.name, entity: binding.entity,
        ...(entities.get(binding.entity).physical == null ? {} : {
          keys: mapping.entities[binding.entity].keys.map((key) =>
            mapping.entities[binding.entity].columns.find((c) => c.name === key).physical),
        }) })),
      // the FROM order and each binding's join conditions; `bindings`
      // stays in the DOCUMENT's order, which is the nested-loop order
      // the ORDER BY reproduces
      joins: joins.map((join) => ({
        binding: join.binding,
        on: join.on.map((edge) => ({
          op: edge.op ?? 'eq',
          left: { binding: edge.left.binding.name, column: edge.left.ref.column,
            ...(edge.left.ref.codec === undefined ? {} : { codec: edge.left.ref.codec }) },
          right: { binding: edge.right.binding.name, column: edge.right.ref.column,
            ...(edge.right.ref.codec === undefined ? {} : { codec: edge.right.ref.codec }) },
        })),
      })),
      filters: bindings.map((binding) => ({
        binding: binding.name,
        filter: filters.get(binding.slot),
      })),
      order: order === null ? null : order.map((term) => ({
        binding: term.binding.name, ref: term.ref,
        desc: term.desc, emptyGreatest: term.emptyGreatest,
        ...(term.hop === null ? {} : { hop: term.hop }),
      })),
      window,
      aggregate,
      ...(quantifier === null ? {} : { quantifier }),
      ...(scalarAggregate === null ? {} : { scalarAggregate }),
      group,
      ret: retBinding === undefined ? null : retBinding.name,
      // the projected shape, when the return is one: leaves that name
      // the binding they read from, and the tree the decoder rebuilds
      project: projection === null ? null : {
        tree: projection.tree,
        leaves: projection.leaves,
      },
    },
  };
}

/**
 * Plan an ENTITY query document (one planner, two document kinds). The
 * store's registered operators (Ring 2) are recognised as vocabulary and
 * kept in the set residual over the fetched root, named in the reasons.
 * @param {any} document
 * @param {Map<string, any>} entities - normalized entities
 * @param {any} mapping - explainMapping result
 * @param {{ functions?: any, extensions?: any } | null} [operators]
 * @returns {any}
 */
export function planEntityQuery(document, entities, mapping, operators = null) {
  const peeled = peelWrappedResult(document);
  const core = planEntityQueryCore(peeled.document, entities, mapping, operators);
  const planned = {
    ...core,
    wrapped: peeled.wrapped,
    // the entity whose documents the query yields, in EITHER mode: what
    // a tracked cursor registers, and `null` when there is nothing to
    // register — a projection, a count, a window handed over whole
    retEntity: peeled.wrapped ? null : returnedEntity(core.analysis, entities),
  };
  return prependRegisteredReason(planned, document, operators);
}

/**
 * The declared entity a `$for` binding ranges over — the array
 * `$.<Entity>[*]`, spelled exactly so — or `null` for any other source.
 * @param {any} binding - an analysed `$for` binding
 * @param {Map<string, any>} entities
 * @returns {string | null}
 */
function bindingEntity(binding, entities) {
  const source = unpacked(binding.expr);
  const name = source?.kind === 'path' && source.name === '$'
    && source.external !== true && source.segments.length === 2
    && source.segments[0].descendant !== true
    && source.segments[0].selectors.length === 1
    && source.segments[0].selectors[0].kind === 'name'
    && source.segments[1].selectors?.length === 1
    && source.segments[1].selectors[0].kind === 'wildcard'
    ? source.segments[0].selectors[0].name
    : null;
  return name !== null && entities.has(name) ? name : null;
}

/**
 * The entity whose documents a query RETURNS: under any literal
 * windows, a FLWOR whose `$return` is one bare binding over a declared
 * entity array. `null` for a projection, a count, or a binding over
 * anything else — the items are then not entity documents, and a
 * tracked cursor has nothing it may register.
 * @param {any} analysis - the engine's analysis of the document
 * @param {Map<string, any>} entities
 * @returns {string | null}
 */
function returnedEntity(analysis, entities) {
  let root = analysis.root;
  while (root.kind === 'op' && root.name === '$subsequence') root = root.args[0];
  if (root.kind !== 'flwor') return null;
  const ret = root.ret;
  if (ret.kind !== 'var' || ret.external === true) return null;
  const binding = root.forBindings.find((candidate) => candidate.slot === ret.slot);
  return binding === undefined ? null : bindingEntity(binding, entities);
}

/** Which binding slots a subtree references (via path roots). */
function collectBindingSlots(node, byName, slots) {
  if (node === null || typeof node !== 'object') return;
  if (Array.isArray(node)) {
    for (const item of node) collectBindingSlots(item, byName, slots);
    return;
  }
  if (node.kind === 'path' && byName.has(node.rootSlot)) slots.add(node.rootSlot);
  for (const key of Object.keys(node)) {
    if (key === 'docPath') continue;
    collectBindingSlots(node[key], byName, slots);
  }
}

/**
 * Every member of one root a document READS, and whether it reads a
 * root item WHOLE. This walks the ANALYSIS — the normalized AST, where
 * a path is already resolved to the binding slot it hangs off — not the
 * document text, which cannot tell the path `$it.name` from a member
 * literally called `$it.name`.
 *
 * A path that is not singular (a wildcard, a slice, a descendant) reads
 * a SUBTREE, and its longest singular prefix is what a policy sees:
 * allowing a member allows everything under it, so the prefix is the
 * honest unit. A path with no singular prefix at all, and a bare
 * reference to the binding itself, read the whole item — reported as
 * `whole` with the construct that did it, because no member list can
 * cover them and narrowing one silently would be the wrong answer.
 *
 * @param {any} root - the analysis root node
 * @param {(expr: any) => boolean} isRootSource - whether one
 *   `$for` binding ranges over the root being policed
 * @returns {{ members: { canonical: string, member: string, docPath: string }[],
 *   whole: { construct: string, docPath: string } | null }}
 */
export function collectMemberReads(root, isRootSource) {
  /** @type {Set<number>} */
  const slots = new Set();
  const walk = (node, visit) => {
    if (node === null || typeof node !== 'object') return;
    if (Array.isArray(node)) {
      for (const item of node) walk(item, visit);
      return;
    }
    visit(node);
    for (const key of Object.keys(node)) {
      if (key === 'docPath') continue;
      walk(node[key], visit);
    }
  };
  walk(root, (node) => {
    if (node.kind !== 'flwor' || !Array.isArray(node.forBindings)) return;
    for (const binding of node.forBindings) {
      if (isRootSource(binding?.expr)) slots.add(binding.slot);
    }
  });

  /** @type {Map<string, { canonical: string, member: string, docPath: string }>} */
  const members = new Map();
  /** @type {{ construct: string, docPath: string } | null} */
  let whole = null;
  const readsWhole = (construct, docPath) => {
    if (whole === null) whole = { construct, docPath: docPath ?? '$' };
  };
  walk(root, (node) => {
    if (node.external === true) return;
    if (node.kind === 'var' && slots.has(node.slot)) {
      readsWhole('$' + (node.name ?? ''), node.docPath);
      return;
    }
    if (node.kind !== 'path' || !slots.has(node.rootSlot)) return;
    /** @type {({ name: string } | { index: number })[]} */
    const segments = [];
    for (const segment of node.segments ?? []) {
      if (segment.descendant === true || segment.selectors.length !== 1) break;
      const selector = segment.selectors[0];
      if (selector.kind === 'name') segments.push({ name: selector.name });
      else if (selector.kind === 'index') segments.push({ index: selector.index });
      else break;
    }
    if (segments.length === 0) {
      readsWhole('$' + (node.name ?? ''), node.docPath);
      return;
    }
    const canonical = canonicalOf(segments);
    if (!members.has(canonical)) {
      members.set(canonical, { canonical,
        member: segments.map((segment) => ('name' in segment ? segment.name : segment.index))
          .join('.'),
        docPath: node.docPath ?? '$' });
    }
  });
  return { members: [...members.values()], whole };
}

/**
 * Whether one `$for` binding ranges over the whole collection — the one
 * spelling `$[*]`, bare or packed, that {@link collectMemberReads}
 * policies against on the collection side.
 * @param {any} expr
 * @returns {boolean}
 */
export function isRootScanSource(expr) {
  return isCollectionSource(expr);
}

/**
 * Whether one `$for` binding ranges over a named entity's array — the
 * entity-side counterpart of {@link isRootScanSource}, reading the one
 * spelling {@link entityRoot} publishes.
 * @param {string} name - a declared entity name
 * @returns {(expr: any) => boolean}
 */
export function isEntityRootSource(name) {
  return (expr) => bindingEntity({ expr }, new Map([[name, true]])) === name;
}

/**
 * The root expression an entity's rows are bound through — the ONE
 * spelling of `$.<Name>[*]`: what an entity set exposes as its `root`
 * (the hint a chain reads), and what {@link collectEntityRoots}
 * recognises in a document. Two spellings would let a handle publish a
 * root the planner does not read.
 * @param {string} name - a declared entity name
 * @returns {string}
 */
export function entityRoot(name) {
  return `$.${name}[*]`;
}

/** The entity names a document's root paths reference (`$.Name[*]`). */
export function collectEntityRoots(document, entities) {
  const found = new Set();
  // an explicit stack, not recursion: a query's depth is the caller's, and
  // a long chain nested one operand deep must not overflow the walk. The
  // children go on in reverse, so the roots are found in document order —
  // the order a plan's `referenced` reports
  const pending = [document];
  while (pending.length > 0) {
    const node = pending.pop();
    if (typeof node === 'string') {
      for (const name of entities.keys()) {
        if (node.startsWith(entityRoot(name))) {
          found.add(name);
          break;
        }
      }
    }
    else if (Array.isArray(node)) {
      for (let i = node.length - 1; i >= 0; i--) pending.push(node[i]);
    }
    else if (node !== null && typeof node === 'object') {
      const keys = Object.keys(node);
      for (let i = keys.length - 1; i >= 0; i--) pending.push(node[keys[i]]);
    }
  }
  return found;
}
